local vape = shared.vape
local loadstring = function(...)
    local Chunk, Message = loadstring(...)
    if Message and vape then
        vape:CreateNotification("Vape", `Failed to load : {Message}`, 30, "alert")
    end
    return Chunk
end
local isfile = isfile or function(File: string): boolean
    local Success, Result = pcall(function()
        return readfile(File)
    end)
    return Success and Result ~= nil and Result ~= ""
end
local function DownloadFile(FilePath: string, Func)
    if not isfile(FilePath) then
        local Success, Result = pcall(function()
            return game:HttpGet(`https://api.catvape.dev/download/src/{select(1, FilePath:gsub(`^{vape.Directory}/`, ""))}`, true)
        end)
        if not Success or Result == "404: Not Found" then
            error(Result)
        end
        if FilePath:find(".lua") then
            Result = `--This watermark is used to delete the file if its cached, remove it to make the file persist after vape updates.\n{Result}`
        end
        writefile(FilePath, Result)
    end
    return (Func or readfile)(FilePath)
end
vape.Libraries.swordtiming = loadstring(DownloadFile(`{vape.Directory}/libraries/swordtiming.lua`), "SwordTiming")()
local Run = function(Func: () -> ())
    xpcall(Func, function(Message)
        task.spawn(error, Message)
        vape:CreateNotification("Vape", `A module failed to load: {Message}`, 15, "alert")
    end)

    vape.YieldBuild()
end
local cloneref = cloneref or function(Reference: Instance)
    return Reference
