local function CreateProgressBar()
    local Frame: Frame = Instance.new("Frame")
    Frame.AnchorPoint = Vector2.new(0.5, 0)
    Frame.Position = UDim2.new(0.5, 0, 1, -200)
    Frame.Size = UDim2.new(0.2, 0, 0, 20)
    Frame.BackgroundTransparency = 0.5
    Frame.BorderSizePixel = 0
    Frame.BackgroundColor3 = Color3.new(0, 0, 0)
    Frame.Visible = false
    if vape.ThreadFix then
        setthreadidentity(8)
    end
    Frame.Parent = vape.gui

    local Fill: Frame = Instance.new("Frame")
    Fill.Size = UDim2.new(1, 0, 0, 20)
    Fill.BorderSizePixel = 0
    Fill.BackgroundColor3 = Color3.fromHSV(vape.GUIColor.Hue, vape.GUIColor.Sat, vape.GUIColor.Value)
    Fill.Parent = Frame

    local Label: TextLabel = Instance.new("TextLabel")
    Label.Font = Enum.Font.Gotham
    Label.TextStrokeTransparency = 0
    Label.TextColor3 = Color3.new(0.9, 0.9, 0.9)
    Label.TextSize = 20
    Label.Size = UDim2.fromScale(1, 1)
    Label.Position = UDim2.fromScale(0, -1)
    Label.BackgroundTransparency = 1
    Label.Parent = Frame

    local LastText, LastScale, LastColor = "", -1, nil
    return {
        Frame = Frame,
        Set = function(Remaining: number, Total: number)
            local Color: Color3 = Color3.fromHSV(vape.GUIColor.Hue, vape.GUIColor.Sat, vape.GUIColor.Value)
            if Color ~= LastColor then
                LastColor = Color
                Fill.BackgroundColor3 = Color
            end

            local Scale: number = math.clamp(Remaining / Total, 0, 1)
            if Scale ~= LastScale then
                LastScale = Scale
                Fill.Size = UDim2.new(Scale, 0, 0, 20)
            end

            local Text: string = `{string.format("%.1f", math.max(Remaining, 0))}s`
            if Text ~= LastText then
                LastText = Text
                Label.Text = Text
            end
        end
    }
end
getgenv().createProgressBar = CreateProgressBar

local function Collection(Tags, Module, CustomAdd, CustomRemove)
    Tags = typeof(Tags) ~= "table" and {Tags} or Tags
    local Objects, Indexes, Connections = {}, {}, {}

    for _, v: string in Tags do
        table.insert(Connections, CollectionService:GetInstanceAddedSignal(v):Connect(function(Object: Instance)
            if CustomAdd then
                CustomAdd(Objects, Object, v)
                return
            end
            Objects[#Objects + 1] = Object
            Indexes[Object] = #Objects
        end))
        table.insert(Connections, CollectionService:GetInstanceRemovedSignal(v):Connect(function(Object: Instance)
            if CustomRemove then
                CustomRemove(Objects, Object, v)
                return
            end
            if CustomAdd then
                local Index: number? = table.find(Objects, Object)
                if Index then
                    table.remove(Objects, Index)
                end
                return
            end

            local Index: number? = Indexes[Object]
            if Index then
                local Size: number = #Objects
                local Last = Objects[Size]
                Objects[Index] = Last
                Indexes[Last] = Index
                Objects[Size] = nil
                Indexes[Object] = nil
            end
        end))

        for _, Object: Instance in CollectionService:GetTagged(v) do
            if CustomAdd then
                CustomAdd(Objects, Object, v)
                continue
            end
            Objects[#Objects + 1] = Object
            Indexes[Object] = #Objects
        end
    end

    local function CleanFunc(self)
        for _, v: RBXScriptConnection in Connections do
            v:Disconnect()
        end
        table.clear(Connections)
        table.clear(Objects)
        table.clear(Indexes)
        table.clear(self)
    end
    if Module then
        Module:Clean(CleanFunc)
    end
    return Objects, CleanFunc
end
getgenv().collection = Collection

local function GetBestArmor(Slot: number)
    local Best, BestReduction = nil, 0

    for _, v: any in store.inventory.inventory.items do
        local Meta = v and bedwars.ItemMeta[v.itemType] or {}
        if Meta.armor and Meta.armor.slot == Slot then
            local Reduction: number = (Meta.armor.damageReductionMultiplier or 0)
            if Reduction > BestReduction then
                Best, BestReduction = v, Reduction
            end
        end
    end

    return Best
end
getgenv().getBestArmor = GetBestArmor

local function GetBow()
    local BestBow, BestBowSlot, BestBowDamage = nil, nil, 0
    for Slot: number, v: any in store.inventory.inventory.items do
        local BowMeta = bedwars.ItemMeta[v.itemType].projectileSource
        if BowMeta and table.find(BowMeta.ammoItemTypes, "arrow") then
            local BowDamage: number = bedwars.ProjectileMeta[BowMeta.projectileType("arrow")].combat.damage or 0
            if BowDamage > BestBowDamage then
                BestBow, BestBowSlot, BestBowDamage = v, Slot, BowDamage
            end
        end
    end
    return BestBow, BestBowSlot
end
getgenv().getBow = GetBow

local function MatchesList(List, Names): boolean
    for _, v: string in List do
        local Needle: string = (tostring(v):lower():gsub("[_%s]+", " "))
        if #Needle > 0 then
            for _, Name: string in Names do
                if Name then
                    Name = (tostring(Name):lower():gsub("[_%s]+", " "))
                    if Name == Needle or (` {Name}`):find(` {Needle}`, 1, true) then
                        return true
                    end
                end
            end
        end
    end
    return false
end

local function GetMageSource(ItemType: string)
    if ItemType ~= "wizard_stick" then
        return nil
    end

    local Util = bedwars.MageKitUtil
    local Elements = Util and Util.MageElementMeta
    if not Elements then
        return nil
    end

    local Chosen = Elements.BASE
    local Success, Unlocked = pcall(Util.getUnlockedMageElements, LocalPlayer)
    if Success and type(Unlocked) == "table" then
        for i: number, v: string in Unlocked do
            local Element = Elements[v] or Elements[i]
            if Element and Element.projectileSource then
                Chosen = Element
            end
        end
    end

    return Chosen and Chosen.projectileSource
end

local SophiaStaffs: {string} = {"frost_staff_3", "frost_staff_2", "frost_staff_1"}
local NextSophiaSwap: number = 0

local function GetSophiaSource(ItemType: string)
    if not table.find(SophiaStaffs, ItemType) then
        return nil
    end

    local Controller = bedwars.FrostyGunController
    if not Controller then
        return nil
    end

    if Controller.projectileMode ~= bedwars.FrostyGunMode.PROJECTILE then
        if tick() >= NextSophiaSwap and bedwars.AbilityController:canUseAbility("frosty_gun_swap", {disableBlockedAbilityAlert = true}) then
            NextSophiaSwap = tick() + 1
            bedwars.AbilityController:useAbility("frosty_gun_swap")
        end
        return nil
    end

    local Meta = bedwars.ItemMeta[ItemType]
    return Meta and Meta.projectileSource or nil
end

local function GetWhimSource(ItemType: string)
    if ItemType ~= "mage_spellbook" then
        return nil
    end

    local Util = bedwars.MageKitUtil
    local Elements = Util and Util.MageElementMeta
    if not Elements then
        return nil
    end

    local Element = bedwars.BalanceFile.MAGE_ELEMENT_CYCLE[(LocalPlayer:GetAttribute("MageElementIndex") or 0) + 1]
    local Success, Unlocked = pcall(Util.getUnlockedMageElements, LocalPlayer)
    if not Element or not Success or type(Unlocked) ~= "table" or table.find(Unlocked, Element) == nil then
        Element = "BASE"
    end

    local Meta = Elements[Element]
    return Meta and Meta.projectileSource or nil
end

local NazarWeapons: {string} = {"life_bow", "life_crossbow", "life_headhunter"}

local function GetNazarSource(ItemType: string)
    if not table.find(NazarWeapons, ItemType) then
        return nil
    end

    local Meta = bedwars.ItemMeta[ItemType]
    return Meta and Meta.projectileSource or nil
end

local function GetUmekoSource(ItemType: string)
    if not ItemType:match("^ninja_chakram_%d+$") then
        return nil
    end

    local Controller = bedwars.ChakramController
    if Controller and Controller.chakramIsLaunched then
        return nil
    end

    local Meta = bedwars.ItemMeta[ItemType]
    return Meta and Meta.projectileSource or nil
end

local function GetProjectiles(Whitelist, Sophia: boolean?, Whim: boolean?, Nazar: boolean?, Umeko: boolean?)
    local Items = {}
    for _, v: any in store.inventory.inventory.items do
        local Meta = bedwars.ItemMeta[v.itemType]
        local Kit = (Sophia and GetSophiaSource(v.itemType)) or (Whim and GetWhimSource(v.itemType)) or (Nazar and GetNazarSource(v.itemType)) or (Umeko and GetUmekoSource(v.itemType)) or nil
        local Projectile = Kit or (Meta and (Meta.projectileSource or GetMageSource(v.itemType)))
        if Projectile then
            local Ammo
            if Projectile.ammoItemTypes and #Projectile.ammoItemTypes > 0 then
                for _, Item: any in store.inventory.inventory.items do
                    if table.find(Projectile.ammoItemTypes, Item.itemType) then
                        Ammo = Item.itemType
                        break
                    end
                end
            else
                Ammo = v.itemType
            end

            if Ammo and (Kit or not Whitelist or MatchesList(Whitelist, {Ammo, v.itemType, Meta.displayName})) then
                table.insert(Items, {
                    v,
                    Ammo,
                    Projectile.projectileType(Ammo),
                    Projectile
                })
            end
        end
    end

    return Items
end
getgenv().getProjectiles = GetProjectiles

local function GetFacingEntity(EntitySettings)
    if not Entity.isAlive then
        return nil
    end

    local RootPart: BasePart = Entity.character.RootPart
    local Origin: Vector3 = EntitySettings.Origin or RootPart.Position
    local Facing: Vector3 = RootPart.CFrame.LookVector * Vector3.new(1, 0, 1)
    local Cone: number = math.rad((EntitySettings.Angle or 120) / 2)
    EntitySettings.Angle = nil
    EntitySettings.Origin = Origin

    for _, v: any in Entity.AllPosition(EntitySettings) do
        local Delta: Vector3 = (v.RootPart.Position - Origin) * Vector3.new(1, 0, 1)
        if Facing.Magnitude == 0 or Delta.Magnitude == 0 or math.acos(math.clamp(Facing.Unit:Dot(Delta.Unit), -1, 1)) <= Cone then
            return v
        end
    end
    return nil
end
getgenv().getFacingEntity = GetFacingEntity

local function SolveProjectile(Origin: Vector3, Speed: number, Gravity: number, Target)
    return Prediction.SolveTrajectory(Origin, Speed, Gravity, Target.RootPart.Position, Target.RootPart.AssemblyLinearVelocity, workspace.Gravity, Target.HipHeight, Target.Jumping and 42.6 or nil, nil, Target.Humanoid.FloorMaterial == Enum.Material.Air or math.abs(Target.RootPart.AssemblyLinearVelocity.Y) > 0.01, Target.RootPart.Position, Target.RootPart, nil, true)
end

local function WatchProjectile(RefId: string, Origin: Vector3, Velocity: Vector3, Gravity: number, Target, Lifetime: number?)
    local Character: Model? = Target and Target.Character
    if not Character or Velocity.Magnitude <= 0 then
        return
    end

    local Overlap: OverlapParams = OverlapParams.new()
    Overlap.FilterType = Enum.RaycastFilterType.Include
    Overlap.FilterDescendantsInstances = {Character}
    local Box: Vector3 = Vector3.new(3, 1, 3)
    local Drop: Vector3 = Vector3.new(0, -Gravity, 0)
    local Steps: number = math.clamp(math.ceil(Velocity.Magnitude / 170), 1, 16)
    local Started: number = os.clock()
    local Last: Vector3 = Origin
    local Watcher: RBXScriptConnection
    Watcher = RunService.Heartbeat:Connect(function()
        local Elapsed: number = os.clock() - Started
        if Elapsed > (Lifetime or 2) or not Character.Parent then
            Watcher:Disconnect()
            return
        end

        local Position: Vector3 = Origin + Velocity * Elapsed + Drop * (0.5 * Elapsed * Elapsed)
        for Step: number = 1, Steps do
            if #workspace:GetPartBoundsInBox(CFrame.new(Last:Lerp(Position, Step / Steps)), Box, Overlap) > 0 then
                Watcher:Disconnect()
                bedwars.Handler:Get("ProjectileHit"):Fire("SendToServer", RefId, Character)
                return
            end
        end

        if store.airRay and workspace:Raycast(Last, Position - Last, store.airRay) then
            Watcher:Disconnect()
            return
        end
        Last = Position
    end)
end
getgenv().watchProjectile = WatchProjectile

local ArcParams: RaycastParams = RaycastParams.new()
ArcParams.FilterType = Enum.RaycastFilterType.Exclude

local function FireProjectile(Item, Ammo: string, Projectile: string, Target): boolean
    local Meta = bedwars.ProjectileMeta[Projectile]
    if not Meta then
        return false
    end

    local Origin: Vector3 = Entity.character.RootPart.Position
    local Speed, Gravity = Meta.launchVelocity, Meta.gravitationalAcceleration or 196.2
    local Solution = SolveProjectile(Origin, Speed, Gravity, Target)
    if not Solution then
        return false
    end

    local ShootPosition: Vector3 = (CFrame.new(Origin, Solution) * CFrame.new(Vector3.new(-bedwars.BowConstantsTable.RelX, -bedwars.BowConstantsTable.RelY, -bedwars.BowConstantsTable.RelZ))).Position
    local Aim, _, Flight = SolveProjectile(ShootPosition, Speed, Gravity, Target)
    Aim = Aim or Solution
    local Velocity, Id = CFrame.lookAt(ShootPosition, Aim).LookVector * Speed, bedwars.IdUtil.generateId(8)
    ArcParams.FilterDescendantsInstances = {LocalPlayer.Character, Camera}
    if Flight and not Prediction.IsTrajectoryClear(ShootPosition, Velocity, Gravity, Flight, ArcParams, Target.Character) then
        return false
    end
    bedwars.Handler:Get("ProjectileFire"):Fire("CallServerAsync",
        Item.tool,
        Ammo,
        Projectile,
        ShootPosition,
        Origin,
        Velocity,
        Id,
        bedwars.getShotData(Item.itemType),
        workspace:GetServerTimeNow() - 0.045
    ):andThen(function(Result)
        if type(Result) == "table" and Result.accepted and Result.model then
            Result.model.Parent = ReplicatedStorage
        end
    end)
    WatchProjectile(Id, ShootPosition, Velocity, Gravity, Target, Meta.lifetimeSec)
    Prediction.trackShot(Target.RootPart)
    return true
end
getgenv().fireProjectile = FireProjectile

