local function HotbarSwitch(Slot: number?): boolean
    if not Slot then
        return false
    end

    if not canDebug then
        local Entry = store.inventory.hotbar and store.inventory.hotbar[Slot + 1]
        local Tool: Tool? = Entry and Entry.item and Entry.item.tool
        if not Tool then
            return false
        end

        local Visual = vape.Libraries.cheatengine and vape.Libraries.cheatengine.HotbarVisual
        local Real: number? = Visual and Visual.GetSlot(Tool)
        if Real then
            Visual.Select(Real)
            local Deadline: number = tick() + 0.3
            repeat
                task.wait()
            until store.hand.tool == Tool or tick() > Deadline
            if store.hand.tool ~= Tool then
                SwitchItem(Tool, 0)
            end

            return true
        end

        return SwitchItem(Tool, 0) == true
    end

    if store.inventory.hotbarSlot ~= Slot then
        bedwars.Store:dispatch({
            type = "InventorySelectHotbarSlot",
            slot = Slot
        })
        VapeEvents.InventoryChanged.Event:Wait()
        return true
    end
    return false
end
