                        for Attribute: string in Player.Character:GetAttributes() do
                            if Attribute:find("StatusEffect_") and not Attribute:find("_stacks") then
                                local Name = bedwars.StatusEffectMeta[({Attribute:gsub("StatusEffect_", "")})[1]]
                                if bedwars.StatusEffectMeta[Name] then
                                    Name = bedwars.StatusEffectMeta[Name]
                                    for Tier: number = 1, 3 do
                                        Name = Name:gsub(`_{Tier}`, "")
                                    end

                                    if bedwars.EnchantMeta[Name] then
                                        return bedwars.EnchantMeta[Name].image
                                    end
                                end
                            end
                        end
                    end
                    return nil
                end,
            }
        end
    })
    getgenv().store = store
    getgenv().bedwars = bedwars

    if canDebug then
        local Shop: any = require(ReplicatedStorage.TS.games.bedwars.shop["bedwars-shop"]).BedwarsShop
        local ShopUtil: any = require(ReplicatedStorage.TS.shop["shop-util"]).ShopUtil
        local OldSuperiorItems: (...any) -> ...any = ShopUtil.getAllSuperiorItems
        local OldOwnsSuperiorItem: (...any) -> ...any = ShopUtil.ownsSuperiorItem
        local ShopItems: {[string]: any}?

        local function ClearShopItems()
            ShopItems = nil
        end

        local function GetSuperiorItems(self, Player: Player, ShopItem: any): {string}
            if Player ~= LocalPlayer then
                return OldSuperiorItems(self, Player, ShopItem)
            end
            if not ShopItem or not ShopItem.superiorItems then
                return {}
            end
            if not ShopItems then
                ShopItems = {}
                for _, v: any in Shop.getShop(Player) do
                    ShopItems[v.itemType] = v
                end
            end

            local Pending: {string} = table.clone(ShopItem.superiorItems)
            local Seen: {[string]: boolean} = {}
            local Result: {string} = {}
            while #Pending > 0 do
                local ItemType: string = table.remove(Pending)
                if Seen[ItemType] then
                    continue
                end
                Seen[ItemType] = true
                table.insert(Result, ItemType)
                local Item: any = ShopItems[ItemType]
                if Item and Item.superiorItems then
                    for _, v: string in Item.superiorItems do
                        if not Seen[v] then
                            table.insert(Pending, v)
                        end
                    end
                end
            end
            return Result
        end

        local function OwnsSuperiorItem(self, Player: Player, ShopItem: any): boolean
            if Player ~= LocalPlayer then
                return OldOwnsSuperiorItem(self, Player, ShopItem)
            end

            local SuperiorItems: {string} = self:getAllSuperiorItems(Player, ShopItem)
            for _, v: {string} in {Shop.Pickaxes, Shop.Axes} do
                local Tier: number? = table.find(v, ShopItem.itemType)
                if Tier then
                    for i: number = Tier + 1, #v do
                        table.insert(SuperiorItems, v[i])
                    end
                    break
                end
            end
            if #SuperiorItems == 0 then
                return false
            end

            local Amounts: {[string]: number} = {}
            local Seen: {[Instance]: boolean} = {}
            for _, v: any in InventoryUtil.getInventory(Player).items do
                if not Seen[v.tool] then
                    Seen[v.tool] = true
                    Amounts[v.itemType] = (Amounts[v.itemType] or 0) + v.amount
                end
            end
            for _, v: string in SuperiorItems do
                if (Amounts[v] or 0) >= 1 then
                    return true
                end
            end
            return false
        end

        ShopUtil.getAllSuperiorItems = GetSuperiorItems
        ShopUtil.ownsSuperiorItem = OwnsSuperiorItem
        vape:Clean(RunService.PreSimulation:Connect(ClearShopItems))
        vape:Clean(bedwars.Store.changed:connect(ClearShopItems))
        vape:Clean(LocalPlayer.AttributeChanged:Connect(ClearShopItems))
        vape:Clean(VapeEvents.AttributeChanged.Event:Connect(ClearShopItems))
        vape:Clean(function()
            if ShopUtil.getAllSuperiorItems == GetSuperiorItems then
                ShopUtil.getAllSuperiorItems = OldSuperiorItems
            end
            if ShopUtil.ownsSuperiorItem == OwnsSuperiorItem then
                ShopUtil.ownsSuperiorItem = OldOwnsSuperiorItem
            end
            ClearShopItems()
        end)
    end

    Entity.Raycast = function(Origin: Vector3, Direction: Vector3, Params: RaycastParams?)
        return bedwars.QueryUtil:raycast(Origin, Direction, Params)
    end
    Prediction.Raycast = Entity.Raycast

    OldWallcheck = Entity.Wallcheck
    local WallcheckParams: RaycastParams = RaycastParams.new()
    WallcheckParams.FilterType = Enum.RaycastFilterType.Exclude
    local WallcheckFilter: {Instance} = {}

    Entity.Wallcheck = function(Origin: Vector3, Position: Vector3, IgnoreObject, Ent)
        local Character = Ent and Ent.Character
        local SelfCharacter = LocalPlayer.Character
        local SelfRoot = SelfCharacter and SelfCharacter.PrimaryPart
        local TargetRoot = Character and Character.PrimaryPart
        if not SelfRoot or not TargetRoot then
            return OldWallcheck(Origin, Position, IgnoreObject)
        end

        local Humanoid: Humanoid? = SelfCharacter:FindFirstChildWhichIsA("Humanoid")
        local TargetHumanoid: Humanoid? = Character:FindFirstChildWhichIsA("Humanoid")
        local Scale = Humanoid and Humanoid:FindFirstChild("BodyHeightScale")
        local Height: Vector3 = Vector3.new(0, 5 * (Scale and Scale.Value or 1), 0)
        local SelfFeet: Vector3 = SelfRoot.Position - Vector3.new(0, (Humanoid and Humanoid.HipHeight or 0) + (SelfRoot.Size.Y / 2), 0)
        local TargetFeet: Vector3 = TargetRoot.Position - Vector3.new(0, (TargetHumanoid and TargetHumanoid.HipHeight or 0) + (TargetRoot.Size.Y / 2), 0)
        local SelfHead, TargetHead = SelfFeet + Height, TargetFeet + Height
        local SelfMiddle, TargetMiddle = (SelfFeet + SelfHead) / 2, (TargetFeet + TargetHead) / 2

        table.clear(WallcheckFilter)
        table.insert(WallcheckFilter, SelfCharacter)
        table.insert(WallcheckFilter, Character)
        for _, v: Instance in CollectionService:GetTagged("DontBlockSwordRaycast") do
            table.insert(WallcheckFilter, v)
        end
        if typeof(IgnoreObject) == "table" then
            for _, v: Instance in IgnoreObject do
                table.insert(WallcheckFilter, v)
            end
        end
        WallcheckParams.FilterDescendantsInstances = WallcheckFilter
        table.clear(WallcheckFilter)

        return (Entity.Raycast(SelfFeet, TargetFeet - SelfFeet, WallcheckParams) or Entity.Raycast(TargetFeet, SelfFeet - TargetFeet, WallcheckParams)) and (Entity.Raycast(SelfHead, TargetHead - SelfHead, WallcheckParams) or Entity.Raycast(TargetHead, SelfHead - TargetHead, WallcheckParams)) and (Entity.Raycast(SelfMiddle, TargetMiddle - SelfMiddle, WallcheckParams) or Entity.Raycast(TargetMiddle, SelfMiddle - TargetMiddle, WallcheckParams)) or nil
    end

    local function ClearStaleHooks()
        if not canDebug or not isexecutorclosure then
            return
        end
        local Seen = {}
        local function Clear(Object)
            if type(Object) ~= "table" or Seen[Object] then
                return
            end
            Seen[Object] = true
            local Meta = getmetatable(Object)
            local Class = type(Meta) == "table" and rawget(Meta, "__index")
            if type(Class) ~= "table" then
                return
            end
            for Key: string, Value: any in Object do
                if type(Value) == "function" and isexecutorclosure(Value) and type(Class[Key]) == "function" then
                    rawset(Object, Key, nil)
                end
            end
        end
        pcall(function()
            for _, v: any in Knit.Controllers do
                Clear(v)
            end
            for _, v: any in bedwars do
                Clear(v)
            end
        end)
    end
    ClearStaleHooks()

    local ChestController: any = bedwars.InventoryDraggingController
    local OldApplySnapshot: (any, any) -> any = ChestController.applySnapshot

    local function ApplySnapshot(self: any, Snapshot: any)
        local ChestHold: ((Folder) -> boolean)? = store.chestHold
        if ChestHold and Snapshot and Snapshot.chest and ChestHold(Snapshot.chest.chestFolder) then
            Snapshot = table.clone(Snapshot)
            Snapshot.chest = nil
        end

        local SlotHold: ((any) -> any?)? = store.slotHold
        if SlotHold and Snapshot then
            Snapshot = SlotHold(Snapshot) or Snapshot
        end
        return OldApplySnapshot(self, Snapshot)
    end

    rawset(ChestController, "applySnapshot", ApplySnapshot)
    vape:Clean(function()
        if rawget(ChestController, "applySnapshot") == ApplySnapshot then
            rawset(ChestController, "applySnapshot", nil)
        end
    end)

