    local function RequestSelfDeath(self: any, DamageType: any)
        local DeathLog: ((any, string) -> ())? = store.deathLog
        if DeathLog then
            DeathLog(DamageType, debug.traceback())
        end
        local DeathHold: (() -> boolean)? = store.deathHold
        if DeathHold and DeathHold() then
