    task.spawn(function()
        local Signals: {string} = {"Heartbeat", "PostSimulation", "PreAnimation", "PreRender", "PreSimulation", "RenderStepped", "Stepped"}

        local function CleanSignals()
            if not canDebug or not getconnections or not getfunctionhash or not isexecutorclosure then
                return
            end

            local Seen = {}
            for _, v: string in Signals do
                for _, Connection: any in getconnections(RunService[v]) do
                    if Connection.Function and not Connection.ForeignState and isexecutorclosure(Connection.Function) then
                        local Hash: string = `{v}{getfunctionhash(Connection.Function)}`
                        if Seen[Hash] then
                            Connection:Disconnect()
                        else
                            Seen[Hash] = true
                        end
                    end
                end
            end

            for _, v: any in bedwars.SyncEvents do
                if typeof(v) == "table" and typeof(v.entries) == "table" then
                    table.clear(Seen)
                    for i: any, Entry: any in v.entries do
                        local Callback = Entry.callbackInfo and Entry.callbackInfo.callback
                        if Callback and isexecutorclosure(Callback) then
                            local Hash: string = getfunctionhash(Callback)
                            if Seen[Hash] then
                                v.entries[i] = nil
                                if typeof(v.sortedEntries) == "table" then
                                    v.sortedEntries.isSorted = false
                                end
                            else
                                Seen[Hash] = true
                            end
                        end
                    end
                end
            end
        end

        local function CleanDummies()
            if not canDebug or not getconnections then
                return
            end

            for _, Dummy: Instance in CollectionService:GetTagged("trainingRoomDummy") do
                local Kept = {}
                for i: number, Connection: any in getconnections(Dummy.Destroying) do
                    local Callback = Connection.Function
                    local Source: string? = Callback and debug.info(Callback, "s")
                    if Source and Source:find("training-room-entity-controller", 1, true) then
                        local Ok, Target = pcall(debug.getupvalue, Callback, 1)
                        local Key = if Ok and Target ~= nil then Target else Callback
                        if Kept[Key] then
                            Connection:Disconnect()
                        else
                            Kept[Key] = true
                        end
                    end

                    if i % 2000 == 0 then
                        task.wait()
                    end
                end
                task.wait()
            end
        end

        task.wait(5)
        repeat
            pcall(CleanSignals)
            pcall(CleanDummies)
            task.wait(30)
        until vape.Loaded == nil
    end)

