	local HitregTiming = {
	    Window = 8,
	    FloorWindow = 32,
	    ExcessCap = 0.25,
	    HoldCap = 0.18,
	    OutlierSamples = 4,
	    OutlierGap = 0.1,
	    Spread = 0,
	    Noise = 0.03,
	    Margin = 0,
	    AlignFrames = false,
