Run(function()
	local AutoHonor
	local Delay
	
	local Honored = {}
	local function Honor()
	    local PlayerList, Team = Players:GetPlayers(), LocalPlayer:GetAttribute("Team")
	    table.sort(PlayerList, function(A: Player, B: Player)
	        return A:GetAttribute("Team") == Team and B:GetAttribute("Team") ~= Team
	    end)
	    for _, v: Player in PlayerList do
	        local TeamId = v:GetAttribute("Team")
	        if v ~= LocalPlayer and TeamId and not Honored[TeamId] and (LocalPlayer:GetAttribute(TeamId == Team and "HonorPointsLeftToGiveToAllies" or "HonorPointsLeftToGiveToOpponents") or 0) > 0 then
	            Honored[TeamId] = true
	            bedwars.HonorController:honorPlayer(v.UserId):await()
	            task.wait(Delay.Value)
	        end
	    end
	end
	
	AutoHonor = vape.Categories.Utility:CreateModule({
	    Name = "AutoHonor",
	    Function = function(Callback: boolean)
	        if Callback then
	            AutoHonor:Clean(VapeEvents.EntityDeathEvent.Event:Connect(function(DeathTable)
	                if DeathTable.finalKill and DeathTable.entityInstance == LocalPlayer.Character and #bedwars.Store:getState().Party.members <= 0 and store.matchState ~= 2 then
	                    Honor()
	                end
	            end))
	            AutoHonor:Clean(VapeEvents.MatchEndEvent.Event:Connect(Honor))
	        end
	    end,
	    Tooltip = "Automatically honor your teammates"
	})
	
	Delay = AutoHonor:CreateSlider({
	    Name = "Delay",
	    Min = 0,
	    Max = 2,
	    Decimal = 100,
	    Suffix = "seconds",
	    Default = 0.1
	})
end)

Run(function()
	local AutoMiner
	local Delay
	local Animation
	local KitCheck
	local Range
	
	local Legit: number = GetFunctionRange(bedwars.MinerController.setupMinerPrompts) or 0
	local Session = nil
	
	AutoMiner = vape.Categories.Utility:CreateModule({
	    Name = "AutoMiner",
	    Function = function(Callback: boolean)
	        if Callback then
	            local Petrified = Collection("petrified-player", AutoMiner)
	            local Tries: {[Instance]: number} = setmetatable({}, {__mode = "k"})
	            local LastTry: {[Instance]: number} = setmetatable({}, {__mode = "k"})
	            local Current = {}
	            local Cooldown: number = 0
	            Session = Current
	
	            repeat
	                if Entity.isAlive and (not KitCheck.Enabled or table.find(store.equippedKits or {}, "miner")) and tick() - Cooldown >= math.max(Delay.Value, 0.25) then
	                    local LocalPosition: Vector3 = Entity.character.RootPart.Position
	                    local MyTeam = bedwars.Store:getState().Game.myTeam
	                    local RetryGap: number = Delay.Value + 1
	                    local Best, BestTries, BestDistance = nil, math.huge, math.huge
	                    for _, v: Instance in Petrified do
	                        local Root: BasePart? = if not v.Parent then nil elseif v:IsA("Model") then v.PrimaryPart elseif v:IsA("BasePart") then v else nil
	                        if not Root or not v:GetAttribute("PetrifyId") then
	                            continue
	                        end
	                        if MyTeam and v:GetAttribute("Team") == MyTeam.id then
	                            continue
	                        end
	                        if LastTry[v] and (tick() - LastTry[v]) < RetryGap then
	                            continue
	                        end
	
	                        local Distance: number = (LocalPosition - Root.Position).Magnitude
	                        local Count: number = Tries[v] or 0
	                        if Distance <= Range.Value and (Count < BestTries or (Count == BestTries and Distance < BestDistance)) then
	                            Best, BestTries, BestDistance = v, Count, Distance
	                        end
	                    end
	
	                    if Best then
	                        local Target: Instance = Best
	                        local PetrifyId = Target:GetAttribute("PetrifyId")
	                        Tries[Target] = BestTries + 1
	                        LastTry[Target] = tick()
	                        if Animation.Enabled then
	                            bedwars.GameAnimationUtil:playAnimation(LocalPlayer.Character, bedwars.AnimationType.MINER_MINE_STONE)
	                        end
	
	                        task.delay(Delay.Value, function()
	                            if AutoMiner.Enabled and Target.Parent then
	                                bedwars.Handler:Get("DestroyPetrifiedPlayer"):Fire("SendToServer", {
	                                    petrifyId = PetrifyId
	                                })
	                            end
	                        end)
	                        Cooldown = tick()
	                    end
	                end
	                task.wait(0.1)
	            until not AutoMiner.Enabled or Session ~= Current
	        end
	    end,
	    Tooltip = "Automatically mines the closest enemy petrified player within range"
	})
	
	Range = AutoMiner:CreateSlider({
	    Name = "Range",
	    Min = 1,
	    Max = 30,
	    Default = 12,
	    Suffix = function(Val: number)
	        return Val <= 1 and "stud" or "studs"
	    end
	})
	AutoMiner:CreateButton({
	    Name = "Sync to legit range",
	    Function = function()
	        Range:SetValue(Legit)
	    end
	})
	Delay = AutoMiner:CreateSlider({
	    Name = "Delay",
	    Min = 0,
	    Max = 2,
	    Default = 0.1,
	    Decimal = 10,
	    Suffix = "seconds"
	})
	Animation = AutoMiner:CreateToggle({
	    Name = "Animation",
	    Default = true
	})
	KitCheck = AutoMiner:CreateToggle({
	    Name = "Kit check",
	    Tooltip = "Only mines while you are using the Miner kit",
	    Default = true
	})
end)

Run(function()
	local AutoPearl
	local Legit
	local Back
	local Check
	local LandCheck
	local BackDelay
	local Limit
	local ClutchRange
	local Cooldown
	local ShowLanding
	local WarnLost
	local LastThrow: number = 0
	local NextScan: number = 0
	local LastGround: Vector3?
	local VoidLine: number?
	local InFlight
	local Alerted: boolean = false
	local Hope: boolean = false
	local Probe: number = 0
	local Markers: {Part} = {}
	
	local FireLead: number = 0.02
	local VoidDepth: number = 200
	local PathStep: number = 0.1
	local PathSteps: number = 12
	local FlightStep: number = 0.05
	local MaxFlight: number = 4
	local LandingTolerance: number = 4
	local FloorReach: number = 2
	local ScanGap: number = 0.05
	local RetryGap: number = 0.3
	local EquipGap: number = 0.05
	local VoidMargin: number = 50
	local FallTrigger: number = 120
	local MaxChecks: number = 12
	local ArcSamples: number = 6
	local MarkerCount: number = 4
	local ProbeStride: number = 2
	local EdgePenalty: number = 0.15
	local EdgeProbes: {Vector3} = {
	    Vector3.new(2, 0, 2),
	    Vector3.new(2, 0, -2),
	    Vector3.new(-2, 0, 2),
	    Vector3.new(-2, 0, -2)
	}
	local PearlBox: Vector3 = Vector3.new(3, 1, 3)
	
	local RayCheck: RaycastParams = RaycastParams.new()
	RayCheck.RespectCanCollide = true
	RayCheck.FilterType = Enum.RaycastFilterType.Include
	
	local function GetGravity(): number
	    return bedwars.ProjectileMeta.telepearl.gravitationalAcceleration or 196.2
	end
	
	local function PredictLanding(Origin: Vector3, Velocity: Vector3): (Vector3?, Vector3?)
	    local Drop: Vector3 = Vector3.new(0, -GetGravity(), 0)
	    local Last: Vector3 = Origin
	    for Step: number = 1, math.round(MaxFlight / FlightStep) do
	        local Time: number = Step * FlightStep
	        local Position: Vector3 = Origin + Velocity * Time + Drop * (0.5 * Time * Time)
	        local Direction: Vector3 = Position - Last
	        local Hit: RaycastResult? = workspace:Blockcast(CFrame.new(Last), PearlBox, Direction, store.airRay)
	        if Hit then
	            return Last + Direction.Unit * Hit.Distance, Hit.Normal
	        end
	        Last = Position
	    end
	
	    return nil, nil
	end
	
	local function GetArcs(From: Vector3, Spot: Vector3): {any}
	    local Meta = bedwars.ProjectileMeta.telepearl
	    local Speed: number = Meta.launchVelocity
	    local Gravity: number = GetGravity()
	    local Offset: Vector3 = Spot - From
	    local Flat: Vector3 = Offset * Vector3.new(1, 0, 1)
	    local Discriminant: number = Speed ^ 4 - Gravity * (Gravity * Flat.Magnitude ^ 2 + 2 * Offset.Y * Speed ^ 2)
	    local Arcs: {any} = {}
	    if Flat.Magnitude < 1 or Discriminant < 0 then
	        return Arcs
	    end
	
	    for _, v: number in {-1, 1} do
	        local Angle: number = math.atan((Speed ^ 2 + v * math.sqrt(Discriminant)) / (Gravity * Flat.Magnitude))
	        table.insert(Arcs, {
	            velocity = Flat.Unit * (math.cos(Angle) * Speed) + Vector3.new(0, math.sin(Angle) * Speed, 0),
	            time = Flat.Magnitude / (math.cos(Angle) * Speed)
	        })
	    end
	
	    return Arcs
	end
	
	local function IsArcClear(From: Vector3, Velocity: Vector3, Time: number): boolean
	    local Drop: Vector3 = Vector3.new(0, -GetGravity(), 0)
	    local Last: Vector3 = From
	    for Step: number = 1, ArcSamples do
	        local Elapsed: number = Time * Step / ArcSamples
	        local Position: Vector3 = From + Velocity * Elapsed + Drop * (0.5 * Elapsed * Elapsed)
	        if workspace:Raycast(Last, Position - Last, RayCheck) then
	            return false
	        end
	        Last = Position
	    end
	
	    return true
	end
	
	local function GetSafeLanding(From: Vector3, Velocity: Vector3, Spot: Vector3): Vector3?
	    local Landing, Normal = PredictLanding(From, Velocity)
	    if not Landing or not Normal or Normal.Y < 0.7 or (Landing - Spot).Magnitude > LandingTolerance then
	        return
	    end
	
	    return workspace:Raycast(Landing, Vector3.new(0, -FloorReach, 0), RayCheck) and Landing
	end
	
	local function GetAnchors(Position: Vector3): {Vector3}
	    local Anchors: {Vector3} = {Position + Vector3.new(0, 40, 0)}
	    if LastGround then
	        table.insert(Anchors, LastGround + Vector3.new(0, 5, 0))
	    end
	
	    return Anchors
	end
	
	local function GetVoidLine(): number
	    local Engine: number = workspace.FallenPartsDestroyHeight
	    if not VoidLine then
	        local Lowest: number = math.huge
	        for _, v: BasePart in store.blocks do
	            Lowest = math.min(Lowest, v.Position.Y - v.Size.Y / 2)
	        end
	        if Lowest == math.huge then
	            return Engine
	        end
	        VoidLine = Lowest - VoidMargin
	    end
	
	    return math.max(VoidLine, Engine)
	end
	
	local function GetDeadline(Position: Vector3, Speed: number): number
	    local Gravity: number = workspace.Gravity
	    local Drop: number = Position.Y - GetVoidLine()
	    if Drop <= 0 then
	        return 0
	    end
	
	    return (Speed + math.sqrt(Speed ^ 2 + 2 * Gravity * Drop)) / Gravity
	end
	
	local function GetSupport(Landing: Vector3): number
	    local Support: number = 0
	    for _, v: Vector3 in EdgeProbes do
	        if workspace:Raycast(Landing + v, Vector3.new(0, -FloorReach - 1, 0), RayCheck) then
	            Support += 1
	        end
	    end
	
	    return Support
	end
	
	local function FindSpots(From: Vector3, Anchors: {Vector3}, Deadline: number): ({any}, number)
	    local Candidates: {any} = {}
	    local Seen: {[string]: boolean} = {}
	    local Ground: number = 0
	    for _, Anchor: Vector3 in Anchors do
	        for Radius: number = 2, ClutchRange.Value, 3 do
	            local Count: number = math.max(8, math.ceil(2 * math.pi * Radius / 6))
	            for i: number = 1, Count do
	                local Angle: number = 2 * math.pi * i / Count
	                local Start: Vector3 = Anchor + Vector3.new(math.cos(Angle) * Radius, 3, math.sin(Angle) * Radius)
	                local Ray: RaycastResult? = workspace:Raycast(Start, Vector3.new(0, -120, 0), RayCheck)
	                if not Ray or Ray.Normal.Y < 0.7 then
	                    continue
	                end
	
	                local Key: string = `{math.round(Ray.Position.X)},{math.round(Ray.Position.Y)},{math.round(Ray.Position.Z)}`
	                if Seen[Key] then
	                    continue
	                end
	                Seen[Key] = true
	                Ground += 1
	
	                for _, Arc: any in GetArcs(From, Ray.Position + Vector3.new(0, 0.5, 0)) do
	                    if Arc.time + EquipGap < Deadline and IsArcClear(From, Arc.velocity, Arc.time) then
	                        table.insert(Candidates, {spot = Ray.Position, velocity = Arc.velocity, time = Arc.time})
	                    end
	                end
	            end
	        end
	    end
	
	    table.sort(Candidates, function(A: any, B: any): boolean
	        return A.time < B.time
	    end)
	
	    local Spots: {any} = {}
	    local Landed: {[string]: boolean} = {}
	    for i: number = 1, math.min(#Candidates, MaxChecks) do
	        local Landing: Vector3? = GetSafeLanding(From, Candidates[i].velocity, Candidates[i].spot)
	        if not Landing then
	            continue
	        end
	
	        local Key: string = `{math.round(Landing.X / 3)},{math.round(Landing.Y / 3)},{math.round(Landing.Z / 3)}`
	        if Landed[Key] then
	            continue
	        end
	        Landed[Key] = true
	
	        Candidates[i].landing = Landing
	        Candidates[i].score = Candidates[i].time + (#EdgeProbes - GetSupport(Landing)) * EdgePenalty
	        table.insert(Spots, Candidates[i])
	    end
	
	    table.sort(Spots, function(A: any, B: any): boolean
	        return A.score < B.score
	    end)
	
	    return Spots, Ground
	end
	
	local function IsVoidFall(Root: BasePart): (boolean, {Vector3})
	    local Path: {Vector3} = {}
	    local Velocity: Vector3 = Root.AssemblyLinearVelocity
	    if Velocity.Y > -FallTrigger or workspace:Raycast(Root.Position, Vector3.new(0, -VoidDepth, 0), RayCheck) then
	        return false, Path
	    end
	
	    local Position: Vector3 = Root.Position
	    local Gravity: number = workspace.Gravity
	    for _ = 1, PathSteps do
	        local Next: Vector3 = Position + Velocity * PathStep - Vector3.new(0, Gravity * 0.5 * PathStep * PathStep, 0)
	        local Hit: RaycastResult? = workspace:Raycast(Position, Next - Position, RayCheck)
	        if Hit then
	            if Hit.Normal.Y >= 0.7 then
	                return false, Path
	            end
	            Velocity = Vector3.new(0, Velocity.Y, 0)
	            Next = Hit.Position + Hit.Normal * 0.5
	        end
	        Velocity -= Vector3.new(0, Gravity * PathStep, 0)
	        Position = Next
	        table.insert(Path, Position)
	    end
	
	    return true, Path
	end
	
	local function GetFirePosition(Root: BasePart): Vector3
	    return Root.Position + Root.AssemblyLinearVelocity * FireLead - Vector3.new(0, workspace.Gravity * 0.5 * FireLead * FireLead, 0)
	end
	
	local function CreateMarker(Index: number): Part
	    local Color: Color3 = Index == 1 and Color3.fromRGB(90, 255, 120) or Color3.new(1, 1, 1)
	    local TagSize: Vector2 = GetFontBounds("Best landing 000 studs 0.00s", 14, UIPallet.Font)
	    local Marker: Part = Instance.new("Part")
	    Marker.Size = Vector3.new(3, 0.2, 3)
	    Marker.Anchored = true
	    Marker.CanCollide = false
	    Marker.CanQuery = false
	    Marker.CanTouch = false
	    Marker.CastShadow = false
	    Marker.Transparency = 1
	    local Selection: SelectionBox = Instance.new("SelectionBox")
	    Selection.Adornee = Marker
	    Selection.LineThickness = 0.04
	    Selection.Color3 = Color
	    Selection.SurfaceColor3 = Color
	    Selection.SurfaceTransparency = 0.75
	    Selection.Parent = Marker
	    local Billboard: BillboardGui = Instance.new("BillboardGui")
	    Billboard.Name = "Tag"
	    Billboard.Size = UDim2.fromOffset(TagSize.X + 8, TagSize.Y + 7)
	    Billboard.StudsOffsetWorldSpace = Vector3.new(0, 2, 0)
	    Billboard.AlwaysOnTop = true
	    Billboard.Parent = Marker
	    local Label: TextLabel = Instance.new("TextLabel")
	    Label.Name = "Label"
	    Label.Size = Billboard.Size
	    Label.BackgroundColor3 = Color3.new()
	    Label.BackgroundTransparency = 0.5
	    Label.BorderSizePixel = 0
	    Label.FontFace = UIPallet.Font
	    Label.TextSize = 14
	    Label.TextColor3 = Color
	    Label.Parent = Billboard
	
	    return Marker
	end
	
	local function HideSpots(): ()
	    for _, v: Part in Markers do
	        if v.Parent then
	            v.Parent = nil
	        end
	    end
	end
	
	local function ShowSpots(Spots: {any}, Position: Vector3): ()
	    if not ShowLanding.Enabled then
	        return
	    end
	
	    for i: number = 1, MarkerCount do
	        local Info: any = Spots[i]
	        local Marker: Part? = Markers[i]
	        if not Info then
	            if Marker and Marker.Parent then
	                Marker.Parent = nil
	            end
	            continue
	        end
	
	        if not Marker then
	            Marker = CreateMarker(i)
	            Markers[i] = Marker
	        end
	
	        local Distance: number = math.round((Info.landing - Position).Magnitude)
	        local Text: string = `{i == 1 and "Best landing " or ""}{Distance} studs {math.round(Info.time * 100) / 100}s`
	        Marker.CFrame = CFrame.new(Info.landing - Vector3.new(0, 0.4, 0))
	        if Marker.Tag.Label.Text ~= Text then
	            Marker.Tag.Label.Text = Text
	        end
	        if Marker.Parent ~= Camera then
	            Marker.Parent = Camera
	        end
	    end
	end
	
	local function ClearFall(): ()
	    Alerted, Hope, Probe = false, false, 0
	    HideSpots()
	end
	
	local function Lost(Reason: string): ()
	    if Alerted then
	        return
	    end
	
	    Alerted = true
	    if WarnLost.Enabled then
	        vape:CreateNotification("AutoPearl", `Can't clutch, {Reason}`, 5, "warning")
	    end
	end
	
	local function LookAhead(Path: {Vector3}, Ground: number, Deadline: number): ()
	    Probe += 1
	    local Sample: Vector3? = Path[Probe * ProbeStride]
	    if Sample then
	        if #FindSpots(Sample, GetAnchors(Sample), Deadline - Probe * ProbeStride * PathStep) > 0 then
	            Hope = true
	        end
	        return
	    end
	
	    if not Hope then
	        local Reason: string = "your pearl can't reach any ground in time"
	        if Ground == 0 then
	            Reason = `no ground within {ClutchRange.Value} studs`
	        end
	        Lost(Reason)
	    end
	    Probe, Hope = 0, false
	end
	
	local function GetHeld(): string
	    local HandValue: ObjectValue? = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HandInvItem") or nil
	    return HandValue and HandValue.Value and HandValue.Value.Name or "nothing"
	end
	
	local function FirePearl(Shot: any, Origin: Vector3, Item): boolean
	    if not Entity.isAlive then
	        return false
	    end
	
	    local Hotbar, OldHand = GetHotbar(Item.tool), store.hand
	    local PreviousThrow: number = LastThrow
	    local ThrowUntil: number = tick() + Cooldown.Value
	    LastThrow = ThrowUntil
	
	    SwitchItem(Item.tool, EquipGap)
	
	    local Position: Vector3? = Entity.isAlive and Origin or nil
	    local Direction: Vector3? = Position and Shot.velocity or nil
	    local Landed: boolean = false
	
	    if Position and Direction then
	        local Meta = bedwars.ProjectileMeta.telepearl
	        local Id: string = bedwars.IdUtil.generateId(8)
	        local ShotData = bedwars.getShotData("telepearl")
	        local Projectile = bedwars.ProjectileController:createLocalProjectile(Meta, "telepearl", "telepearl", Position, Id, Direction, ShotData)
	        InFlight = Projectile
	        local Tracked = Projectile
	        local Pending: boolean = Projectile == nil
	
	        bedwars.Handler:Get("ProjectileFire"):Fire("CallServerAsync",
	            Item.tool,
	            "telepearl",
	            "telepearl",
	            Position,
	            Position,
	            Direction,
	            Id,
	            ShotData,
	            workspace:GetServerTimeNow() - 0.045
	        ):andThen(function(Result)
	            Pending = false
	            if type(Result) == "table" and Result.accepted then
	                if Projectile == nil and typeof(Result.model) == "Instance" then
	                    Tracked, InFlight = Result.model, Result.model
	                elseif Result.model and Result.model.Parent then
	                    Result.model.Parent = ReplicatedStorage
	                end
	                return
	            end
	
	            warn(`AutoPearl throw refused, holding {GetHeld()}`)
	            if Projectile then
	                Projectile:Destroy()
	            end
	            if LastThrow == ThrowUntil then
	                LastThrow = PreviousThrow
	            end
	            if InFlight == Projectile then
	                InFlight = nil
	            end
	            NextScan = 0
	        end)
	
	        task.spawn(function()
	            local Timeout: number = tick() + 10
	            repeat
	                task.wait()
	            until not AutoPearl.Enabled or tick() >= Timeout or (not Pending and (not Tracked or not Tracked.Parent))
	            Landed = true
	            HideSpots()
	        end)
	    else
	        if LastThrow == ThrowUntil then
	            LastThrow = PreviousThrow
	        end
	        NextScan = tick() + RetryGap
	        Landed = true
	        HideSpots()
	    end
	
	    if Legit.Enabled and Hotbar then
	        HotbarSwitch(Hotbar)
	    end
	
	    if Back.Enabled and LandCheck.Enabled then
	        repeat
	            task.wait()
	        until Landed or not AutoPearl.Enabled
	    end
	
	    if Back.Enabled and OldHand and OldHand.tool then
	        task.wait(BackDelay:GetRandomValue())
	        SwitchItem(OldHand.tool)
	        if Legit.Enabled and GetHotbar(OldHand.tool) then
	            HotbarSwitch(GetHotbar(OldHand.tool))
	        end
	    end
	
	    return Direction ~= nil
	end
	
	local function Rescue(Root: BasePart, Path: {Vector3}): ()
	    if Check.Enabled and InFlight and InFlight.Parent then
	        HideSpots()
	        return
	    end
	
	    local Item = GetItem("telepearl")
	    if not Item then
	        HideSpots()
	        Lost("you have no telepearl")
	        return
	    end
	
	    local Deadline: number = GetDeadline(Root.Position, Root.AssemblyLinearVelocity.Y)
	    local From: Vector3 = GetFirePosition(Root)
	    local Spots: {any}, Ground: number = FindSpots(From, GetAnchors(Root.Position), Deadline)
	    NextScan = tick() + ScanGap
	    if #Spots == 0 then
	        HideSpots()
	        if not Alerted then
	            LookAhead(Path, Ground, Deadline)
	        end
	        return
	    end
	
	    Probe, Hope = 0, false
	    local Success, Result = pcall(ShowSpots, Spots, Root.Position)
	    if not Success then
	        warn(`AutoPearl landing boxes failed: {Result}`)
	    end
	    if Limit.Enabled and not (store.hand.tool and store.hand.tool.Name == "telepearl") then
	        return
	    end
	
	    FirePearl(Spots[1], From, Item)
	end
	
	AutoPearl = vape.Categories.Utility:CreateModule({
	    Name = "AutoPearl",
	    Function = function(Callback: boolean)
	        if Callback then
	            VoidLine = nil
	            local Connection = bedwars.SyncEvents.ProjectileLaunched:connect(function(Event)
	                if Event.projectileType ~= "telepearl" or typeof(Event.projectile) ~= "Instance" or not Event.projectile:IsA("PVInstance") or not Entity.isAlive then
	                    return
	                end
	                if Event.shooter == Entity.character.Character then
	                    InFlight = Event.projectile
	                end
	            end)
	
	            AutoPearl:Clean(function()
	                Connection:Destroy()
	                ClearFall()
	                for _, v: Part in Markers do
	                    v:Destroy()
	                end
	                table.clear(Markers)
	            end)
	
	            repeat
	                if store.map and store.airRay then
	                    RayCheck.FilterDescendantsInstances = {store.map}
	                    RayCheck.CollisionGroup = Entity.isAlive and Entity.character.RootPart.CollisionGroup or ""
	
	                    local Root = Entity.isAlive and Entity.character.RootPart
	                    if Root and Entity.character.Humanoid.FloorMaterial ~= Enum.Material.Air then
	                        LastGround = Root.Position
	                    end
	
	                    if not Root then
	                        ClearFall()
	                    elseif tick() >= NextScan and tick() >= LastThrow then
	                        local Falling: boolean, Path: {Vector3} = IsVoidFall(Root)
	                        if Falling then
	                            Rescue(Root, Path)
	                        else
	                            ClearFall()
	                        end
	                    end
	                end
	
	                task.wait()
	            until not AutoPearl.Enabled
	        else
	            InFlight = nil
	            LastGround = nil
	        end
	    end,
	    Tooltip = "Throws a pearl onto nearby ground once you are falling at 120 studs/s over the void\nOnly throws along an arc it checked is clear and lands before you hit the void line\nBoxes the ground you can land on (green is the best one) and warns when it's sure you can't clutch"
	})
	
	Legit = AutoPearl:CreateToggle({
	    Name = "Legit Switch",
	    Tooltip = "Visualizes the switching clientside",
	    Default = true
	})
	Back = AutoPearl:CreateToggle({
	    Name = "Switch back",
	    Function = function(Callback: boolean)
	        if BackDelay then
	            BackDelay.Object.Visible = Callback
	        end
	        if LandCheck then
	            LandCheck.Object.Visible = Callback
	        end
	    end,
	    Default = true,
	    Tooltip = "Switches back to the last slot before pearl"
	})
	LandCheck = AutoPearl:CreateToggle({
	    Name = "Only after landed",
	    Tooltip = "Only switches back after your pearl landed",
	    Darker = true
	})
	Check = AutoPearl:CreateToggle({
	    Name = "Pearl check",
	    Default = true,
	    Tooltip = "Doesn't throw a pearl while one of yours is still in the air, including ones you threw yourself"
	})
	BackDelay = AutoPearl:CreateTwoSlider({
	    Name = "Switch Back Delay",
	    Min = 0,
	    Max = 2,
	    DefaultMin = 0.1,
	    DefaultMax = 0.2,
	    Darker = true
	})
	ClutchRange = AutoPearl:CreateSlider({
	    Name = "Clutch range",
	    Min = 10,
	    Max = 100,
	    Default = 24,
	    Suffix = "studs",
	    Tooltip = "How far away a block can be for a void save, blocks your pearl cannot reach are skipped"
	})
	Cooldown = AutoPearl:CreateSlider({
	    Name = "Cooldown",
	    Min = 0,
	    Max = 5,
	    Default = 1,
	    Decimal = 10,
	    Suffix = "seconds",
	    Tooltip = "Minimum gap between two throws"
	})
	Limit = AutoPearl:CreateToggle({
	    Name = "Limit to item",
	    Tooltip = "Only throws pearl when holding a pearl"
	})
	ShowLanding = AutoPearl:CreateToggle({
	    Name = "Show landing",
	    Function = function(Callback: boolean)
	        if not Callback then
	            HideSpots()
	        end
	    end,
	    Default = true,
	    Tooltip = "Boxes the ground your pearl can reach while you fall, green is the best spot (flat ground away from the edge, soonest)\nEach box shows how far it is and how long the pearl takes"
	})
	WarnLost = AutoPearl:CreateToggle({
	    Name = "Warn when lost",
	    Default = true,
	    Tooltip = "Tells you when you can't clutch: no pearl, or no ground your pearl can reach anywhere along the next second of your fall\nIf you steer in the air a spot can still open up after it warned"
	})
end)

Run(function()
	local AutoPearlAggro
	local Legit
	local Back
	local Check
	local LandCheck
	local BackDelay
	local Limit
	local Distance
	local MinHealth
	local Cooldown
	local LastThrow: number = 0
	local InFlight
	
	local FollowMinimum: number = 12
	local LandingTolerance: number = 4
	local FlightStep: number = 0.05
	local MaxFlight: number = 4
	local PearlBox: Vector3 = Vector3.new(3, 1, 3)
	
	local function PredictLanding(Origin: Vector3, Velocity: Vector3, Gravity: number): Vector3?
	    local Drop: Vector3 = Vector3.new(0, -Gravity, 0)
	    local Last: Vector3 = Origin
	    for Step: number = 1, math.round(MaxFlight / FlightStep) do
	        local Time: number = Step * FlightStep
	        local Position: Vector3 = Origin + Velocity * Time + Drop * (0.5 * Time * Time)
	        local Direction: Vector3 = Position - Last
	        local Hit: RaycastResult? = workspace:Blockcast(CFrame.new(Last), PearlBox, Direction, store.airRay)
	        if Hit then
	            return Last + Direction.Unit * Hit.Distance
	        end
	        Last = Position
	    end
	
	    return nil
	end
	
	local function GetLaunch(From: Vector3, Spot: Vector3): Vector3?
	    local Meta = bedwars.ProjectileMeta.telepearl
	    local Speed: number = Meta.launchVelocity
	    local Gravity: number = Meta.gravitationalAcceleration or 196.2
	    local Offset: Vector3 = Spot - From
	    local Flat: Vector3 = Offset * Vector3.new(1, 0, 1)
	    local Discriminant: number = Speed ^ 4 - Gravity * (Gravity * Flat.Magnitude ^ 2 + 2 * Offset.Y * Speed ^ 2)
	    if Flat.Magnitude < 1 or Discriminant < 0 then
	        return nil
	    end
	
	    for _, v: number in {-1, 1} do
	        local Angle: number = math.atan((Speed ^ 2 + v * math.sqrt(Discriminant)) / (Gravity * Flat.Magnitude))
	        local Velocity: Vector3 = Flat.Unit * (math.cos(Angle) * Speed) + Vector3.new(0, math.sin(Angle) * Speed, 0)
	        local Landing: Vector3? = PredictLanding(From, Velocity, Gravity)
	        if Landing and (Landing - Spot).Magnitude <= LandingTolerance then
	            return Velocity
	        end
	    end
	
	    return nil
	end
	
	local function FirePearl(Spot: Vector3, Item): boolean
	    if not Entity.isAlive or not GetLaunch(Entity.character.RootPart.Position, Spot) then
	        return false
	    end
	
	    local Hotbar, OldHand = GetHotbar(Item.tool), store.hand
	    local PreviousThrow: number = LastThrow
	    local ThrowUntil: number = tick() + Cooldown.Value
	    LastThrow = ThrowUntil
	
	    SwitchItem(Item.tool)
	    if Legit.Enabled and Hotbar then
	        HotbarSwitch(Hotbar)
	    end
	
	    local Position: Vector3 = Entity.character.RootPart.Position
	    local Direction: Vector3? = Entity.isAlive and GetLaunch(Position, Spot) or nil
	    local Landed: boolean = false
	
	    if Direction then
	        local Meta = bedwars.ProjectileMeta.telepearl
	        local Id: string = bedwars.IdUtil.generateId(8)
	        local ShotData = bedwars.getShotData("telepearl")
	        local Projectile = bedwars.ProjectileController:createLocalProjectile(Meta, "telepearl", "telepearl", Position, Id, Direction, ShotData)
	        InFlight = Projectile
	        local Tracked = Projectile
	        local Pending: boolean = Projectile == nil
	
	        bedwars.Handler:Get("ProjectileFire"):Fire("CallServerAsync",
	            Item.tool,
	            "telepearl",
	            "telepearl",
	            Position,
	            Position,
	            Direction,
	            Id,
	            ShotData,
	            workspace:GetServerTimeNow() - 0.045
	        ):andThen(function(Result)
	            Pending = false
	            if type(Result) == "table" and Result.accepted then
	                if Projectile == nil and typeof(Result.model) == "Instance" then
	                    Tracked, InFlight = Result.model, Result.model
	                elseif Result.model then
	                    Result.model.Parent = ReplicatedStorage
	                end
	                return
	            end
	
	            if LastThrow == ThrowUntil then
	                LastThrow = PreviousThrow
	            end
	            if InFlight == Projectile then
	                InFlight = nil
	            end
	        end)
	
	        task.spawn(function()
	            local Timeout: number = tick() + 10
	            repeat
	                task.wait()
	            until not AutoPearlAggro.Enabled or tick() >= Timeout or (not Pending and (not Tracked or not Tracked.Parent))
	            Landed = true
	        end)
	    else
	        if LastThrow == ThrowUntil then
	            LastThrow = PreviousThrow
	        end
	        Landed = true
	    end
	
	    if Back.Enabled and LandCheck.Enabled then
	        repeat
	            task.wait()
	        until Landed or not AutoPearlAggro.Enabled
	    end
	
	    if Back.Enabled and OldHand and OldHand.tool then
	        task.wait(BackDelay:GetRandomValue())
	        SwitchItem(OldHand.tool)
	        if Legit.Enabled and GetHotbar(OldHand.tool) then
	            HotbarSwitch(GetHotbar(OldHand.tool))
	        end
	    end
	
	    return Direction ~= nil
	end
	
	local function Follow(Origin: Vector3, Velocity: Vector3)
	    if not Entity.isAlive or not store.airRay then
	        return
	    end
	
	    local Meta = bedwars.ProjectileMeta.telepearl
	    local Spot: Vector3? = PredictLanding(Origin, Velocity, Meta.gravitationalAcceleration or 196.2)
	    if not Spot or not AutoPearlAggro.Enabled or not Entity.isAlive then
	        return
	    end
	
	    local Position: Vector3 = Entity.character.RootPart.Position
	    local Gap: number = (Spot - Position).Magnitude
	    if Gap > Distance.Value or Gap < FollowMinimum or Gap < (Origin - Position).Magnitude then
	        return
	    end
	    if tick() < LastThrow or (Check.Enabled and InFlight and InFlight.Parent) then
	        return
	    end
	    if MinHealth.Value > 0 and Entity.character.Health < MinHealth.Value then
	        return
	    end
	    if Limit.Enabled and not (store.hand.tool and store.hand.tool.Name == "telepearl") then
	        return
	    end
	
	    local Item = GetItem("telepearl")
	    if Item then
	        FirePearl(Spot, Item)
	    end
	end
	
	local function HandleLaunch(Event)
	    if Event.projectileType ~= "telepearl" or not Entity.isAlive then
	        return
	    end
	    if Event.shooter == Entity.character.Character then
	        if typeof(Event.projectile) == "Instance" and Event.projectile:IsA("PVInstance") then
	            InFlight = Event.projectile
	        end
	        return
	    end
	    if typeof(Event.origin) ~= "Vector3" or typeof(Event.launchVelocity) ~= "Vector3" then
	        return
	    end
	
	    for _, v: any in Entity.List do
	        if v.Character == Event.shooter then
	            if v.Targetable then
	                task.spawn(Follow, Event.origin, Event.launchVelocity)
	            end
	            break
	        end
	    end
	end
	
	AutoPearlAggro = vape.Categories.Utility:CreateModule({
	    Name = "AutoPearlAggro",
	    Function = function(Callback: boolean)
	        if Callback then
	            local Connection = bedwars.SyncEvents.ProjectileLaunched:connect(HandleLaunch)
	
	            AutoPearlAggro:Clean(function()
	                Connection:Destroy()
	            end)
	
	            if not canDebug then
	                bedwars.Client:WaitFor("ProjectileLaunchClient"):andThen(function(Remote)
	                    if not Remote or not AutoPearlAggro.Enabled then
	                        return
	                    end
	
	                    AutoPearlAggro:Clean(Remote:Connect(function(Data)
	                        if type(Data) ~= "table" then
	                            return
	                        end
	
	                        local Shooter = Data.shooter
	                        if typeof(Shooter) == "Instance" and Shooter:IsA("Player") then
	                            Shooter = Shooter.Character
	                        end
	                        HandleLaunch({
	                            projectileType = Data.projectileType,
	                            shooter = Shooter,
	                            origin = Data.positionFrom,
	                            launchVelocity = Data.initialVelocity
	                        })
	                    end))
	                end)
	            end
	        else
	            InFlight = nil
	        end
	    end,
	    Tooltip = "Predicts where an enemy pearl will land the moment it is thrown and pearls you to the same spot\nPearls that fall into the void, land closer to you than the thrower stood, or that your pearl cannot reach are ignored"
	})
	
	Legit = AutoPearlAggro:CreateToggle({
	    Name = "Legit Switch",
	    Tooltip = "Visualizes the switching clientside",
	    Default = true
	})
	Back = AutoPearlAggro:CreateToggle({
	    Name = "Switch back",
	    Function = function(Callback: boolean)
	        if BackDelay then
	            BackDelay.Object.Visible = Callback
	        end
	        if LandCheck then
	            LandCheck.Object.Visible = Callback
	        end
	    end,
	    Default = true,
	    Tooltip = "Switches back to the last slot before pearl"
	})
	LandCheck = AutoPearlAggro:CreateToggle({
	    Name = "Only after landed",
	    Tooltip = "Only switches back after your pearl landed",
	    Darker = true
	})
	Check = AutoPearlAggro:CreateToggle({
	    Name = "Pearl check",
	    Default = true,
	    Tooltip = "Doesn't throw a pearl while one of yours is still in the air, including ones you threw yourself"
	})
	BackDelay = AutoPearlAggro:CreateTwoSlider({
	    Name = "Switch Back Delay",
	    Min = 0,
	    Max = 2,
	    DefaultMin = 0.1,
	    DefaultMax = 0.2,
	    Darker = true
	})
	Distance = AutoPearlAggro:CreateSlider({
	    Name = "Distance limit",
	    Min = 10,
	    Max = 200,
	    Default = 150,
	    Suffix = "studs",
	    Tooltip = "How far away an enemy pearl can land before it is ignored"
	})
	MinHealth = AutoPearlAggro:CreateSlider({
	    Name = "Min health",
	    Min = 0,
	    Max = 100,
	    Default = 0,
	    Tooltip = "Never follows a pearl below this health, 0 disables the check"
	})
	Cooldown = AutoPearlAggro:CreateSlider({
	    Name = "Cooldown",
	    Min = 0,
	    Max = 5,
	    Default = 1,
	    Decimal = 10,
	    Suffix = "seconds",
	    Tooltip = "Minimum gap between two throws"
	})
	Limit = AutoPearlAggro:CreateToggle({
	    Name = "Limit to item",
	    Tooltip = "Only throws pearl when holding a pearl"
	})
end)

Run(function()
	local AutoPlay
	local Delay
	local Random
	
	local Pending: boolean = false
	local NextJoin: number = 0
	
	local function JoinQueue()
	    if Pending then
	        return
	    end
	
	    Pending = true
	    task.delay(Delay.Value, function()
	        Pending = false
	        local State = bedwars.Store:getState()
	        if not AutoPlay.Enabled or os.clock() < NextJoin or State.Game.customMatch or State.Party.leader.userId ~= LocalPlayer.UserId or State.Party.queueState ~= 0 then
	            return
	        end
	
	        NextJoin = os.clock() + 5
	        if Random.Enabled then
	            local Modes: {string} = {}
	            for QueueType: string, v: any in bedwars.QueueMeta do
	                if not v.disabled and not v.voiceChatOnly and not v.rankCategory then
	                    table.insert(Modes, QueueType)
	                end
	            end
	            bedwars.QueueController:joinQueue(Modes[math.random(1, #Modes)])
	        else
	            bedwars.QueueController:joinQueue(store.queueType)
	        end
	    end)
	end
	
	AutoPlay = vape.Categories.Utility:CreateModule({
	    Name = "AutoQueue",
	    Function = function(Callback: boolean)
	        if Callback then
	            AutoPlay:Clean(VapeEvents.EntityDeathEvent.Event:Connect(function(DeathTable)
	                if DeathTable.finalKill and DeathTable.entityInstance == LocalPlayer.Character and #bedwars.Store:getState().Party.members <= 0 and store.matchState ~= 2 then
	                    JoinQueue()
	                end
	            end))
	            AutoPlay:Clean(VapeEvents.MatchEndEvent.Event:Connect(JoinQueue))
	        end
	    end,
	    Tooltip = "Automatically queues after the match ends."
	})
	
	Delay = AutoPlay:CreateSlider({
	    Name = "Delay",
	    Min = 0,
	    Max = 10,
	    Decimal = 10,
	    Default = 0,
	    Suffix = function(Value: number)
	        return Value == 1 and "second" or "seconds"
	    end,
	    Tooltip = "How long to wait after the match ends, or after your final death when you are solo, before queueing"
	})
	Random = AutoPlay:CreateToggle({
	    Name = "Random",
	    Tooltip = "Chooses a random mode"
	})
end)

Run(function()
	local AutoReset
	local Delay
	local Pearl
	local Whisper
	local Lasso
	local LowestPoint: number = math.huge
	
	local function GetVoidLine(): number
	    if LowestPoint == math.huge then
	        for _, v: BasePart in store.blocks do
	            local Point: number = (v.Position.Y - (v.Size.Y / 2)) - 50
	            if Point < LowestPoint then
	                LowestPoint = Point
	            end
	        end
	    end
	    return LowestPoint
	end
	
	local function IsLassoed(): boolean
	    for _, v: Instance in LocalPlayer.Character and LocalPlayer.Character:GetChildren() or {} do
	        if v:IsA("Accessory") and v:FindFirstChild("Rope") then
	            return true
	        end
	    end
	    return false
	end
	
	local function CanSave(): boolean
	    if Pearl.Enabled and GetItem("telepearl") then
	        return true
	    end
	    if Whisper.Enabled and LocalPlayer:GetAttribute("IsOwlTarget") then
	        return true
	    end
	    return Lasso.Enabled and IsLassoed()
	end
	
	AutoReset = vape.Categories.Utility:CreateModule({
	    Name = "AutoReset",
	    Function = function(Callback: boolean)
	        if Callback then
	            local Falling
	            repeat
	                if store.matchState == 1 and Entity.isAlive then
	                    local Character = Entity.character
	                    local Root: BasePart = Character.RootPart
	                    if Falling and Falling ~= Character then
	                        Falling = nil
	                    end
	
	                    if not Falling and not CanSave() and Root.Position.Y < GetVoidLine() and Root.AssemblyLinearVelocity.Y < 0 and not workspace:Raycast(Root.Position, Vector3.new(0, -2000, 0), store.airRay) then
	                        Falling = Character
	                        task.delay(Delay.Value, function()
	                            if AutoReset.Enabled and Entity.isAlive and Entity.character == Character and Root.Parent and not CanSave() and Root.AssemblyLinearVelocity.Y < 0 and not workspace:Raycast(Root.Position, Vector3.new(0, -2000, 0), store.airRay) then
	                                bedwars.Handler:Get("ResetCharacter"):Fire("SendToServer")
	                            elseif Falling == Character then
	                                Falling = nil
	                            end
	                        end)
	                    end
	                else
	                    Falling = nil
	                end
	                task.wait(0.05)
	            until not AutoReset.Enabled
	        end
	    end,
	    Tooltip = "Resets once you fall past the void line so you can respawn sooner, leaving you room to clutch before then"
	})
	
	Delay = AutoReset:CreateSlider({
	    Name = "Delay",
	    Min = 0,
	    Max = 2,
	    Default = 0,
	    Decimal = 10,
	    Suffix = function(Value: number)
	        return Value == 1 and "second" or "seconds"
	    end,
	    Tooltip = "How long to wait before resetting. 0 resets instantly"
	})
	Pearl = AutoReset:CreateToggle({
	    Name = "Pearl check",
	    Default = true,
	    Tooltip = "Never resets while you are carrying a telepearl, so you keep the chance to pearl back"
	})
	Whisper = AutoReset:CreateToggle({
	    Name = "Whisper check",
	    Default = true,
	    Tooltip = "Never resets while an owl is assigned to you, so a Whisper can still lift you out"
	})
	Lasso = AutoReset:CreateToggle({
	    Name = "Lasso check",
	    Default = true,
	    Tooltip = "Never resets while a lasso is attached to you, so the pull can drag you back to safety"
	})
end)

Run(function()
	local AutoShoot
	local Targets
	local Projectiles
	local Mode -- remove the mode completely, only legit
	local FireRate
	local ChargeDelay
	local SwitchDelay
	
	local Listener
	
	local FireDelays = {}
	local Session: number = 0
	local Swapped: boolean = false
	local function IsHolding(Tool: Tool): boolean
	    local Hand: Instance? = LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HandInvItem")
	    return store.hand.tool == Tool or (Hand ~= nil and Hand.Value == Tool)
	end
	
	local function GetShots(): {{any}}
	    local List = Projectiles.ListEnabled
	
	    return GetProjectiles(List)
	end
	
	local function GetEntity()
	    local LocalPosition: Vector3 = Entity.character.RootPart.Position
	    local Entities = Entity.AllPosition({
	        Origin = LocalPosition,
	        Part = "RootPart",
	        Range = 22,
	        Players = Targets.Players.Enabled,
	        NPCs = Targets.NPCs.Enabled,
	        Priority = Targets.Priority.Value,
	        Wallcheck = Targets.Walls.Enabled,
	        Limit = 10
	    })
	    if #Entities > 0 then
	        for _, Player: any in Entities do
	            local LocalFacing: Vector3 = Entity.character.RootPart.CFrame.LookVector * Vector3.new(1, 0, 1)
	            local Delta: Vector3 = (Player.RootPart.Position - LocalPosition) * Vector3.new(1, 0, 1)
	            local Angle: number = LocalFacing.Magnitude > 0 and Delta.Magnitude > 0 and math.acos(math.clamp(LocalFacing.Unit:Dot(Delta.Unit), -1, 1)) or 0
	            if Angle > (math.rad(120) / 2) then
	                continue
	            end
	            
	            return Player
	        end
	    end
	    return nil
	end
	
	AutoShoot = vape.Categories.Utility:CreateModule({
	    Name = "AutoShoot",
	    Function = function(Callback: boolean)
	        Session += 1
	        Swapped = false
	
	        if Callback then
	            local Current: number = Session
	
	            Listener = bedwars.SyncEvents.BeginProjectileTargeting:setPriority(1000):connect(function(Event)
	                if Swapped then
	                    Event:setCancelled(true)
	                end
	            end) -- not required
	
	            local SwingStart: number? = nil
	            local Required: number = 0
	
	            repeat
	                local Swinging: boolean = Entity.isAlive and store.hand.toolType == "sword" and (tick() - bedwars.SwordController.lastSwing) < 0.2
	                if not Swinging then
	                    SwingStart = nil
	                elseif not SwingStart then
	                    SwingStart = os.clock()
	                    Required = ChargeDelay:GetRandomValue()
	                end
	
	                if SwingStart and (os.clock() - SwingStart) >= Required then
	                    local OldTool, OldHotbar = store.hand.tool, store.inventory.hotbarSlot
	
	                    for _, v: {any} in GetShots() do
	                        local Item, Ammo, Projectile, ItemMeta = unpack(v)
	                        local CooldownId: string = ItemMeta.cooldownId or (Item.itemType .. "-proj-source")
	                        if (FireDelays[Item.itemType] or 0) < os.clock() and not bedwars.AbilityController.cooldownController:isOnCooldown(CooldownId) then
	                            local Ent = GetEntity()
	                            if Ent then
	                                local Hotbar: number? = GetHotbar(Item.tool)
	                                if Hotbar or Mode.Value ~= "Legit" then
	                                    if not IsHolding(Item.tool) then
	                                        Swapped = true
	                                        SwitchItem(Item.tool, 0)
	
	                                        if Mode.Value == "Legit" then
	                                            HotbarSwitch(Hotbar) -- hotkey instead of this function
	                                        end
	
	                                        task.wait(math.max(0.04, (store.ping and store.ping.total) or 0))
	                                    end
	
	                                    local Meta = bedwars.ProjectileMeta[Projectile]
	                                    local ProjectileSpeed, Gravity = Meta.launchVelocity, Meta.gravitationalAcceleration or 196.2
	                                    local Origin: Vector3 = Entity.character.RootPart.Position
	                                    local TargetPosition = Ent and Prediction.SolveTrajectory(Origin, ProjectileSpeed, Gravity, Ent.RootPart.Position, Ent.RootPart.AssemblyLinearVelocity, workspace.Gravity, Ent.HipHeight, Ent.Jumping and 42.6 or nil, nil, Ent.Humanoid.FloorMaterial == Enum.Material.Air or math.abs(Ent.RootPart.AssemblyLinearVelocity.Y) > 0.01, Ent.RootPart.Position, Ent.RootPart, nil, true) or (not Ent and (Origin + Camera.CFrame.LookVector * 100))
	                                    if TargetPosition and IsHolding(Item.tool) then
	                                        local ShootPosition: Vector3 = (CFrame.new(Origin, TargetPosition) * CFrame.new(Vector3.new(-bedwars.BowConstantsTable.RelX, -bedwars.BowConstantsTable.RelY, -bedwars.BowConstantsTable.RelZ))).Position
	                                        local Aim: Vector3 = Ent and Prediction.SolveTrajectory(ShootPosition, ProjectileSpeed, Gravity, Ent.RootPart.Position, Ent.RootPart.AssemblyLinearVelocity, workspace.Gravity, Ent.HipHeight, Ent.Jumping and 42.6 or nil, nil, Ent.Humanoid.FloorMaterial == Enum.Material.Air or math.abs(Ent.RootPart.AssemblyLinearVelocity.Y) > 0.01, Ent.RootPart.Position, Ent.RootPart, nil, true) or TargetPosition
	                                        bedwars.ProjectileController:launchProjectileWithValues({ -- mouseclick instead of this
	                                            initialVelocity = CFrame.lookAt(ShootPosition, Aim).LookVector * ProjectileSpeed,
	                                            positionFrom = ShootPosition,
	                                            drawDurationSeconds = bedwars.getShotData(Item.itemType).drawDurationSec
	                                        }, Item.tool, bedwars.getSkinnedSource(Item, ItemMeta), Ammo, nil, Projectile):await()
	                                        FireDelays[Item.itemType] = os.clock() + (ItemMeta.fireDelaySec + FireRate:GetRandomValue())
	                                        bedwars.AbilityController.cooldownController:setOnCooldown(CooldownId, ItemMeta.fireDelaySec, {})
	                                        Prediction.trackShot(Ent.RootPart)
	                                        SwingStart = nil
	
	                                        task.wait(SwitchDelay:GetRandomValue())
	                                    end
	
	                                    if OldTool and OldTool ~= Item.tool then
	                                        if Mode.Value == "Legit" then
	                                            HotbarSwitch(OldHotbar) -- hotkey
	                                        else
	                                            SwitchItem(OldTool, 0)
	                                        end
	
	                                        local Deadline: number = os.clock() + 0.5
	                                        repeat
	                                            task.wait()
	                                        until not IsHolding(Item.tool) or os.clock() >= Deadline
	                                    end
	                                    Swapped = false
	                                end
	                            end
	                        end
	                    end
	                end
	                task.wait(0.02)
	            until not AutoShoot.Enabled or Session ~= Current
	        else
	            if Listener then
	                Listener:Destroy()
	            end
	
	            Listener = nil
	        end
	    end
	})
	
	Targets = AutoShoot:CreateTargets({Players = true, Walls = true})
	Projectiles = AutoShoot:CreateTextList({
	    Name = "Projectiles",
	    Default = {"arrow", "snowball"}
	})
	Mode = AutoShoot:CreateDropdown({
	    Name = "Mode",
	    List = {"Blatant", "Legit"},
	    Default = "Legit"
	})
	FireRate = AutoShoot:CreateTwoSlider({
	    Name = "Fire Rate",
	    Min = 0,
	    Max = 1,
	    DefaultMin = 0.05,
	    DefaultMax = 0.12,
	    Decimal = 100
	})
	ChargeDelay = AutoShoot:CreateTwoSlider({
	    Name = "Charge Delay",
	    Min = 0,
	    Max = 2,
	    DefaultMin = 0.25,
	    DefaultMax = 0.75,
	    Decimal = 100,
	    Tooltip = "How long your sword has to swing for before auto swapping"
	})
	SwitchDelay = AutoShoot:CreateTwoSlider({
	    Name = "Switch Delay",
	    Min = 0,
	    Max = 1,
	    DefaultMin = 0.02,
	    DefaultMax = 0.04,
	    Decimal = 100,
	    Suffix = "seconds"
	})
end)

Run(function()
	local AutoToxic
	local GG
	local GGMessage
	local Modes, Fixed, Lists, Said = {}, {}, {}, {}
	local Dead
	local Presets = {}
	local Names = {"Kill", "Death", "Bed", "BedDestroyed", "Win"}
	local Labels = {
	    Kill = "Kill",
	    Death = "Death",
	    Bed = "Bed",
	    BedDestroyed = "Bed destroyed",
	    Win = "Win"
	}
	local Variables = {
	    Kill = "[killed.player]",
	    Death = "[killer.player]",
	    Bed = "[bed.team]",
	    BedDestroyed = "[breaker.player]"
	}
	local Meanings = {
	    Kill = "the name of the player you killed",
	    Death = "the name of the player who killed you",
	    Bed = "the colour of the team whose bed you broke",
	    BedDestroyed = "the name of the player who broke your bed"
	}
	local Defaults = {
	    Kill = "imagine losing [killed.player] >> catvape",
	    Death = "my gaming chair subscription expired :( | [killer.player]",
	    Bed = "nice bed lul | [bed.team]",
	    BedDestroyed = "how dare you >:( | [breaker.player]",
	    Win = "yall garbage"
	}
	
	local function GetMessage(Name: string): string
	    if Modes[Name].Value == "Fixed" then
	        local Text: string = Fixed[Name].Value
	        return Text:match("%S") and Text or Defaults[Name]
	    end
	
	    local List: {string} = Lists[Name].ListEnabled
	    if #List == 0 then
	        return Defaults[Name]
	    end
	
	    local Index: number = math.random(1, #List)
	    if #List > 1 and List[Index] == Said[Name] then
	        Index = Index % #List + 1
	    end
	    Said[Name] = List[Index]
	
	    return List[Index]
	end
	
	local function FillMessage(Message: string, Name: string, Value: string): string
	    local Variable: string? = Variables[Name]
	    if Variable then
	        Message = Message:gsub((Variable:gsub("%p", "%%%0")), function()
	            return Value
	        end)
	    end
	
	    Message = Message:gsub("<obj>", function()
	        return Value
	    end)
	
	    return Message
	end
	
	local function SendMessage(Name: string, Value: string?)
	    if Modes[Name].Value == "Off" then
	        return
	    end
	
	    local Message: string = FillMessage(GetMessage(Name), Name, Value or "")
	    if not Message:match("%S") then
	        return
	    end
	
	    if TextChatService.ChatVersion == Enum.ChatVersion.TextChatService then
	        if TextChatService:CanUserChatAsync(LocalPlayer.UserId) then
	            TextChatService.ChatInputBarConfiguration.TargetTextChannel:SendAsync(Message)
	        else
	            TextChatService.ChatInputBarConfiguration.TargetTextChannel:SendPresetAsync(Presets["So close"])
	        end
	    else
	        ReplicatedStorage.DefaultChatSystemChatEvents.SayMessageRequest:FireServer(Message, "All")
	    end
	end
	
	local function IsActive(Name: string): boolean
	    return Modes[Name].Value ~= "Off"
	end
	
	AutoToxic = vape.Categories.Utility:CreateModule({
	    Name = "AutoToxic",
	    Function = function(Callback: boolean)
	        if Callback then
	            AutoToxic:Clean(VapeEvents.BedwarsBedBreak.Event:Connect(function(BedTable)
	                if IsActive("BedDestroyed") and BedTable.brokenBedTeam.id == LocalPlayer:GetAttribute("Team") then
	                    SendMessage("BedDestroyed", (BedTable.player.DisplayName or BedTable.player.Name))
	                elseif IsActive("Bed") and BedTable.player.UserId == LocalPlayer.UserId then
	                    local Team = bedwars.QueueMeta[store.queueType].teams[tonumber(BedTable.brokenBedTeam.id)]
	                    SendMessage("Bed", Team and Team.displayName:lower() or "white")
	                end
	            end))
	            AutoToxic:Clean(VapeEvents.EntityDeathEvent.Event:Connect(function(DeathTable)
	                if DeathTable.finalKill then
	                    local Killer: Player? = Players:GetPlayerFromCharacter(DeathTable.fromEntity)
	                    local Killed: Player? = Players:GetPlayerFromCharacter(DeathTable.entityInstance)
	                    if not Killed or not Killer then
	                        return
	                    end
	                    if Killed == LocalPlayer then
	                        if (not Dead) and Killer ~= LocalPlayer and IsActive("Death") then
	                            Dead = true
	                            SendMessage("Death", (Killer.DisplayName or Killer.Name))
	                        end
	                    elseif Killer == LocalPlayer and IsActive("Kill") then
	                        SendMessage("Kill", (Killed.DisplayName or Killed.Name))
	                    end
	                end
	            end))
	            AutoToxic:Clean(VapeEvents.MatchEndEvent.Event:Connect(function(WinTable)
	                if GG.Enabled then
	                    local Text: string = GGMessage.Value
	                    Text = Text:match("%S") and Text or "gg"
	                    if TextChatService.ChatVersion == Enum.ChatVersion.TextChatService then
	                        TextChatService.ChatInputBarConfiguration.TargetTextChannel:SendAsync(Text)
	                    else
	                        ReplicatedStorage.DefaultChatSystemChatEvents.SayMessageRequest:FireServer(Text, "All")
	                    end
	                end
	
	                local MyTeam = bedwars.Store:getState().Game.myTeam
	                if MyTeam and MyTeam.id == WinTable.winningTeamId or LocalPlayer.Neutral then
	                    SendMessage("Win")
	                end
	            end))
	        end
	    end,
	    Tooltip = "Says a message after a certain action\nEach action can be Off, Fixed (one message) or Rotating (random from a list)\nWrite a variable in a message and it is replaced with the real name\n[killed.player] - Kill\n[killer.player] - Death\n[bed.team] - Bed\n[breaker.player] - Bed destroyed"
	})
	
	GG = AutoToxic:CreateToggle({
	    Name = "AutoGG",
	    Default = true,
	    Function = function(Callback: boolean)
	        if GGMessage then
	            GGMessage.Object.Visible = Callback
	        end
	    end,
	    Tooltip = "Says a message when the match ends"
	})
	GGMessage = AutoToxic:CreateTextBox({
	    Name = "GG message",
	    Default = "gg",
	    Placeholder = "gg",
	    Darker = true
	})
	for _, v: string in Names do
	    local Tip: string = "Off - sends nothing\nFixed - sends the message below\nRotating - sends a random enabled entry from the list"
	    if Variables[v] then
	        Tip = `{Tip}\n{Variables[v]} - replaced with {Meanings[v]}`
	    end
	
	    Modes[v] = AutoToxic:CreateDropdown({
	        Name = `{Labels[v]} mode`,
	        List = {"Off", "Fixed", "Rotating"},
	        Function = function(Val: string)
	            Fixed[v].Object.Visible = Val == "Fixed"
	            Lists[v].Object.Visible = Val == "Rotating"
	        end,
	        Tooltip = Tip
	    })
	    Fixed[v] = AutoToxic:CreateTextBox({
	        Name = `{Labels[v]} message`,
	        Default = Defaults[v],
	        Placeholder = "Type a message",
	        Darker = true,
	        Visible = false
	    })
	    Lists[v] = AutoToxic:CreateTextList({
	        Name = v,
	        Darker = true,
	        Visible = false
	    })
	end
	
	task.spawn(pcall, function()
	    for _, Group: any in TextChatService:GetPresetsAsync().categoryGroups do
	        for _, Category: any in Group.categories do
	            for _, Message: any in Category.messages do
	                Presets[Message.value] = Message.presetId
	            end
	        end
	    end
	end)
end)

Run(function()
	local AutoVoidDrop
	local OwlCheck
	local AutoReset
	
	AutoVoidDrop = vape.Categories.Utility:CreateModule({
	    Name = "AutoVoidDrop",
	    Function = function(Callback: boolean)
	        if Callback then
	            repeat task.wait() until store.matchState ~= 0 or (not AutoVoidDrop.Enabled)
	            if not AutoVoidDrop.Enabled then
	                return
	            end
	
	            local LowestPoint: number = math.huge
	            for _, v: BasePart in store.blocks do
	                local Point: number = (v.Position.Y - (v.Size.Y / 2)) - 50
	                if Point < LowestPoint then
	                    LowestPoint = Point
	                end
	            end
	
	            repeat
	                if Entity.isAlive then
	                    local Root: BasePart = Entity.character.RootPart
	                    if Root.Position.Y < LowestPoint and (LocalPlayer.Character:GetAttribute("InflatedBalloons") or 0) <= 0 and not GetItem("balloon") then
	                        if not OwlCheck.Enabled or not Root:FindFirstChild("OwlLiftForce") then
	                            local Dropped: boolean = false
	                            for _, v: string in {"iron", "diamond", "emerald", "gold"} do
	                                v = GetItem(v)
	                                if v then
	                                    v = bedwars.Handler:Get("DropItem"):Fire("CallServer", {
	                                        item = v.tool,
	                                        amount = v.amount
	                                    })
	
	                                    if v then
	                                        v:SetAttribute("ClientDropTime", tick() + 100)
	                                        Dropped = true
	                                    end
	                                end
	                            end
	
	                            if Dropped and AutoReset.Enabled then
	                                bedwars.Handler:Get("ResetCharacter"):Fire("SendToServer")
	                            end
	                        end
	                    end
	                end
	
	                task.wait(0.1)
	            until not AutoVoidDrop.Enabled
	        end
	    end,
	    Tooltip = "Drops resources when you fall into the void"
	})
	
	OwlCheck = AutoVoidDrop:CreateToggle({
	    Name = "Owl check",
	    Default = true,
	    Tooltip = "Refuses to drop items if being picked up by an owl"
	})
	AutoReset = AutoVoidDrop:CreateToggle({
	    Name = "Auto Reset",
	    Tooltip = "Resets as soon as your resources are dropped"
	})
end)

Run(function()
	local AutoVote
	local Option
	local Delay
	local Notify
	
	local Request = bedwars.Handler:Get("CastPregameVote")
	local Voted: boolean
	
	AutoVote = vape.Categories.Utility:CreateModule({
	    Name = "AutoVote",
	    Function = function(Callback: boolean)
	        if Callback then
	            Voted = false
	
	            repeat
	                if store.matchState == 0 then
	                    if not Voted then
	                        Request:Fire("SendToServer", {votingOptionIndex = Option.Value - 1})
	                        Voted = true
	
	                        if Notify.Enabled then
	                            SendNotification("AutoVote", `Voted for option {Option.Value}`, 4)
	                        end
	                    end
	                else
	                    Voted = false
	                end
	                task.wait(Delay.Value)
	            until not AutoVote.Enabled
	        else
	            Voted = false
	        end
	    end,
	    Tooltip = "Casts your map vote the moment the pregame vote opens"
	})
	
	Option = AutoVote:CreateSlider({
	    Name = "Option",
	    Min = 1,
	    Max = 4,
	    Default = 1,
	    Tooltip = "Which of the voting options to pick, counting from the left"
	})
	Delay = AutoVote:CreateSlider({
	    Name = "Delay",
	    Min = 0.5,
	    Max = 10,
	    Default = 1,
	    Decimal = 10,
	    Suffix = "seconds"
	})
	Notify = AutoVote:CreateToggle({
	    Name = "Notify",
	    Default = true,
	    Tooltip = "Tells you when the vote goes in"
	})
end)

Run(function()
	local Clutch
	local OnVoid
	local FallDamage
	local Accuracy = {}
	local Allowance
	local BlockFall
	local Blocks
	local Speed
	local SilentAim
	local ResetAngle
	local ReturnSlot
	local MoveDelay
	local FailDelay
	local Staircase
	local LimitBlocks
	local MaxBlocks
	local Blacklist
	local HeldOnly
	local Whitelist
	local Label: TextLabel?
	local Placed, LastPlace, LastDanger, Falling = 0, 0, 0, false
	local CatchCell, CatchUntil, CatchSeen, CatchTries = nil, 0, false, 0
	local Impulse, ImpulseUntil = Vector3.zero, 0
	local GroundY: number?
	local MaxDrop: number = 512
	local ReachCells: number = 3
	local CatchStuds: number = 14
	local BridgeStuds: number = 14
	local CatchTime: number = 0.4
	local CatchLimit: number = 2
	
	local function GetClutchBlock()
	    if store.hand.toolType == "block" and (#Whitelist.ListEnabled == 0 or Blacklist.Enabled ~= (table.find(Whitelist.ListEnabled, store.hand.tool.Name) and true or false)) then
	        return store.hand.tool.Name, store.hand.amount, nil
	    end
	
	    if not HeldOnly.Enabled then
	        for _, v: any in store.inventory.inventory.items do
	            local Meta = bedwars.ItemMeta[v.itemType]
	            if Meta and Meta.block and (#Whitelist.ListEnabled == 0 or Blacklist.Enabled ~= (table.find(Whitelist.ListEnabled, v.itemType) and true or false)) then
	                return v.itemType, v.amount, v
	            end
	        end
	    end
	    return nil, 0, nil
	end
	
	local function IsDangerous(Position: Vector3): boolean
	    if not (OnVoid.Enabled or BlockFall.Enabled) then
	        return false
	    end
	
	    local Ray: RaycastResult? = Entity.Raycast(Position, Vector3.new(0, -MaxDrop, 0), store.airRay)
	    local Drop: number? = Ray and Position.Y - Ray.Position.Y or nil
	    if not Drop then
	        return OnVoid.Enabled
	    end
	    return BlockFall.Enabled and (Drop / 3) > Blocks.Value
	end
	
	local function GetBridge(State): Vector3?
	    local Feet: Vector3 = State.Position - Vector3.new(0, Entity.character.HipHeight + 1.5, 0)
	    local Level: number = GroundY or roundPos(Feet).Y
	    if Feet.Y < Level - 1.5 then
	        return nil
	    end
	
	    local Placement = Navigation:SolveVoid(State, {Channel = "clutch", Reach = BridgeStuds})
	    if Placement and IsDangerous(Placement.Position) then
	        return Placement.Position
	    end
	
	    local Under: Vector3 = Vector3.new(math.round(Feet.X / 3) * 3, Level, math.round(Feet.Z / 3) * 3)
	    local MoveDirection: Vector3 = Entity.character.Humanoid.MoveDirection
	    local Columns: {Vector3} = {Under}
	
	    if MoveDirection.Magnitude > 0 then
	        table.insert(Columns, roundPos(Under + MoveDirection * 3))
	        if Staircase.Enabled then
	            table.insert(Columns, roundPos(Under + MoveDirection * 3 + Vector3.new(0, 3, 0)))
	        end
	    end
	
	    for _, v: Vector3 in Columns do
	        for Depth: number = 0, ReachCells do
	            local Position: Vector3 = v - Vector3.new(0, Depth * 3, 0)
	            if getPlacedBlock(Position) then
	                break
	            end
	            if IsDangerous(Position) and Navigation:SolvePlacement(State, Navigation.WorldToGrid(Position), {Channel = "clutch", Reach = BridgeStuds}).Valid then
	                return Position
	            end
	        end
	    end
	    return nil
	end
	
	local function GetPlacement()
	    local Root: BasePart = Entity.character.RootPart
	    local State = {
	        Position = Root.Position,
	        Velocity = tick() < ImpulseUntil and Root.AssemblyLinearVelocity + Impulse or Root.AssemblyLinearVelocity,
	        Grounded = Entity.character.Humanoid.FloorMaterial ~= Enum.Material.Air
	    }
	
	    if State.Grounded and Entity.character.Humanoid.MoveDirection == Vector3.zero and (State.Velocity * Vector3.new(1, 0, 1)).Magnitude < 0.5 then
	        return nil, false
	    end
	
	    if not State.Grounded and CatchTries < CatchLimit and (FallDamage.Enabled or BlockFall.Enabled or OnVoid.Enabled) then
	        local Result = Navigation:FindClutch(State, {
	            Channel = "clutch",
	            Reach = CatchStuds,
	            BlocksAvailable = LimitBlocks.Enabled and math.max(MaxBlocks.Value - Placed, 0) or nil,
	            DamageAllowance = FallDamage.Enabled and math.min(Allowance.Value, math.max(Entity.character.Health - 1, 0)) or 1000,
	            Agent = {SafeMargin = Accuracy.Value / 100},
	            Clutch = {
	                MaxFall = BlockFall.Enabled and Blocks.Value * 3 or math.huge,
	                Void = OnVoid.Enabled
	            }
	        })
	
	        if Result.Success then
	            return Result.BridgePath[1].Position, true
	        elseif Result.Reason == "Safe" then
	            return nil, false
	        end
	    end
	
	    return GetBridge(State), false
	end
	
	Clutch = vape.Categories.Utility:CreateModule({
	    Name = "Clutch",
	    Function = function(Callback: boolean)
	        if Label then
	            if vape.ThreadFix then
	                setthreadidentity(8)
	            end
	
	            Label.Visible = Callback
	        end
	
	        if Callback then
	            local LastSlot: number?
	
	            Clutch:Clean(vapeEvents.EntityDamageEvent.Event:Connect(function(DamageTable)
	                if DamageTable.entityInstance ~= LocalPlayer.Character or not Entity.isAlive or not DamageTable.fromPosition then
	                    return
	                end
	                local Multiplier = DamageTable.knockbackMultiplier
	                if Multiplier and Multiplier.disabled then
	                    return
	                end
	
	                local Direction: Vector3 = bedwars.KnockbackUtil.getDirection(Entity.character.RootPart.Position, DamageTable.fromPosition)
	                if Direction.Magnitude > 0 then
	                    Impulse = bedwars.KnockbackUtil.calculateKnockbackVelocity(Direction, 1, Multiplier)
	                    ImpulseUntil = tick() + 0.2
	                end
	            end))
	
	            ;(function()
	                local Warned: number = 0
	
	                repeat
	                    if vape.ThreadFix then
	                        setthreadidentity(8)
	                    end
	
	                    local Success, ErrorMessage = pcall(function()
	                        if not Entity.isAlive then
	                            CatchCell, CatchSeen, CatchTries, Falling = nil, false, 0, false
	                            return
	                        end
	
	                        local Grounded: boolean = Entity.character.Humanoid.FloorMaterial ~= Enum.Material.Air
	                        if Grounded then
	                            GroundY = roundPos((Entity.character.RootPart.Position - Vector3.new(0, Entity.character.HipHeight + 1.5, 0))).Y
	                            Placed, CatchTries = 0, 0
	                        end
	
	                        if CatchCell then
	                            local Feet: Vector3 = (Entity.character.RootPart.Position - Vector3.new(0, Entity.character.HipHeight + 1.5, 0))
	                            local AimVelocity: Vector3 = tick() < ImpulseUntil and Entity.character.RootPart.AssemblyLinearVelocity + Impulse or Entity.character.RootPart.AssemblyLinearVelocity
	                            local AimElapsed: number = ((AimVelocity.Y + math.sqrt((AimVelocity.Y * AimVelocity.Y) + (2 * workspace.Gravity * math.max((Feet.Y - (CatchCell.Y + 1.5)), 0)))) / workspace.Gravity)
	                            local Aimed: Vector3 = Vector3.new(math.round((Feet.X + (AimVelocity.X * AimElapsed)) / 3) * 3, CatchCell.Y, math.round((Feet.Z + (AimVelocity.Z * AimElapsed)) / 3) * 3)
	                            if Grounded or Feet.Y < CatchCell.Y or (Aimed - CatchCell).Magnitude > 3 then
	                                CatchCell, CatchSeen = nil, false
	                            elseif getPlacedBlock(CatchCell) then
	                                CatchSeen = true
	                            elseif CatchSeen or tick() > CatchUntil then
	                                CatchCell, CatchSeen = nil, false
	                            end
	                        end
	
	                        local Position, Catching
	                        if not CatchCell then
	                            Position, Catching = GetPlacement()
	                        end
	
	                        if Position or Label then
	                            local ItemType, Amount, Item = GetClutchBlock()
	                            if Label then
	                                if vape.ThreadFix then
	                                    setthreadidentity(8)
	                                end
	
	                                Label.Text = `{Amount} <font color="rgb(170, 170, 170)">(Clutch)</font>`
	                                Label.TextColor3 = Color3.fromHSV((Amount / 128) / 2.8, 0.86, 1)
	                            end
	
	                            if Position and ItemType and (not LimitBlocks.Enabled or Placed < MaxBlocks.Value) then
	                                if not Falling then
	                                    Falling = true
	                                    LastSlot = store.inventory.hotbarSlot
	                                    task.wait(((MoveDelay.ValueMin + math.random() * (MoveDelay.ValueMax - MoveDelay.ValueMin)) / 60))
	                                    if vape.ThreadFix then
	                                        setthreadidentity(8)
	                                    end
	
	                                    Position = nil
	                                    if Entity.isAlive then
	                                        Position, Catching = GetPlacement()
	                                    end
	                                end
	
	                                local Now: number = workspace:GetServerTimeNow()
	                                local Interval: number = 1 / bedwars.SharedConstants.BLOCK_PLACE_CPS
	                                if Position and Now >= LastPlace then
	                                    local Slot = Item and getHotbar(Item.tool)
	                                    if Slot then
	                                        task.spawn(hotbarSwitch, Slot)
	                                    end
	                                    LastPlace = Now + math.max(1 / Speed.Value, Interval)
	                                    local Restore: CFrame?
	                                    if not SilentAim.Enabled then
	                                        Restore = Camera.CFrame
	                                        if vape.ThreadFix then
	                                            setthreadidentity(8)
	                                        end
	                                        Camera.CFrame = CFrame.lookAt(Restore.Position, Position)
	                                    end
	
	                                    local Success = bedwars.placeBlock(Position, ItemType)
	                                    if Restore then
	                                        task.delay(((ResetAngle.ValueMin + math.random() * (ResetAngle.ValueMax - ResetAngle.ValueMin)) / 60), function()
	                                            if vape.ThreadFix then
	                                                setthreadidentity(8)
	                                            end
	
	                                            Camera.CFrame = CFrame.lookAt(Camera.CFrame.Position, Camera.CFrame.Position + Restore.LookVector)
	                                        end)
	                                    end
	
	                                    if Success then
	                                        Placed += 1
	                                        if Catching then
	                                            CatchCell, CatchSeen = Position, false
	                                            CatchTries += 1
	                                            CatchUntil = tick() + CatchTime + math.clamp(store.ping.total or 0, 0, 0.3)
	                                        end
	                                    else
	                                        LastPlace = Now + math.max(FailDelay.Value / 1000, Interval)
	                                    end
	                                end
	                            end
	                        end
	
	                        if Position then
	                            LastDanger = tick()
	                        elseif Falling and (tick() - LastDanger) > 0.5 then
	                            Falling = false
	                            Placed = 0
	                            if ReturnSlot.Enabled and LastSlot then
	                                hotbarSwitch(LastSlot)
	                            end
	                            LastSlot = nil
	                        end
	                    end)
	
	                    if not Success and tick() > Warned then
	                        Warned = tick() + 5
	                        warn(`[catvape] clutch step failed: {ErrorMessage}`)
	                    end
	
	                    task.wait()
	                until not Clutch.Enabled
	            end)()
	        else
	            Falling, Placed, CatchCell, CatchSeen, CatchTries, ImpulseUntil, GroundY = false, 0, nil, false, 0, 0, nil
	        end
	    end,
	    Tooltip = "Saves yourself from falling"
	})
	
	OnVoid = Clutch:CreateToggle({
	    Name = "On void",
	    Tooltip = "Clutches when there is nothing at all beneath you"
	})
	FallDamage = Clutch:CreateToggle({
	    Name = "On fall damage",
	    Function = function(Callback: boolean)
	        if Accuracy.Object then
	            Accuracy.Object.Visible = Callback
	        end
	    end,
	    Default = true,
	    Tooltip = "Catches you as far down as it can while still landing you without damage"
	})
	Accuracy = Clutch:CreateSlider({
	    Name = "Accuracy",
	    Min = 50,
	    Max = 100,
	    Default = 100,
	    Darker = true,
	    Suffix = "%",
	    Tooltip = "How close to the real limit it cuts it, lower catches you higher up with room to spare"
	})
	Allowance = Clutch:CreateSlider({
	    Name = "Damage allowance",
	    Min = 0,
	    Max = 100,
	    Default = 0,
	    Suffix = "hp",
	    Tooltip = "Fall damage you are willing to eat, so it can catch you even lower"
	})
	BlockFall = Clutch:CreateToggle({
	    Name = "On more than x blocks",
	    Default = true
	})
	Blocks = Clutch:CreateSlider({
	    Name = "Blocks",
	    Min = 1,
	    Max = 30,
	    Default = 3,
	    Suffix = function(Val: number)
	        return Val <= 1 and "block" or "blocks"
	    end
	})
	Speed = Clutch:CreateSlider({
	    Name = "Speed",
	    Min = 1,
	    Max = 40,
	    Default = 20,
	    Suffix = "bps",
	    Tooltip = "Blocks placed per second"
	})
	SilentAim = Clutch:CreateToggle({
	    Name = "Silent aim",
	    Default = true,
	    Tooltip = "Places without turning your camera to the block"
	})
	ResetAngle = Clutch:CreateTwoSlider({
	    Name = "Reset angle delay",
	    Min = 0,
	    Max = 20,
	    DefaultMin = 3,
	    DefaultMax = 6,
	    Tooltip = "Ticks before your camera goes back to where it was"
	})
	ReturnSlot = Clutch:CreateToggle({
	    Name = "Return to last slot",
	    Tooltip = "Swaps back to whatever you were holding once you land"
	})
	MoveDelay = Clutch:CreateTwoSlider({
	    Name = "Clutch move delay",
	    Min = 0,
	    Max = 20,
	    DefaultMin = 2,
	    DefaultMax = 5,
	    Tooltip = "Ticks of reaction time before the first block goes down"
	})
	FailDelay = Clutch:CreateSlider({
	    Name = "Fail delay",
	    Min = 0,
	    Max = 1000,
	    Default = 0,
	    Suffix = "ms"
	})
	Staircase = Clutch:CreateToggle({
	    Name = "Allow staircase up",
	    Tooltip = "Also places ahead and above you so you can climb back up"
	})
	Clutch:CreateToggle({
	    Name = "Show block count",
	    Function = function(Callback: boolean)
	        if Callback then
	            Label = Instance.new("TextLabel")
	            Label.Size = UDim2.fromOffset(100, 20)
	            Label.Position = UDim2.new(0.5, 6, 0.5, 80)
	            Label.BackgroundTransparency = 1
	            Label.AnchorPoint = Vector2.new(0.5, 0)
	            Label.Text = "0"
	            Label.TextColor3 = Color3.new(0, 1, 0)
	            Label.TextSize = 18
	            Label.RichText = true
	            Label.Font = Enum.Font.Arial
	            Label.Visible = Clutch.Enabled
	            if vape.ThreadFix then
	                setthreadidentity(8)
	            end
	            Label.Parent = vape.gui
	        else
	            Label:Destroy()
	            Label = nil
	        end
	    end
	})
	LimitBlocks = Clutch:CreateToggle({
	    Name = "Limit blocks",
	    Default = true,
	    Tooltip = "Caps how many blocks one clutch is allowed to spend"
	})
	MaxBlocks = Clutch:CreateSlider({
	    Name = "Max blocks",
	    Min = 1,
	    Max = 32,
	    Default = 5
	})
	Blacklist = Clutch:CreateToggle({
	    Name = "Blacklist",
	    Tooltip = "Treats the list as blocks to avoid instead of blocks to use"
	})
	HeldOnly = Clutch:CreateToggle({
	    Name = "Held whitelist",
	    Tooltip = "Only clutches with the block already in your hand, never swaps for one"
	})
	Whitelist = Clutch:CreateTextList({
	    Name = "Whitelist",
	    Tooltip = "Block types the clutch is allowed to use"
	})
	
end)

Run(function()
	local DeviceSpoofer
	local Device
	local OldDevice, Old
	
	DeviceSpoofer = vape.Categories.Utility:CreateModule({
	    Name = "DeviceSpoofer",
	    Function = function(Callback: boolean)
	        if Callback then
	            OldDevice, Old = bedwars.UserInputController:getUserInputType(), bedwars.UserInputController.getUserInputType
	            bedwars.UserInputController.getUserInputType = function()
	                return Device.Value:upper()
	            end
	            bedwars.Handler:Get("SendUserInputType"):Fire("SendToServer", {userInputType = Device.Value:upper()})
	        else
	            bedwars.UserInputController.getUserInputType = Old
	            bedwars.Handler:Get("SendUserInputType"):Fire("SendToServer", {userInputType = OldDevice})
	            Old = nil
	        end
	    end,
	    Tooltip = "Spoofs the device you show up as to the server",
	    ExtraText = function()
	        return Device.Value
	    end
	})
	
	Device = DeviceSpoofer:CreateDropdown({
	    Name = "Device",
	    List = {"Mobile", "PC", "Gamepad"},
	    Function = function(Val: string)
	        if DeviceSpoofer.Enabled then
	            bedwars.Handler:Get("SendUserInputType"):Fire("SendToServer", {userInputType = Val:upper()})
	        end
	    end
	})
end)

Run(function()
	local KnockbackDelay
	local Chance
	local AirDelay
	local GroundDelay
	local TargetCheck
	
	local Old, RandomGenerator
	local function Apply(Type: string, Environment, ...)
	    local Root, Mass, Direction, Knockback = ...
	    Knockback = Knockback and table.clone(Knockback) or {}
	    Knockback[Type] = Environment[Type] and Knockback[Type] or 0
	    return Old(Root, Mass, Direction, Knockback, select(5, ...))
	end
	
	KnockbackDelay = vape.Categories.Utility:CreateModule({
	    Name = "KnockbackDelay",
	    Function = function(Callback: boolean)
	        if Callback then
	            Old, RandomGenerator = bedwars.KnockbackUtil.applyKnockback, Random.new()
	            bedwars.KnockbackUtil.applyKnockback = function(...)
	                if RandomGenerator:NextNumber(0, 100) > Chance.Value then
	                    return Old(...)
	                end
	
	                local Root, Mass, Direction, Knockback = ...
	                if not TargetCheck.Enabled or Entity.EntityPosition({
	                    Range = 50,
	                    Part = "RootPart",
	                    Players = true,
	                }) then
	                    local Environment = {}
	                    task.delay(AirDelay:GetRandomValue() / 1000, Apply, "horizontal", Environment, Root, Mass, Direction, Knockback, select(5, ...))
	                    task.delay(GroundDelay:GetRandomValue() / 1000, Apply, "vertical", Environment, Root, Mass, Direction, Knockback, select(5, ...))
	                    return
	                end
	                return Old(...)
	            end
	        else
	            bedwars.KnockbackUtil.applyKnockback = Old or bedwars.KnockbackUtil.applyKnockback
	        end
	    end,
	    Tooltip = "Delays incoming knockback packets"
	})
	
	Chance = KnockbackDelay:CreateSlider({
	    Name = "Chance",
