Run(function()
	local LegitAutoPlay
	local Reaction
	local TurnRate
	local ClickRate
	local Caution
	local Style
	local BreakBeds
	local CoverBed
	local Hunt
	local EmptyBeds
	local Debug
	
	local Agent
	local Senses
	local Brain
	local World
	local Walk: {[string]: any} = {}
	local Aim: {[string]: any} = {}
	local Combat: {[string]: any} = {}
	local Build: {[string]: any} = {}
	local Handlers: {[string]: any} = {}
	
	local Planar: Vector3 = Vector3.new(1, 0, 1)
	local Up: Vector3 = Vector3.new(0, 1, 0)
	local PathModel: Model = Instance.new("Model")
	PathModel.Name = "legitPathModel"
	PathModel.Parent = workspace.Terrain
	vape:Clean(function()
	    PathModel:Destroy()
	end)
	
	local Tuning = {
