	    SteerHold = 1.2,
	    SteerReach = 4,
	    TunnelDelay = 0.55,
	    TunnelReach = 9,
	    LearnTime = 30,
	    LearnInterval = 1.5,
	    WeaveWidth = 0.9,
	    WeaveRate = 0.33,
	    WeaveMinimum = 9,
	    PauseGap = {7, 16},
	    PauseLength = {0.15, 0.4},
	    PauseClear = 40,
	    HopGap = {9, 22},
	    HopDistance = 14,
	    StartDelay = {0.1, 0.28},
	    DropOvershoot = 3,
	    JumpRange = 3.4,
	    JumpRise = 1.2,
	    JumpCooldown = 0.5,
	    Lookahead = 3,
	    LookaheadClear = 1.2,
	    StuckTime = 1.4,
	    StuckDistance = 0.6,
	    RouteRetry = 0.8,
	    RouteFaults = 3,
	    Detour = 1.25,
	    SafeDrop = 6,
	    ShortfallLifetime = 30,
	    BlockReserve = 6,
	    BlockFloor = 16,
	    BlockTarget = 40,
	    BlockMargin = 1.45,
	    BridgeCap = 40,
	    CoverReach = 12,
	    CoverRadius = 7,
	    CoverTimeout = 14,
	    CoverPatience = 2,
	    BreakReach = 11,
	    BreakRadius = 6,
	    BreakInterval = 0.24,
	    BreakStall = 5,
	    MeleeReach = 11.4,
	    StrikeRange = 8.5,
	    StrikeCone = 28,
	    FightRange = 32,
	    DisengageRange = 44,
	    CloseRange = 3.6,
	    StrafeMin = 0.45,
	    StrafeMax = 1.1,
	    HitMemory = 3,
	    RetaliateValue = 45,
	    DefendRange = 32,
	    DefendValue = 85,
	    UnknownDamage = 24,
	    UnknownArmor = 0.2,
	    BareDamage = 12,
	    RetreatDistance = 30,
	    RetreatClear = 40,
	    BedValue = 100,
	    FightValue = 55,
	    HuntValue = 85,
	    CoverValue = 70,
	    FarmValue = 28,
	    WaitValue = 5,
	    LootRadius = 45,
	    LootTimeout = 14,
	    PickupRadius = 2.2,
	    DropSearch = 16,
	    SwitchDelay = 0.14,
	    LootValue = {iron = 30, diamond = 58, emerald = 72},
	    TravelWeight = 1.1,
	    RiskWeight = 45,
	    PurchaseGap = 0.35,
	    PurchaseLimit = 8,
	    PurchaseTimeout = 2,
	    CollectWait = 16,
	    CollectRadius = 4,
	    ShopRadius = 3.8,
	    ShopReach = 4.8,
	    BaseRadius = 80,
	    IdleDrift = 5,
	    EmergencyHealth = 0.18,
	    Phases = {
	        OPENING = {bed = 0.8, cover = 1.5, fight = 0.8, farm = 1.4},
	        EARLY = {bed = 1.1, cover = 1.2, fight = 0.9, farm = 1.2},
	        MIDGAME = {bed = 1.2, cover = 0.9, fight = 1, farm = 1},
	        ENDGAME = {bed = 1.1, cover = 0.5, fight = 1.2, farm = 0.7},
	        FINAL = {bed = 1, cover = 0.2, fight = 1.4, farm = 0.4}
	    },
	    Styles = {
	        Balanced = {bed = 1, cover = 1, fight = 1},
	        Aggressive = {bed = 1.25, cover = 0.7, fight = 1.2},
	        Defensive = {bed = 0.8, cover = 1.35, fight = 0.9}
	    },
	    Urgency = {parity = 90, now = 62, armor = 55, soon = 38, cover = 36, upgrade = 30, nice = 14},
	    Swords = {"wood_sword", "stone_sword", "iron_sword", "diamond_sword", "emerald_sword"},
	    Armors = {"leather_chestplate", "iron_chestplate", "diamond_chestplate", "emerald_chestplate"},
	    Tools = {"wood_pickaxe", "wood_axe", "shears"},
	    TeamUpgrades = {"ARMOR", "DAMAGE", "TEAM_GENERATOR"},
	    CoverItems = {"stone_brick", "wood_plank_oak"},
	    GearPlan = {{at = 0, item = "stone_sword"}, {at = 50, item = "leather_chestplate"}, {at = 100, item = "iron_chestplate"}, {at = 150, item = "iron_sword"}},
	    Faces = {Vector3.new(1, 0, 0), Vector3.new(-1, 0, 0), Vector3.new(0, 0, 1), Vector3.new(0, 0, -1), Vector3.new(0, 1, 0)},
	    CellProbe = Vector3.new(2.4, 2.4, 2.4)
	}
	
	local function Jitter(Base: number, Spread: number): number
	    return Base * (1 + (math.random() * 2 - 1) * Spread)
	end
	
	local function Reset()
	    Brain = {
	        goal = nil,
	        failures = {},
	        nextObserve = 0,
	        nextThink = 0,
	        readyAt = 0,
	        nextPlace = 0,
	        nextBreak = 0,
	        nextSwing = 0,
	        placed = {},
	        bought = {},
	        estimates = {},
	        dirty = false,
	        began = os.clock(),
	        hitAt = -math.huge,
	        active = false
	    }
	    World = {
	        self = {resources = {}, armorSlots = {}, ratio = 1, blocks = 0, sword = 0, armor = 0},
	        teams = {},
	        enemies = {},
	        homes = {},
	        broken = {},
	        match = {elapsed = 0, phase = "OPENING", enemyBeds = 0, enemyTeams = 0, enemyPlayers = 0, ownBed = true}
	    }
	    Walk.Request, Walk.Key, Walk.Target, Walk.RetryAt, Walk.Faults = nil, nil, nil, 0, 0
	    Walk.Seed, Walk.BlockedAt, Walk.Deflect, Walk.Tunnels = math.random() * 100, nil, nil, false
	    Walk.NextPause, Walk.PauseUntil, Walk.NextHop, Walk.IdleSince, Walk.Weaving = 0, 0, 0, nil, true
	    Walk.Commanded, Walk.CommandedAt, Walk.JumpedAt, Walk.Progress, Walk.ProgressAt = nil, 0, 0, nil, 0
	    Combat.Reset()
	end
	
	local function Warn(Text: string)
	    if Debug and Debug.Enabled then
	        warn(`[catvape] legitautoplay {Text}`)
	    end
	end
	
	local function Alive(): boolean
	    local Character: Model? = LocalPlayer.Character
	    return Entity.isAlive and Character ~= nil and (Character:GetAttribute("Health") or 0) > 0
	end
	
	local function CanSee(Position: Vector3): boolean
	    local Head: BasePart? = Entity.character.Head
	    local Eye: Vector3 = Head and Head.Position or Entity.character.RootPart.Position + Up * 2
	    return workspace:Raycast(Eye, Position - Eye, Senses.Params) == nil
	end
	
	local function Elapsed(): number
	    local State = bedwars.Store and bedwars.Store:getState()
	    local Started = State and State.Game and State.Game.startTime
	    if Started and Started > 0 then
	        return math.max(workspace:GetServerTimeNow() - Started, 0)
	    end
	    return os.clock() - Brain.began
	end
	
	local function Known(Record, Now: number): boolean
	    return Record.alive and Record.position ~= nil and Now - Record.seenAt <= Tuning.Memory
	end
	
	local function Visible(Record, Now: number): boolean
	    return Record.alive and Record.root ~= nil and Now - Record.seenAt <= 0.6
	end
	
	local function Odds(Record): number
	    local Me = World.self
	    local TheirDamage: number = Record.gearAt and math.max(Record.sword, Tuning.BareDamage) or Tuning.UnknownDamage
	    local TheirArmor: number = Record.gearAt and Record.armor or Tuning.UnknownArmor
	    local MyDamage: number = math.max(Me.sword, Tuning.BareDamage)
	    local Needed: number = Me.health / math.max(TheirDamage * (1 - Me.armor), 1)
	    local Dealt: number = (Record.health or 100) / math.max(MyDamage * (1 - TheirArmor), 1)
	    return Needed / (Needed + Dealt)
	end
	
	local function Danger(Position: Vector3, Radius: number, Now: number, Except): number
	    local Total: number = 0
	    for _, v: any in World.enemies do
	        if v ~= Except and Known(v, Now) then
	            local Distance: number = (v.position - Position).Magnitude
	            if Distance < Radius then
	                Total += (1 - Distance / Radius) * (1.4 - Odds(v))
	            end
	        end
	    end
	    return Total
	end
	
	local function Nearest(Now: number): (any, number)
	    local Best, Distance = nil, math.huge
	    for _, v: any in World.enemies do
	        if Known(v, Now) then
	            local Gap: number = (v.position - World.self.position).Magnitude
	            if Gap < Distance then
	                Best, Distance = v, Gap
	            end
	        end
	    end
	    return Best, Distance
	end
	
	local function Threatened(Now: number): boolean
	    for _, v: any in World.enemies do
	        if v.alive and Now - v.hitAt <= Tuning.HitMemory then
	            return true
	        end
	    end
	    local Record, Distance = Nearest(Now)
	    return Record ~= nil and Distance <= Tuning.RetreatDistance and Odds(Record) < 0.5
	end
	
	local function Mark(Reason: string)
	    if not Brain.dirty then
	        Brain.readyAt = math.max(Brain.readyAt, os.clock() + Jitter(Reaction.Value / 1000, 0.3))
	    end
	    Brain.dirty = Brain.dirty or Reason
	    Brain.nextObserve = 0
	end
	
	local function Offer(Item: string)
	    local ShopItem = bedwars.Shop.getShopItem(Item, LocalPlayer)
	    if not ShopItem or (ShopItem.price or 0) <= 0 or ShopItem.disabled or ShopItem.lockedByForge or ShopItem.ignoredByKit and table.find(ShopItem.ignoredByKit, store.equippedKit) then
	        return nil
	    end
	
	    local Upgrade = ShopItem.require and ShopItem.require.teamUpgrade
	    if Upgrade and bedwars.Store then
	        local Upgrades = bedwars.Store:getState().Bedwars.teamUpgrades
	        if (Upgrades[Upgrade.upgradeId] or -1) < Upgrade.lowestTierIndex then
	            return nil
	        end
	    end
	    return {item = Item, currency = ShopItem.currency, price = ShopItem.price, cost = ShopItem.price, amount = ShopItem.amount, tiered = ShopItem.tiered}
	end
	
	local function TeamOffer(Item: string)
	    local Meta = bedwars.TeamUpgradeMeta and bedwars.TeamUpgradeMeta[Item]
	    if not Meta or not bedwars.Store or Meta.disabledInQueue and table.find(Meta.disabledInQueue, store.queueType) then
	        return nil
	    end
	
	    local Upgrades = bedwars.Store:getState().Bedwars.teamUpgrades[LocalPlayer:GetAttribute("Team")] or {}
	    local Index: number = (Upgrades[Item] or 0) + 1
	    local Tier = Meta.tiers[Index]
	    if not Tier or Tier.availableOnlyInQueue and not table.find(Tier.availableOnlyInQueue, store.queueType) then
	        return nil
	    end
	    return {item = Item, upgrade = true, currency = "diamond", price = Tier.cost, cost = Tier.cost, tier = Index}
	end
	
	local function Worth(Item: string): number
	    local Meta = bedwars.ItemMeta[Item]
	    return Meta and (Meta.sword and Meta.sword.damage or Meta.armor and Meta.armor.damageReductionMultiplier) or 0
	end
	
	local function NextTier(Chain: {string}, Current: number, Field: string): string?
	    for _, v: string in Chain do
	        local Meta = bedwars.ItemMeta[v]
	        local Value = Meta and Meta[Field] and (Meta[Field].damage or Meta[Field].damageReductionMultiplier)
	        if Value and Value > Current and Offer(v) then
	            return v
	        end
	    end
	    return nil
	end
	
	local function Scheduled(Field: string): number
	    local Best: number = 0
	    for _, v: any in Tuning.GearPlan do
	        local Meta = bedwars.ItemMeta[v.item]
	        if World.match.elapsed >= v.at and Meta and Meta[Field] then
	            Best = math.max(Best, Worth(v.item))
	        end
	    end
	    return Best
	end
	
	local function CoverItem(): string?
	    for _, v: string in Tuning.CoverItems do
	        if getItem(v) then
	            return v
	        end
	    end
	    return getWool()
	end
	
	local function BedCells(Bed: BasePart): {Vector3}
	    local Registry = bedwars.BlockController:getHandlerRegistry()
	    local Handler = Registry and Registry:getHandler(Bed.Name)
	    local Cells = Handler and Handler:getContainedPositions(Bed)
	    return Cells or {bedwars.BlockController:getBlockPosition(Bed.Position)}
	end
	
	local function OpenFaces(Bed: BasePart): {Vector3}
	    local Cells: {Vector3} = BedCells(Bed)
	    local Taken: {[string]: boolean} = {}
	    local Open: {Vector3} = {}
	    for _, v: Vector3 in Cells do
	        Taken[tostring(v)] = true
	    end
	    for _, v: Vector3 in Cells do
	        for _, Face: Vector3 in Tuning.Faces do
	            local Grid: Vector3 = v + Face
	            local Key: string = tostring(Grid)
	            if not Taken[Key] then
	                Taken[Key] = true
	                local Position: Vector3 = Grid * 3
	                if not getPlacedBlock(Position) and #workspace:GetPartBoundsInBox(CFrame.new(Position), Tuning.CellProbe, Senses.Overlap) == 0 then
	                    table.insert(Open, Position)
	                end
	            end
	        end
	    end
	    return Open
	end
	
	local function Observe(Now: number)
	    local Me, Match = World.self, World.match
	    local Character: Model = LocalPlayer.Character
	    Me.position = Entity.character.RootPart.Position
	    Me.team = tostring(LocalPlayer:GetAttribute("Team"))
	    Me.health = Character:GetAttribute("Health") or 0
	    Me.maxHealth = math.max(Character:GetAttribute("MaxHealth") or 100, 1)
	    Me.ratio = math.clamp(Me.health / Me.maxHealth, 0, 1)
	    Me.speed = getSpeed()
	
	    local Wool, Amount = getWool()
	    Me.wool, Me.blocks = Wool, Wool and Amount or 0
	    local Sword, Armor = Senses.Gear(store.inventory.inventory)
	    Me.sword, Me.armor, Me.armorSlots = Sword, 0, Armor
	    for _, v: number in Armor do
	        Me.armor += v
	    end
	    Me.armor = math.clamp(Me.armor, 0, 0.9)
	    table.clear(Me.resources)
	    for _, v: any in store.inventory.inventory.items do
	        Me.resources[v.itemType] = (Me.resources[v.itemType] or 0) + v.amount
	    end
	
	    local Teams = World.teams
	    table.clear(Teams)
	    for _, v: any in Senses.Beds() do
	        Teams[v.team] = {id = v.team, bed = v, members = 0, alive = 0}
	        World.homes[v.team] = v.position
	    end
	
	    for _, v: any in Senses.Roster() do
	        local Team = Teams[v.team]
	        if not Team then
	            Team = {id = v.team, members = 0, alive = 0}
	            Teams[v.team] = Team
	        end
	        Team.members += 1
	        Team.alive += v.alive and 1 or 0
	
	        if v.enemy then
	            local Record = World.enemies[v.id]
	            if not Record then
	                Record = {id = v.id, player = v.player, name = v.player.Name, seenAt = -math.huge, hitAt = -math.huge, sword = 0, armor = 0}
	                World.enemies[v.id] = Record
	            end
	
	            Record.team, Record.alive, Record.present = v.team, v.alive, Now
	            if v.alive then
	                Record.root, Record.health, Record.maxHealth, Record.protected = v.root, v.health, math.max(v.maxHealth, 1), v.protected
	                if (v.position - Me.position).Magnitude <= Tuning.SightRange and CanSee(v.position + Up * 1.5) then
	                    Record.position, Record.velocity, Record.seenAt = v.position, v.velocity, Now
	                    if v.gearKnown then
	                        Record.sword, Record.armor, Record.ranged, Record.gearAt = v.sword, v.armor, v.ranged, Now
	                    end
	                end
	            else
	                Record.root = nil
	            end
	        end
	    end
	
	    for Id: string, v: any in World.enemies do
	        if Now - v.present > 2 then
	            World.enemies[Id] = nil
	        end
	    end
	
	    local Own = Teams[Me.team]
	    Match.ownBed = Own ~= nil and Own.bed ~= nil
	    Match.enemyBeds, Match.enemyTeams, Match.enemyPlayers = 0, 0, 0
	    for TeamId: string, v: any in Teams do
	        if TeamId ~= Me.team and (v.members > 0 or EmptyBeds.Enabled and v.bed ~= nil) then
	            Match.enemyTeams += 1
	            Match.enemyPlayers += math.max(v.alive, v.members == 0 and 1 or 0)
	            Match.enemyBeds += v.bed and not v.bed.locked and 1 or 0
	        end
	    end
	
	    Match.elapsed = Elapsed()
	    if Match.enemyTeams == 0 then
	        Match.phase = "FINAL"
	    elseif Match.enemyBeds == 0 or Match.enemyPlayers <= 1 then
	        Match.phase = "FINAL"
	    elseif Match.enemyTeams <= 2 or not Match.ownBed then
	        Match.phase = "ENDGAME"
	    elseif Match.elapsed > 360 or Me.sword >= Worth("iron_sword") and Me.armor >= 0.3 then
	        Match.phase = "MIDGAME"
	    elseif Match.elapsed > 75 then
	        Match.phase = "EARLY"
	    else
	        Match.phase = "OPENING"
	    end
	end
	
	function Aim.Toward(Position: Vector3, Delta: number)
	    local Root: BasePart = Entity.character.RootPart
	    local Flat: Vector3 = (Position - Root.Position) * Planar
	    if Flat.Magnitude < 0.1 then
	        return 0
	    end
	
	    local Current: Vector3 = Root.CFrame.LookVector * Planar
	    local Error: number = math.deg(math.acos(math.clamp(Current.Unit:Dot(Flat.Unit), -1, 1)))
	    if Error < 0.5 then
	        return Error
	    end
	
	    local Limit: number = TurnRate.Value * Delta
	    local Fraction: number = math.min(Limit / Error, 1)
	    local Next: Vector3 = Current.Unit:Lerp(Flat.Unit, Fraction)
	    if Next.Magnitude > 0.01 then
	        Root.CFrame = CFrame.lookAt(Root.Position, Root.Position + Next.Unit)
	    end
	    return Error * (1 - Fraction)
	end
	
	function Aim.Hold(Active: boolean)
	    if Entity.isAlive then
	        Entity.character.Humanoid.AutoRotate = not Active
	    end
	end
	
	function Walk.Note(State: string, Detail: string?)
	    if Walk.Status ~= State then
	        Walk.Status = State
	        Warn(`walk {State}{Detail and ` {Detail}` or ""}`)
	    end
	end
	
	function Walk.Halt()
	    Walk.IdleSince = Walk.IdleSince or os.clock()
	    if Entity.isAlive then
	        Entity.character.Humanoid:MoveTo(Entity.character.RootPart.Position)
	    end
	    Walk.Commanded = nil
	end
	
	function Walk.Probe(Direction: Vector3, Distance: number, Lift: number?)
	    local Root: BasePart = Entity.character.RootPart
	    local Box: Vector3 = Vector3.new(Root.Size.X, Entity.character.HipHeight + Root.Size.Y / 2, Root.Size.X) - Tuning.ProbeShrink
	    return workspace:Blockcast(CFrame.new(Root.Position + Vector3.new(0, Lift or 0, 0)), Box, Direction * Distance, Senses.Params)
	end
	
	function Walk.Learn(Direction: Vector3, Now: number)
	    if Now - (Walk.LearnedAt or -math.huge) < Tuning.LearnInterval then
	        return
	    end
	
	    Walk.LearnedAt = Now
	    local Root: BasePart = Entity.character.RootPart
	    local Grid: Vector3 = Navigation.WorldToGrid(Root.Position + Direction * 3 - Vector3.new(0, Entity.character.HipHeight - 1.5, 0))
	    Agent.Memory:Route(Grid, "collision", Now)
	    if Navigation.World and Navigation.World.Learn then
	        Navigation.World:Learn(Grid.X, Grid.Y, Grid.Z, Tuning.LearnTime)
	        Navigation.World:Learn(Grid.X, Grid.Y + 1, Grid.Z, Tuning.LearnTime)
	    end
	    Agent:Invalidate("Blocked ahead")
	    Walk.Note("blocked", `learned {tostring(Grid)}`)
	end
	
	function Walk.Tunnel(Hit, Now: number): boolean
	    local Root: BasePart = Entity.character.RootPart
	    local Block = getPlacedBlock(Hit.Position - Hit.Normal * 1.2)
	    if not Block or Block.Name == "bed" or (Block.Position - Root.Position).Magnitude > Tuning.TunnelReach then
	        return false
	    end
	    if Now >= Brain.nextBreak then
	        Brain.nextBreak = Now + Jitter(0.3, 0.3)
	        task.spawn(bedwars.breakBlock, Block, true, true, nil, true)
	    end
	    Walk.Note("tunneling", Block.Name)
	    return true
	end
	
	function Walk.Steer(Aim: Vector3, Now: number): Vector3
	    local Root: BasePart = Entity.character.RootPart
	    local Offset: Vector3 = (Aim - Root.Position) * Planar
	    if Offset.Magnitude < 0.6 then
	        Walk.BlockedAt = nil
	        return Aim
	    end
	
	    local Direction: Vector3 = Offset.Unit
	    local Reach: number = math.min(Tuning.ProbeReach, Offset.Magnitude)
	    local Hit = Walk.Probe(Direction, Reach)
	    if not Hit then
	        Walk.BlockedAt = nil
	        return Aim
	    end
	
	    Walk.BlockedAt = Walk.BlockedAt or Now
	    if not Walk.Probe(Direction, Reach, Tuning.StepHeight) then
	        if Entity.character.Humanoid.FloorMaterial ~= Enum.Material.Air then
	            Walk.Jump(Now)
	        end
	        return Aim
	    end
	
	    if Now - Walk.BlockedAt >= Tuning.TunnelDelay and Walk.Tunnels and Walk.Tunnel(Hit, Now) then
	        return Aim
	    end
	
	    local Order: {number} = {}
	    local Side: number = if Walk.Deflect and Now < Walk.Deflect.Until then Walk.Deflect.Sign else 0
	    for _, Degrees: number in Tuning.SteerAngles do
	        if Side == 0 or math.sign(Degrees) == Side then
	            table.insert(Order, Degrees)
	        end
	    end
	    for _, Degrees: number in Tuning.SteerAngles do
	        if Side ~= 0 and math.sign(Degrees) ~= Side then
	            table.insert(Order, Degrees)
	        end
	    end
	
	    for _, Degrees: number in Order do
	        local Turned: Vector3 = CFrame.Angles(0, math.rad(Degrees), 0):VectorToWorldSpace(Direction)
	        if not Walk.Probe(Turned, Tuning.SteerReach) then
	            local Point: Vector3 = Root.Position + Turned * Tuning.SteerReach
	            if Senses.Ground(Point) then
	                Walk.Deflect = {Sign = math.sign(Degrees), Until = Now + Tuning.SteerHold}
	                if Now - Walk.BlockedAt > Tuning.SteerHold then
	                    Walk.Learn(Direction, Now)
	                end
	                return Point
	            end
	        end
	    end
	
	    Walk.Learn(Direction, Now)
	    return Root.Position
	end
	
	function Walk.Weave(Aim: Vector3, Now: number): Vector3
	    local Root: BasePart = Entity.character.RootPart
	    local Offset: Vector3 = (Aim - Root.Position) * Planar
	    if Offset.Magnitude < Tuning.WeaveMinimum or Walk.Weaving == false then
	        return Aim
	    end
	
	    local Direction: Vector3 = Offset.Unit
	    local Across: Vector3 = Vector3.new(-Direction.Z, 0, Direction.X)
	    local Sway: number = math.noise(Now * Tuning.WeaveRate, Walk.Seed, 0) * 2 * Tuning.WeaveWidth
	    local Point: Vector3 = Aim + Across * Sway
	    local Left: Vector3 = Root.Position + Across * 3
	    local Right: Vector3 = Root.Position - Across * 3
	    if Senses.Ground(Point) and Senses.Ground(Left) and Senses.Ground(Right) then
	        return Point
	    end
	    return Aim
	end
	
	function Walk.Floor(Position: Vector3): boolean
	    local Hit: RaycastResult? = workspace:Raycast(Position + Vector3.new(0, 2, 0), Vector3.new(0, -(Tuning.SafeDrop + 3), 0), Senses.Params)
	    return Hit ~= nil and Hit.Normal.Y > 0.5
	end
	
	function Walk.Reach(Position: Vector3): Vector3?
	    local Origin: Vector3 = Entity.character.RootPart.Position
	    local Flat: Vector3 = (Position - Origin) * Planar
	    local Distance: number = Flat.Magnitude
	    if Distance < 0.5 then
	        return Position
	    end
	
	    local Direction: Vector3 = Flat.Unit
	    local Last: Vector3? = nil
	    for Step: number = 1, math.ceil(Distance / 2) do
	        local Sample: Vector3 = Origin + Direction * math.min(Step * 2, Distance)
	        if not Walk.Floor(Sample) then
	            break
	        end
	        Last = Sample
	    end
	    return Last
	end
	
	function Walk.Command(Position: Vector3, Now: number, Trusted: boolean?)
	    Position = Walk.Steer(Position, Now)
	    if not Trusted then
	        local Safe: Vector3? = Walk.Reach(Position)
	        if not Safe then
	            Walk.Halt()
	            return
	        end
	        Position = Safe
	    end
	    Position = Walk.Weave(Position, Now)
	    if not Walk.Commanded or Now - Walk.CommandedAt >= Tuning.CommandInterval or (Position - Walk.Commanded).Magnitude > 2 then
	        Walk.Commanded, Walk.CommandedAt = Position, Now
	        Entity.character.Humanoid:MoveTo(Position)
	    end
	end
	
	function Walk.Jump(Now: number): boolean
	    local Humanoid: Humanoid = Entity.character.Humanoid
	    if Now - Walk.JumpedAt < Tuning.JumpCooldown or Humanoid.FloorMaterial == Enum.Material.Air then
	        return false
	    end
	
	    Walk.JumpedAt = Now
	    Humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
	    return true
	end
	
	function Walk.Sprint()
	    local Controller = bedwars.SprintController
	    if Controller and not Controller.sprinting then
	        pcall(Controller.startSprinting, Controller)
	    end
	end
	
	function Walk.Cancel()
	    if Walk.Request then
	        Walk.Request.Cancelled = true
	    end
	    Walk.Request, Walk.RequestKey, Walk.Key, Walk.Target = nil, nil, nil, nil
	    Walk.Faults, Walk.RetryAt = 0, 0
	    if Agent then
	        Agent:Invalidate()
	    end
	    Walk.Progress, Walk.ProgressAt = nil, 0
	end
	
	function Walk.Options(Now: number)
	    local Me = World.self
	    return {
	        Channel = "legitautoplay",
	        Mode = "Legit",
	        BlocksAvailable = math.max(Me.blocks - Tuning.BlockReserve, 0),
	        BlocksBudget = Tuning.BridgeCap,
	        Debug = Debug.Enabled,
	        Label = true,
	        Agent = {
	            WalkSpeed = Me.speed or getSpeed(),
	            MaxDrop = Tuning.SafeDrop
	        },
	        Traversal = {
	            Mover = "Jump",
	            MaxAirTime = 1.75,
	            Margin = 1,
	            Rise = 1,
	            Instant = false
	        },
	        Search = {
	            MaxSteps = 25000,
	            WalkSteps = 8000,
	            Fallback = false,
	            Smooth = false,
	            Bridge = true,
	            Tower = false,
	            JumpGap = false
	        }
	    }
	end
	
	function Walk.Fault(Key: string, Reason: string, Now: number)
	    Walk.Faults += 1
	    Walk.RetryAt = Now + math.min(Walk.Faults, 4) * Tuning.RouteRetry
	    Warn(`route fault {Key}: {Reason}`)
	end
	
	function Walk.Ask(Key: string, Position: Vector3, Threats: {Vector3}?, Now: number)
	    local Request = {Cancelled = false}
	    local From: Vector3 = Entity.character.RootPart.Position
	    Walk.Request, Walk.RequestKey = Request, Key
	    task.spawn(function()
	        local Success, Plan, Result = pcall(Agent.Draft, Agent, From, Position, Walk.Options(Now), Threats, Key, Request)
	        if Walk.Request ~= Request then
	            return
	        end
	
	        Walk.Request, Walk.RequestKey = nil, nil
	        local At: number = os.clock()
	        if not Success or not Plan then
	            Walk.Fault(Key, Success and Result and Result.Reason or tostring(Plan), At)
	            return
	        end
	
	        local Root = Alive() and Entity.character.RootPart
	        if not Root then
	            return
	        end
	
	        local Carried: number = World.self.blocks
	        local Needed: number = math.max(Plan:Pending(), Brain.estimates[Key] or 0)
	        if Plan.Result.Partial and Plan.Kind ~= "Retreat" then
	            Brain.shortfall = {key = Key, blocks = math.min(math.max(Needed, Carried + 16) + Tuning.BlockReserve, Tuning.BlockTarget), at = At}
	            Walk.Fault(Key, `route does not reach the goal with {Carried} blocks`, At)
	            Agent:Invalidate("Partial route")
	            return
	        end
	        if Plan:Pending() > Carried then
	            Brain.shortfall = {key = Key, blocks = math.min(Plan:Pending() + Tuning.BlockReserve, Tuning.BlockTarget), at = At}
	            Walk.Fault(Key, `needs {Plan:Pending()} blocks, carrying {Carried}`, At)
	            return
	        end
	
	        Agent:Adopt(Plan, {position = Root.Position, velocity = Root.AssemblyLinearVelocity, airborne = Entity.character.Humanoid.FloorMaterial == Enum.Material.Air}, At)
	        Walk.Key, Walk.Target, Walk.Faults = Key, Position, 0
	        Walk.Progress, Walk.ProgressAt = Root.Position, At
	    end)
	end
	
	function Walk.Ahead(Plan, Position: Vector3): Vector3
	    local Points = Plan.Waypoints
	    local Cursor: number = Plan.Cursor
	    local Best: Vector3 = Points[Cursor].Position
	    for i: number = Cursor + 1, math.min(Cursor + Tuning.Lookahead, #Points) do
	        local Previous, Candidate = Points[i - 1], Points[i]
	        if Candidate.Type ~= "Walk" or Candidate.Blocks or Candidate.AirTime or Previous.Blocks or math.abs(Candidate.Position.Y - Position.Y) > Tuning.LookaheadClear then
	            break
	        end
	
	        local Clear: boolean = true
	        local Offset: Vector3 = Candidate.Position - Position
	        for Step: number = 1, math.ceil(Offset.Magnitude / 3) do
	            local Sample: Vector3 = Position + Offset * (Step / math.ceil(Offset.Magnitude / 3))
	            if not Senses.Ground(Sample) then
	                Clear = false
	                break
	            end
	        end
	        if not Clear then
	            break
	        end
	        Best = Candidate.Position
	    end
	    return Best
	end
	
	function Walk.Place(Plan, Now: number): boolean
	    local Point = Plan.Waypoints[Plan.Cursor]
	    if not Point or not Point.Blocks then
	        return true
	    end
	
	    local Waiting: boolean = false
	    for _, v: any in Point.Blocks do
	        if not Plan:Solid(v.Grid) then
	            Waiting = true
	            local Root: BasePart = Entity.character.RootPart
	            if (v.Position - Root.Position).Magnitude <= Tuning.CoverReach + 4 and Build.Place(v.Position, nil, Now) then
	                break
	            end
	        end
	    end
	    return not Waiting
	end
	
	function Walk.Habits(Plan, Aim: Vector3, Now: number)
	    local Root: BasePart = Entity.character.RootPart
	    local Humanoid: Humanoid = Entity.character.Humanoid
	    local Remaining: number = ((Plan.Waypoints[#Plan.Waypoints].Position - Root.Position) * Planar).Magnitude
	    local Quiet: boolean = Danger(Root.Position, Tuning.PauseClear, Now, nil) == 0
	    local Open: boolean = Remaining > Tuning.HopDistance and Plan:Pending() == 0 and Humanoid.FloorMaterial ~= Enum.Material.Air
	    Walk.Weaving = Quiet and Plan:Pending() == 0
	
	    if Now >= Walk.NextPause then
	        Walk.NextPause = Now + Jitter((Tuning.PauseGap[1] + Tuning.PauseGap[2]) / 2, 0.4)
	        if Quiet and Open then
	            Walk.PauseUntil = Now + Tuning.PauseLength[1] + math.random() * (Tuning.PauseLength[2] - Tuning.PauseLength[1])
	        end
	    end
	    if Now >= Walk.NextHop then
	        Walk.NextHop = Now + Tuning.HopGap[1] + math.random() * (Tuning.HopGap[2] - Tuning.HopGap[1])
	        if Open and not Senses.Surface(Root.Position).narrow and Senses.Ground(Aim) then
	            Walk.Jump(Now)
	        end
	    end
	end
	
	function Walk.Follow(Plan, Now: number): string
	    local Root: BasePart = Entity.character.RootPart
	    local Humanoid: Humanoid = Entity.character.Humanoid
	    local Position: Vector3 = Root.Position
	
	    while Plan.Cursor <= #Plan.Waypoints do
	        local Point = Plan.Waypoints[Plan.Cursor]
	        local Flat: number = ((Point.Position - Position) * Planar).Magnitude
	        local Height: number = if Point.Type == "Drop" then Tuning.DropHeight else Tuning.WaypointHeight
	        if Flat <= Tuning.WaypointRadius and math.abs(Point.Position.Y - Position.Y) <= Height and (not Point.Blocks or Plan:Placed(Point)) then
	            Plan.Cursor += 1
	            Walk.Progress, Walk.ProgressAt = Position, Now
	        else
	            break
	        end
	    end
	
	    local Point = Plan.Waypoints[Plan.Cursor]
	    if not Point then
	        return "end"
	    end
	
	    if not Walk.Place(Plan, Now) then
	        local Pending: number = 0
	        local Reach: number = math.huge
	        for _, v: any in Point.Blocks or {} do
	            if not Plan:Solid(v.Grid) then
	                Pending += 1
	                Reach = math.min(Reach, (v.Position - Position).Magnitude)
	            end
	        end
	        Walk.Note("building", `waypoint {Plan.Cursor}/{#Plan.Waypoints} needs {Pending}, nearest {string.format("%.1f", Reach)} away, wool {World.self.blocks}`)
	        Walk.Halt()
	        Walk.ProgressAt = Now
	        return "building"
	    end
	
	    if Now < Walk.PauseUntil then
	        Walk.Halt()
	        return "moving"
	    end
	
	    local Aim: Vector3 = Walk.Ahead(Plan, Position)
	    if Point.Type == "Drop" then
	        local Following = Plan.Waypoints[Plan.Cursor + 1]
	        local Heading: Vector3 = ((Following or Point).Position - Position) * Planar
	        if Heading.Magnitude > 0.1 then
	            Aim = Point.Position + Heading.Unit * Tuning.DropOvershoot
	        end
	    end
	    if Walk.IdleSince and Now - Walk.IdleSince > 1 then
	        Walk.IdleSince = nil
	        Walk.PauseUntil = Now + Tuning.StartDelay[1] + math.random() * (Tuning.StartDelay[2] - Tuning.StartDelay[1])
	        return "moving"
	    end
	    Walk.IdleSince = nil
	    Walk.Sprint()
	    Walk.Command(Aim, Now, true)
	    Walk.Note("moving")
	    Walk.Habits(Plan, Aim, Now)
	
	    local Flat: number = ((Point.Position - Position) * Planar).Magnitude
	    if Point.Position.Y - Position.Y > Tuning.JumpRise and Flat <= Tuning.JumpRange then
	        Walk.Jump(Now)
	    end
	
	    if not Walk.Progress or (Position - Walk.Progress).Magnitude >= Tuning.StuckDistance then
	        Walk.Progress, Walk.ProgressAt = Position, Now
	    elseif Now - Walk.ProgressAt > Tuning.StuckTime then
	        Walk.ProgressAt = Now
	        if Humanoid.FloorMaterial ~= Enum.Material.Air and Walk.Jump(Now) then
	            return "moving"
	        end
	        local Grid: Vector3 = Point.Grid or Navigation.WorldToGrid(Point.Position)
	        Agent.Memory:Route(Grid, "collision", Now)
	        if Navigation.World then
	            local Here: Vector3 = Navigation.WorldToGrid(Position - Vector3.new(0, Humanoid.HipHeight - 1.5, 0))
	            for X: number = -1, 1 do
	                for Y: number = -1, 1 do
	                    for Z: number = -1, 1 do
	                        Navigation.World:Invalidate(Grid.X + X, Grid.Y + Y, Grid.Z + Z)
	                        Navigation.World:Invalidate(Here.X + X, Here.Y + Y, Here.Z + Z)
	                    end
	                end
	            end
	        end
	        Agent:Invalidate("Stuck against the route")
	        Walk.Note("stuck", `at waypoint {Plan.Cursor}/{#Plan.Waypoints} {Point.Type} {tostring(Point.Position)}`)
	        return "stuck"
	    end
	    return "moving"
	end
	
	function Walk.To(Key: string, Position: Vector3, Radius: number, Now: number, Vertical: number?, Threats: {Vector3}?): string
	    local Root: BasePart = Entity.character.RootPart
	    local Offset: Vector3 = Position - Root.Position
	    if (Offset * Planar).Magnitude <= Radius and math.abs(Offset.Y) <= (Vertical or 6) then
	        return "arrived"
	    end
	
	    local Plan = Agent:Current()
	    local Owned: boolean = Plan ~= nil and not Plan.Expired and Walk.Key == Key
	    if Owned and Plan:Stale() then
	        Agent:Invalidate("Route support changed")
	        Owned = false
	    end
	    if Owned and Walk.Target and (Position - Walk.Target).Magnitude > math.clamp(Offset.Magnitude * 0.25, 5, 30) then
	        Owned = false
	    end
	
	    if not Owned then
	        if Walk.Request and Walk.RequestKey ~= Key then
	            Walk.Request.Cancelled = true
	            Walk.Request, Walk.RequestKey = nil, nil
	        end
	        if not Walk.Request and Now >= Walk.RetryAt then
	            Walk.Ask(Key, Position, Threats, Now)
	        end
	        if not Plan or Plan.Expired or Walk.Key ~= Key then
	            Walk.Halt()
	            return if Walk.Faults >= Tuning.RouteFaults then "failed" else "routing"
	        end
	    end
	
	    if Plan.Cursor > #Plan.Waypoints then
	        Walk.Key = nil
	        return "end"
	    end
	    return Walk.Follow(Plan, Now)
	end
	
	function Build.Equip(Item: string): boolean
	    local Held = getItem(Item)
	    local Tool: Tool? = Held and Held.tool
	    if not Tool then
	        return false
	    end
	    if store.hand.tool == Tool then
	        return true
	    end
	
	    local Slot: number? = getHotbar(Tool)
	    if Slot and store.inventory.hotbarSlot ~= Slot then
	        Brain.nextPlace = workspace:GetServerTimeNow() + Jitter(Tuning.SwitchDelay, 0.3)
	        bedwars.Store:dispatch({type = "InventorySelectHotbarSlot", slot = Slot})
	    end
	    return false
	end
	
	function Build.Place(Position: Vector3, Item: string?, Now: number): boolean
	    local Block: string? = Item or getWool()
	    local Server: number = workspace:GetServerTimeNow()
	    if not Block or not canPlace() or Server < Brain.nextPlace or (Brain.placed[tostring(Position)] or 0) > Now then
	        return false
	    end
	    if not Build.Equip(Block) then
	        return false
	    end
	
	    Brain.nextPlace = Server + Jitter(1 / (bedwars.SharedConstants.BLOCK_PLACE_CPS or 12), 0.18)
	    Brain.placed[tostring(Position)] = Now + 0.8
	    task.spawn(bedwars.placeBlock, Position, Block)
	    return true
	end
	
	function Combat.Reset()
	    Combat.Target, Combat.Side, Combat.SideUntil, Combat.NextJump, Combat.NextTap = nil, 1, 0, 0, 0
	    Combat.Engaged = false
	end
	
	function Combat.Strafe(Target: Vector3, Distance: number, Now: number): Vector3
	    local Root: BasePart = Entity.character.RootPart
	    if Now >= Combat.SideUntil then
	        Combat.Side = -Combat.Side
	        Combat.SideUntil = Now + Jitter((Tuning.StrafeMin + Tuning.StrafeMax) / 2, 0.45)
	    end
	
	    local Radial: Vector3 = (Root.Position - Target) * Planar
	    local Lead: Vector3 = Radial.Magnitude > 0.1 and Radial.Unit or Root.CFrame.LookVector * Planar
	    local Tangent: Vector3 = Vector3.new(-Lead.Z, 0, Lead.X) * Combat.Side
	    local Hold: number = Tuning.CloseRange + 0.8
	    local Step: Vector3 = Tangent * 3 - Lead * math.clamp(Distance - Hold, -2, 4)
	    local Point: Vector3 = Root.Position + Step
	    if not Senses.Ground(Point) or Senses.Surface(Point).nearVoid then
	        Combat.Side = -Combat.Side
	        Combat.SideUntil = Now + Jitter(0.6, 0.3)
	        Point = Root.Position - Tangent * 3
	    end
	    return Point
	end
	
	function Combat.Step(Record, Now: number, Delta: number)
	    local Root: BasePart = Entity.character.RootPart
	    local Target: BasePart? = Record.root
	    if not Target or not Target.Parent then
	        Aim.Hold(false)
	        return false
	    end
	
	    Combat.Target, Combat.Engaged = Record, true
	    local Position: Vector3 = Target.Position
	    local Distance: number = ((Position - Root.Position) * Planar).Magnitude
	    Aim.Hold(true)
	    local Error: number = Aim.Toward(Position, Delta)
	
	    if Distance > Tuning.CloseRange + 1.5 then
	        local Velocity: Vector3 = (Record.velocity or Vector3.zero) * Planar
	        local Lead: Vector3 = Position + Velocity * math.min(Distance / math.max(World.self.speed or 20, 8), 0.4)
	        Walk.Sprint()
	        Walk.Command(Lead, Now)
	    else
	        Walk.Command(Combat.Strafe(Position, Distance, Now), Now)
	    end
	
	    if Now >= Combat.NextJump and Distance <= Tuning.StrikeRange and math.random() < 0.02 then
	        Combat.NextJump = Now + Jitter(1.6, 0.5)
	        Walk.Jump(Now)
	    end
	
	    local Reach: number = math.min(Tuning.StrikeRange, Tuning.MeleeReach - 2)
	    if Distance <= Reach and Error <= Tuning.StrikeCone and Now >= Brain.nextSwing then
	        Brain.nextSwing = Now + Jitter(1 / ClickRate.Value, 0.25)
	        Senses.Attack({target = Target, player = Record.player, owner = Record.team})
	    end
	    return true
	end
	
	local function Finish(Goal, Now: number, Success: boolean, Reason: string)
	    Warn(`{Goal.Kind} {Goal.Label} {Success and "done" or "dropped"}: {Reason}`)
	    if not Success then
	        local Failed = Brain.failures[Goal.Key]
	        Brain.failures[Goal.Key] = {count = (Failed and Failed.count or 0) + 1, at = Now}
	    end
	    Brain.goal = nil
	    Brain.dirty = Brain.dirty or "Goal ended"
	    Walk.Cancel()
	    Combat.Reset()
	    Aim.Hold(false)
	end
	
	local function Penalty(Key: string, Now: number): number
	    local Failed = Brain.failures[Key]
	    if not Failed then
	        return 0
	    end
	    return Tuning.FailureWeight * Failed.count * math.max(1 - (Now - Failed.at) / Tuning.FailureLifetime, 0)
	end
	
	local function Sites()
	    return Senses.Sites()
	end
	
	local function ClosestSite(List, Predicate)
	    local Best, Distance = nil, math.huge
	    for _, v: any in List do
	        if v.target.Parent and (not Predicate or Predicate(v)) then
	            local Gap: number = (v.position - World.self.position).Magnitude
	            if Gap < Distance then
	                Best, Distance = v, Gap
	            end
	        end
	    end
	    return Best, Distance
	end
	
	local function Travel(Position: Vector3): number
	    return ((Position - World.self.position) * Planar).Magnitude * Tuning.Detour / math.max(World.self.speed or 20, 8)
	end
	
	local function Wishlist()
	    local Me = World.self
	    local List = {}
	    local Phase = World.match.phase
	    if Me.blocks < Tuning.BlockFloor then
	        table.insert(List, {item = "wool_white", urgency = "now", blocks = Tuning.BlockTarget - Me.blocks})
	    end
	
	    local Short = Brain.shortfall
	    if Short and os.clock() - Short.at < Tuning.ShortfallLifetime and Me.blocks < Short.blocks then
	        table.insert(List, {item = "wool_white", urgency = "now", blocks = Short.blocks - Me.blocks})
	    end
	
	    local Blade: string? = NextTier(Tuning.Swords, Me.sword, "sword")
	    if Blade then
	        local Behind: boolean = false
	        for _, v: any in World.enemies do
	            if v.gearAt and (v.sword or 0) > Me.sword then
	                Behind = true
	            end
	        end
	        table.insert(List, {item = Blade, urgency = if Behind or Scheduled("sword") > Me.sword then "parity" else "nice"})
	    end
	
	    local Chest = bedwars.ItemMeta[Tuning.Armors[1]]
	    local Plate: number = Chest and Me.armorSlots[Chest.armor.slot] or 0
	    local Vest: string? = Chest and NextTier(Tuning.Armors, Plate, "armor") or nil
	    if Vest then
	        local Exposed: boolean = false
	        for _, v: any in World.enemies do
	            if v.gearAt and (v.armor or 0) > Me.armor + 0.05 then
	                Exposed = true
	            end
	        end
	        table.insert(List, {item = Vest, urgency = if Exposed or Scheduled("armor") > Plate then "armor" else "soon"})
	    end
	
	    if Phase ~= "OPENING" then
	        for _, v: string in Tuning.Tools do
	            if not getItem(v) and Offer(v) then
	                table.insert(List, {item = v, urgency = "soon"})
	            end
	        end
	    end
	
	    local Open: number = Brain.coverOpen or 0
	    if CoverBed.Enabled and Open >= Tuning.CoverPatience and Me.blocks < Open + Tuning.BlockReserve then
	        table.insert(List, {item = "wool_white", urgency = "cover", blocks = Open + Tuning.BlockReserve - Me.blocks})
	    end
	
	    if Phase ~= "OPENING" then
	        for _, v: string in Tuning.TeamUpgrades do
	            table.insert(List, {item = v, urgency = if v == "ARMOR" then "armor" else "upgrade", team = true})
	        end
	    end
	    return List
	end
	
	local function AddShop(List, Now: number)
	    local Me = World.self
	    local Shops = Sites()
	    local Base: Vector3? = World.homes[Me.team]
	    local Wanted = Wishlist()
	    table.sort(Wanted, function(A, B)
	        return Tuning.Urgency[A.urgency] > Tuning.Urgency[B.urgency]
	    end)
	
	    Brain.missing = nil
	    for _, Want in Wanted do
	        local Deal = if Want.team then TeamOffer(Want.item) else Offer(Want.item)
	        if Deal and (Brain.bought[Want.item] or -math.huge) + 1.5 < Now then
	            if Want.blocks and Deal.amount then
	                Deal.cost = Deal.price * math.max(math.ceil(Want.blocks / Deal.amount), 1)
	            end
	
	            local Have: number = Me.resources[Deal.currency] or 0
	            local Value: number = Tuning.Urgency[Want.urgency]
	            if Have >= Deal.cost then
	                local Site = ClosestSite(if Deal.upgrade then Shops.Upgrades else Shops.Shops, function(Candidate)
	                    return Deal.upgrade and Base ~= nil and (Candidate.position - Base).Magnitude <= Tuning.BaseRadius or not Deal.upgrade and (Candidate.owner == Me.team or Danger(Candidate.position, 25, Now, nil) < 0.4)
	                end)
	                if Site then
	                    table.insert(List, {
	                        Kind = "SHOP",
	                        Key = `shop:{Site.id}`,
	                        Label = Want.item,
	                        Position = Site.position,
	                        Site = Site,
	                        Value = Value,
	                        Risk = Danger(Site.position, 25, Now, nil),
	                        Reason = `{Want.urgency}: {Deal.price} {Deal.currency} on hand`
	                    })
	                    break
	                end
	            elseif not Brain.missing and Value >= Tuning.Urgency.soon then
	                Brain.missing = {currency = Deal.currency, need = Deal.cost, value = Value, item = Want.item}
	            end
	        end
	    end
	end
	
	local function AddFarm(List, Now: number)
	    local Me = World.self
	    local Need = Brain.missing
	    local Currency: string = Need and Need.currency or "iron"
	    local Weight: number = Tuning.Phases[World.match.phase].farm
	    local Site = ClosestSite(Sites().Generators, function(Candidate)
	        local Owner = Candidate.owner and World.teams[Candidate.owner]
	        local Open: boolean = Candidate.owner == Me.team or Owner ~= nil and (Owner.members == 0 or not Owner.bed)
	        if Candidate.resource ~= Currency then
	            return false
	        end
	        if Candidate.resource == "iron" then
	            return Open
	        end
	        return Danger(Candidate.position, 30, Now, nil) < 0.5
	    end)
	    if not Site then
	        return
	    end
	
	    local Value: number = (Need and Need.value * 0.8 or Tuning.FarmValue) * Weight
	    table.insert(List, {
	        Kind = "FARM",
	        Key = `farm:{Site.id}`,
	        Label = Site.id,
	        Position = Site.position,
	        Site = Site,
	        Currency = Currency,
	        Need = Need and Need.need or (Me.resources[Currency] or 0) + 24,
	        Value = Value,
	        Risk = Danger(Site.position, 25, Now, nil),
	        Reason = if Need then `{Need.need} {Currency} for {Need.item}` else "income"
	    })
	end
	
	local function AddCover(List, Now: number)
	    local Me = World.self
	    local Own = World.teams[Me.team]
	    Brain.coverOpen = 0
	    if not CoverBed.Enabled or not Own or not Own.bed or not Own.bed.part.Parent then
	        return
	    end
	
	    local Open = OpenFaces(Own.bed.part)
	    Brain.coverOpen = #Open
	    if #Open < Tuning.CoverPatience or Me.blocks < math.min(#Open, 6) then
	        return
	    end
	
	    local Weight: number = Tuning.Phases[World.match.phase].cover * Tuning.Styles[Style.Value].cover
	    table.insert(List, {
	        Kind = "COVER",
	        Key = "cover",
	        Label = "bed",
	        Position = Own.bed.position,
	        Bed = Own.bed,
	        Value = Tuning.CoverValue * Weight * math.min(#Open / 5, 1),
	        Risk = Danger(Own.bed.position, 20, Now, nil),
	        Reason = `{#Open} open faces`
	    })
	end
	
	local function AddRaid(List, Now: number)
	    if not BreakBeds.Enabled then
	        return
	    end
	
	    local Me = World.self
	    local Phase = Tuning.Phases[World.match.phase]
	    local Weights = Tuning.Styles[Style.Value]
	    local Targets = {}
	    local Positions = {}
	    for TeamId: string, v: any in World.teams do
	        if TeamId ~= Me.team and v.bed and not v.bed.locked and v.bed.part.Parent and (v.members > 0 or EmptyBeds.Enabled) then
	            table.insert(Targets, v)
	            table.insert(Positions, v.bed.position)
	        end
	    end
	    if #Targets == 0 then
	        return
	    end
	
	    local Costs = Navigation.World and Navigation:GetBlockCosts(Me.position, Positions, {Mode = "Legit"}) or {}
	    local Cheapest: number = math.huge
	    for i: number, v: any in Targets do
	        local Blocks: number = Costs[i] or 0
	        local Key: string = `raid:{v.id or v.bed.team}`
	        Brain.estimates[Key] = Blocks
	        Cheapest = math.min(Cheapest, Blocks)
	        if Blocks * Tuning.BlockMargin + Tuning.BlockReserve > Me.blocks and Blocks > 0 then
	            continue
	        end
	
	        local Defenders: number = Danger(v.bed.position, 28, Now, nil)
	        local Early: number = if Me.sword < Worth("stone_sword") and World.match.elapsed < 40 then 0.5 else 1
	        table.insert(List, {
	            Kind = "RAID",
	            Key = Key,
	            Label = `team {v.bed.team}`,
	            Position = v.bed.position,
	            Bed = v.bed,
	            Team = v.bed.team,
	            Value = Tuning.BedValue * Phase.bed * Weights.bed * Early,
	            Risk = Defenders,
	            Reason = `{math.floor(Blocks)} blocks, {string.format("%.1f", Defenders)} defence`
	        })
	    end
	
	    if Cheapest < math.huge and Cheapest * Tuning.BlockMargin + Tuning.BlockReserve > Me.blocks then
	        Brain.shortfall = {key = "raid", blocks = math.min(math.ceil(Cheapest * Tuning.BlockMargin) + Tuning.BlockReserve, Tuning.BlockTarget), at = Now}
	    end
	end
	
	local function AddLoot(List, Now: number)
	    local Me = World.self
	    local Best, Score = nil, -math.huge
	    for _, v: Instance in CollectionService:GetTagged("ItemDrop") do
	        local Worth: number? = Tuning.LootValue[v.Name]
	        if Worth and v:IsA("BasePart") and v.Parent and Walk.Floor(v.Position) then
	            local Offset: Vector3 = v.Position - Me.position
	            local Distance: number = (Offset * Planar).Magnitude
	            if Distance <= Tuning.LootRadius and math.abs(Offset.Y) <= 14 then
	                local Amount: number = v:GetAttribute("Amount") or 1
	                local Value: number = Worth * (0.7 + 0.15 * math.min(Amount, 6))
	                local Risk: number = Danger(v.Position, 20, Now, nil)
	                local Rank: number = Value - Distance * 0.4 - Risk * Tuning.RiskWeight
	                if Rank > Score then
	                    Best, Score = {Part = v, Value = Value, Risk = Risk, Amount = Amount}, Rank
	                end
	            end
	        end
	    end
	    if not Best then
	        return
	    end
	
	    local Id: string = Best.Part:GetAttribute("Id") or tostring(Best.Part.Position)
	    table.insert(List, {
	        Kind = "LOOT",
	        Key = `loot:{Id}`,
	        Label = Best.Part.Name,
	        Position = Best.Part.Position,
	        Part = Best.Part,
	        Value = Best.Value,
	        Risk = Best.Risk,
	        Reason = `{Best.Amount} on the ground`
	    })
	end
	
	local function AddCombat(List, Now: number)
	    local Me = World.self
	    local Phase = Tuning.Phases[World.match.phase]
	    local Weights = Tuning.Styles[Style.Value]
	    local Own = World.teams[Me.team]
	    local Home: Vector3? = Own and Own.bed and Own.bed.position or World.homes[Me.team]
	    for _, v: any in World.enemies do
	        if Known(v, Now) and not v.protected then
	            local Distance: number = (v.position - Me.position).Magnitude
	            local Chance: number = Odds(v)
	            local Hit: boolean = Now - v.hitAt <= Tuning.HitMemory
	            local Intruder: boolean = Home ~= nil and (v.position - Home).Magnitude <= Tuning.DefendRange
	            if Distance <= Tuning.FightRange or Hit or Intruder then
	                local Value: number = Tuning.FightValue * Phase.fight * Weights.fight * (0.4 + Chance)
	                if Hit then
	                    Value += Tuning.RetaliateValue
	                end
	                if Intruder then
	                    Value = math.max(Value, Tuning.DefendValue * (0.5 + Chance * 0.5))
	                end
	                if Chance < 0.35 and not Hit then
	                    Value *= 0.25
	                end
	                table.insert(List, {
	                    Kind = "FIGHT",
	                    Key = `fight:{v.id}`,
	                    Label = v.name,
	                    Position = v.position,
	                    Record = v,
	                    Value = Value,
	                    Risk = 0,
	                    Reason = `odds {string.format("%.2f", Chance)}{Hit and " retaliating" or ""}{Intruder and " intruder" or ""}`
	                })
	            end
	        end
	    end
	end
	
	local function AddRetreat(List, Now: number)
	    local Me = World.self
	    if Me.ratio >= Caution.Value / 100 then
	        return
	    end
	
	    local Record, Distance = Nearest(Now)
	    local Hunted: boolean = Record ~= nil and Distance <= Tuning.RetreatDistance + 10 or Now - Brain.hitAt <= Tuning.HitMemory
	    if not Hunted then
	        return
	    end
	
	    table.insert(List, {
	        Kind = "RETREAT",
	        Key = "retreat",
	        Label = "safe ground",
	        Position = Me.position,
	        Value = 150 * (1 - Me.ratio / math.max(Caution.Value / 100, 0.01)) + 60,
	        Risk = 0,
	        Reason = `health {math.floor(Me.ratio * 100)}%`
	    })
	end
	
	local function AddHunt(List, Now: number)
	    if not Hunt.Enabled then
	        return
	    end
	
	    local Match = World.match
	    if Match.enemyBeds > 0 and Match.phase ~= "FINAL" then
	        return
	    end
	
	    for _, v: any in World.enemies do
	        if v.alive and not v.protected then
	            local Position: Vector3? = if Known(v, Now) then v.position else World.homes[v.team]
	            if Position then
	                table.insert(List, {
	                    Kind = "HUNT",
	                    Key = `hunt:{v.id}`,
	                    Label = v.name,
	                    Position = Position,
	                    Record = v,
	                    Value = Tuning.HuntValue * Tuning.Phases[Match.phase].fight,
	                    Risk = Danger(Position, 20, Now, v),
	                    Reason = if Known(v, Now) then "last seen" else "checking their island"
	                })
	            end
	        end
	    end
	end
	
	local function AddWait(List, Now: number)
	    local Me = World.self
	    local Own = World.teams[Me.team]
	    local Position: Vector3? = Own and Own.bed and Own.bed.position or World.homes[Me.team] or Me.position
	    table.insert(List, {
	        Kind = "WAIT",
	        Key = "wait",
	        Label = "base",
	        Position = Position,
	        Value = Tuning.WaitValue,
	        Risk = 0,
	        Reason = "nothing better to do"
	    })
	end
	
	local function Score(Candidate, Now: number): number
	    local Current = Brain.goal
	    local Value: number = Candidate.Value - Travel(Candidate.Position) * Tuning.TravelWeight - Candidate.Risk * Tuning.RiskWeight - Penalty(Candidate.Key, Now)
	    if Current and Current.Key == Candidate.Key then
	        Value += Tuning.CommitBonus
	    end
	    return Value
	end
	
	local function Adopt(Candidate, Now: number)
	    local Previous = Brain.goal
	    Candidate.StartedAt = Now
	    Candidate.Phase = "APPROACH"
	    Walk.Tunnels = Candidate.Kind == "RAID" or Candidate.Kind == "HUNT"
	    if Previous then
	        Walk.Cancel()
	        Combat.Reset()
	    end
	    Aim.Hold(false)
	    Brain.goal = Candidate
	    Warn(`goal {Candidate.Kind} {Candidate.Label} ({string.format("%.0f", Candidate.Score)}): {Candidate.Reason}`)
	end
	
	local function Think(Now: number)
	    Brain.dirty = false
	    Brain.nextThink = Now + Tuning.ThinkInterval
	
	    local List = {}
	    AddShop(List, Now)
	    AddFarm(List, Now)
	    AddCover(List, Now)
	    AddLoot(List, Now)
	    AddRaid(List, Now)
	    AddCombat(List, Now)
	    AddRetreat(List, Now)
	    AddHunt(List, Now)
	    AddWait(List, Now)
	
	    local Best = nil
	    local Current = Brain.goal
	    local Stay = nil
	    for _, v: any in List do
	        v.Score = Score(v, Now)
	        if Current and v.Key == Current.Key then
	            Stay = v
	        end
	        if not Best or v.Score > Best.Score then
	            Best = v
	        end
	    end
	
	    if not Best then
	        return
	    end
	    if Stay then
	        for Key: string, v: any in Stay do
	            Current[Key] = v
	        end
	    end
	    if not Current or not Stay then
	        Adopt(Best, Now)
	        return
	    end
	    if Best.Key ~= Current.Key and Best.Score >= Stay.Score + Tuning.SwitchMargin then
	        Adopt(Best, Now)
	    end
	end
	
	function Handlers.WAIT(Goal, Now: number, Delta: number)
	    local Root: BasePart = Entity.character.RootPart
	    local Status: string = Walk.To(Goal.Key, Goal.Position, 9, Now)
	    if Status == "arrived" or Status == "end" then
	        if Now >= (Goal.DriftAt or 0) then
	            Goal.DriftAt = Now + Jitter(Tuning.IdleDrift, 0.6)
	            local Angle: number = math.random() * math.pi * 2
	            Walk.Command(Root.Position + Vector3.new(math.cos(Angle), 0, math.sin(Angle)) * 2.5, Now)
	        end
	    elseif Status == "failed" then
	        Finish(Goal, Now, false, "no route to the base")
	    end
	end
	
	function Handlers.FARM(Goal, Now: number, Delta: number)
	    local Held = getItem(Goal.Currency)
	    local Amount: number = Held and Held.amount or 0
	    if Amount >= Goal.Need then
	        Finish(Goal, Now, true, `collected {Amount} {Goal.Currency}`)
	        return
	    end
	
	    if Goal.Phase == "APPROACH" then
	        local Status: string = Walk.To(Goal.Key, Goal.Site.position, Tuning.CollectRadius, Now)
	        if Status == "arrived" or Status == "end" then
	            Goal.Phase, Goal.CollectAt = "COLLECT", Now
	            Walk.Cancel()
	            Walk.Halt()
	        elseif Status == "failed" then
	            Finish(Goal, Now, false, "no route to the generator")
	        end
	        return
	    end
	
	    local Offset: Vector3 = (Goal.Site.position - Entity.character.RootPart.Position) * Planar
	    if Offset.Magnitude > Tuning.DropSearch + Tuning.CollectRadius then
	        Goal.Phase = "APPROACH"
	        return
	    end
	    if Goal.Drop and not Goal.Drop.Parent then
	        Goal.Drop = nil
	    end
	    if not Goal.Drop and Now >= (Goal.DropAt or 0) then
	        Goal.DropAt = Now + 0.25
	        local Gap: number = math.huge
	        local Here: Vector3 = Entity.character.RootPart.Position
	        for _, v: Instance in CollectionService:GetTagged("ItemDrop") do
	            if v.Name == Goal.Currency and v:IsA("BasePart") and v.Parent and (v.Position - Goal.Site.position).Magnitude <= Tuning.DropSearch and Walk.Floor(v.Position) then
	                local Distance: number = (v.Position - Here).Magnitude
	                if Distance < Gap then
	                    Goal.Drop, Gap = v, Distance
	                end
	            end
	        end
	    end
	    if Goal.Drop and Goal.Drop.Parent then
	        Walk.Command(Goal.Drop.Position, Now)
	    elseif Now >= (Goal.DriftAt or 0) then
	        Goal.DriftAt = Now + Jitter(Tuning.IdleDrift, 0.6)
	        local Angle: number = math.random() * math.pi * 2
	        Walk.Command(Goal.Site.position + Vector3.new(math.cos(Angle), 0, math.sin(Angle)) * 2, Now)
	    end
	    if Now - Goal.CollectAt > Tuning.CollectWait + Goal.Need / 4 then
	        Finish(Goal, Now, false, "generator wait expired")
	    end
	end
	
	function Handlers.LOOT(Goal, Now: number, Delta: number)
	    local Part: BasePart = Goal.Part
	    if not Part.Parent then
	        Finish(Goal, Now, true, "picked up")
	        return
	    end
	    if Now - Goal.StartedAt > Tuning.LootTimeout then
	        Finish(Goal, Now, false, "could not reach it")
	        return
	    end
	
	    local Status: string = Walk.To(Goal.Key, Part.Position, Tuning.PickupRadius, Now, 6)
	    if Status == "arrived" or Status == "end" then
	        Walk.Command(Part.Position, Now)
	    elseif Status == "failed" then
	        Finish(Goal, Now, false, "no route to it")
	    end
	end
	
	function Handlers.SHOP(Goal, Now: number, Delta: number)
	    if Goal.Phase == "APPROACH" then
	        local Status: string = Walk.To(Goal.Key, Goal.Position, Tuning.ShopRadius, Now, 3)
	        local Close: boolean = (Entity.character.RootPart.Position - Goal.Position).Magnitude <= Tuning.ShopReach
	        if Status == "arrived" or Status == "end" and Close then
	            Goal.Phase, Goal.Bought, Goal.NextBuy, Goal.Rejected = "BUY", 0, Now + Jitter(Reaction.Value / 1000, 0.3), {}
	            Walk.Cancel()
	            Walk.Halt()
	        elseif Status == "end" then
	            Finish(Goal, Now, false, "route ended short of the shop")
	        elseif Status == "failed" then
	            Finish(Goal, Now, false, "no route to the shop")
	        end
	        return
	    end
	
	    local Pending = Goal.Pending
	    if Pending then
	        if Pending.done then
	            Goal.Pending = nil
	            if Pending.success then
	                Goal.Bought += 1
	                Brain.bought[Pending.item] = Now
	                Goal.NextBuy = Now + Jitter(Tuning.PurchaseGap, 0.4)
	            else
	                Goal.Rejected[Pending.item] = true
	            end
	        elseif Now - Pending.started > Tuning.PurchaseTimeout then
	            Goal.Rejected[Pending.item] = true
	            Goal.Pending = nil
	        end
	        return
	    end
	    if Now < Goal.NextBuy then
	        return
	    end
	    if Goal.Bought >= Tuning.PurchaseLimit then
	        Finish(Goal, Now, true, `bought {Goal.Bought} items`)
	        return
	    end
	
	    local Me = World.self
	    local Wanted = Wishlist()
	    table.sort(Wanted, function(A, B)
	        return Tuning.Urgency[A.urgency] > Tuning.Urgency[B.urgency]
	    end)
	    for _, Want in Wanted do
	        local Deal = if Want.team then TeamOffer(Want.item) else Offer(Want.item)
	        local Site = Goal.Site
	        local Eligible: boolean = Deal ~= nil and not Goal.Rejected[Want.item] and (Me.resources[Deal.currency] or 0) >= Deal.price
	        if Eligible and (Deal.upgrade == true) == (Site.shopId == nil) then
	            Pending = {started = Now, item = Want.item}
	            Goal.Pending = Pending
	            Senses.Buy({target = Site.target, position = Site.position, shopId = Site.shopId}, Deal, function(Success: boolean)
	                Pending.done, Pending.success = true, Success
	                if Success and not Deal.upgrade then
	                    bedwars.AudioManager:playAudio(bedwars.SoundList.BEDWARS_PURCHASE_ITEM)
	                    bedwars.Store:dispatch({type = "BedwarsAddItemPurchased", itemType = Deal.item})
	                    if Deal.tiered and bedwars.BedwarsShopController then
	                        bedwars.BedwarsShopController.alreadyPurchasedMap[Deal.item] = true
	                    end
	                end
	                Mark("Purchase")
	            end)
	            return
	        end
	    end
	    Finish(Goal, Now, Goal.Bought > 0, "nothing more to buy here")
	end
	
	function Handlers.COVER(Goal, Now: number, Delta: number)
	    local Bed: BasePart = Goal.Bed.part
	    if not Bed.Parent then
	        Finish(Goal, Now, false, "bed is gone")
	        return
	    end
	
	    local Root: BasePart = Entity.character.RootPart
	    if Goal.Phase == "APPROACH" then
	        local Status: string = Walk.To(Goal.Key, Goal.Position, Tuning.CoverRadius, Now)
	        if Status == "arrived" or Status == "end" and (Bed.Position - Root.Position).Magnitude <= Tuning.CoverReach then
	            Goal.Phase, Goal.CoverAt, Goal.PlacedAt = "COVER", Now, Now
	            Walk.Cancel()
	            Walk.Halt()
	        elseif Status == "failed" or Status == "end" then
	            Finish(Goal, Now, false, "cannot reach the bed")
	        end
	        return
	    end
	
	    local Open = OpenFaces(Bed)
	    Brain.coverOpen = #Open
	    if #Open == 0 then
	        Finish(Goal, Now, true, "bed is covered")
	        return
	    end
	    if Now - Goal.CoverAt > Tuning.CoverTimeout then
	        Finish(Goal, Now, false, "cover took too long")
	        return
	    end
	
	    local Block: string? = CoverItem()
	    if not Block then
	        Finish(Goal, Now, false, "out of cover blocks")
	        return
	    end
	
	    local Closest, Gap = nil, math.huge
	    for _, v: Vector3 in Open do
	        local Offset: Vector3 = v - Root.Position
	        if Offset.Magnitude <= Tuning.CoverReach and ((Offset * Planar).Magnitude > 2.4 or math.abs(Offset.Y) > 4) then
	            Aim.Toward(v, Delta)
	            if Build.Place(v, Block, Now) then
	                Goal.PlacedAt = Now
	            end
	            return
	        end
	        if Offset.Magnitude < Gap then
	            Closest, Gap = v, Offset.Magnitude
	        end
	    end
	
	    if Closest then
	        Walk.To("cover:reach", Closest, 4, Now)
	    end
	end
	
	function Handlers.RAID(Goal, Now: number, Delta: number)
	    local Bed: BasePart = Goal.Bed.part
	    if not Bed.Parent then
	        Finish(Goal, Now, true, "bed destroyed")
	        return
	    end
	
	    local Root: BasePart = Entity.character.RootPart
	    local Distance: number = (Bed.Position - Root.Position).Magnitude
	    if Goal.Phase == "APPROACH" then
	        local Status: string = Walk.To(Goal.Key, Goal.Position, Tuning.BreakRadius, Now, 8)
	        if Status == "arrived" or Distance <= Tuning.BreakReach and Senses.Ground(Root.Position) then
	            Goal.Phase, Goal.BreakAt, Goal.BrokeAt = "BREAK", Now, Now
	            Walk.Cancel()
	            Walk.Halt()
	        elseif Status == "end" then
	            Finish(Goal, Now, false, "route ended short of the bed")
	        elseif Status == "failed" then
	            Finish(Goal, Now, false, "no route to the bed")
	        end
	        return
	    end
	
	    if Distance > Tuning.BreakReach + 3 then
	        Goal.Phase = "APPROACH"
	        return
	    end
	
	    Aim.Toward(Bed.Position, Delta)
	    local Shield: number = Bed:GetAttribute("BedShieldEndTime") or 0
	    if Now >= Brain.nextBreak and Shield <= workspace:GetServerTimeNow() then
	        Brain.nextBreak = Now + Jitter(Tuning.BreakInterval, 0.3)
	        Goal.BrokeAt = Now
	        task.spawn(bedwars.breakBlock, Bed, true, true, nil, true)
	    end
	    if Now - Goal.BreakAt > Tuning.BreakStall + 20 then
	        Finish(Goal, Now, false, "bed will not break")
	    end
	end
	
	function Handlers.FIGHT(Goal, Now: number, Delta: number)
	    local Record = Goal.Record
	    if not Record.alive or Record.protected then
	        Finish(Goal, Now, true, "target is down")
	        return
	    end
	    if not Visible(Record, Now) then
	        if Known(Record, Now) then
	            Aim.Hold(false)
	            local Status: string = Walk.To(Goal.Key, Record.position, 4, Now)
	            if Status == "arrived" or Status == "failed" or Status == "end" then
	                Record.seenAt = -math.huge
	            end
	            return
	        end
	        Finish(Goal, Now, false, "lost sight of the target")
	        return
	    end
	    if (Record.position - World.self.position).Magnitude > Tuning.DisengageRange and Now - Record.hitAt > Tuning.HitMemory then
	        Finish(Goal, Now, false, "target got away")
	        return
	    end
	    Combat.Step(Record, Now, Delta)
	end
	
	function Handlers.HUNT(Goal, Now: number, Delta: number)
	    local Record = Goal.Record
	    if not Record.alive then
	        Finish(Goal, Now, true, "target is down")
	        return
	    end
	    if Visible(Record, Now) and (Record.position - World.self.position).Magnitude <= Tuning.FightRange then
	        Combat.Step(Record, Now, Delta)
	        return
	    end
	
	    Aim.Hold(false)
	    local Position: Vector3? = if Known(Record, Now) then Record.position else World.homes[Record.team]
	    if not Position then
	        Finish(Goal, Now, false, "nowhere to look")
	        return
	    end
	
	    Goal.Position = Position
	    local Status: string = Walk.To(Goal.Key, Position, 6, Now)
	    if Status == "failed" then
	        Finish(Goal, Now, false, "no route to the target")
	    elseif Status == "arrived" and not Known(Record, Now) then
	        Finish(Goal, Now, false, "they are not here")
	    end
	end
	
	function Handlers.RETREAT(Goal, Now: number, Delta: number)
	    local Me = World.self
	    if Me.ratio >= math.min(Caution.Value / 100 + 0.25, 0.9) and not Threatened(Now) then
	        Finish(Goal, Now, true, "recovered")
	        return
	    end
	
	    Aim.Hold(false)
	    local Own = World.teams[Me.team]
	    local Home: Vector3? = Own and Own.bed and Own.bed.position or World.homes[Me.team]
	    if Home and ((Home - Me.position) * Planar).Magnitude > 8 and Danger(Home, 20, Now, nil) < 0.6 and Walk.Faults < Tuning.RouteFaults then
	        Walk.To("retreat:home", Home, 8, Now)
	        return
	    end
	
	    local Record, Distance = Nearest(Now)
	    if Record and Distance <= Tuning.RetreatDistance then
	        local Away: Vector3 = ((Me.position - Record.position) * Planar)
	        if Away.Magnitude > 0.1 then
	            local Point: Vector3 = Me.position + Away.Unit * 14
	            if Senses.Ground(Point) then
	                Walk.Command(Point, Now)
	                return
	            end
	        end
	    end
	    Walk.Halt()
	end
	
	local function Gate(): boolean
	    if not Alive() or store.matchState ~= 1 or not isnetworkowner(Entity.character.RootPart) then
	        return false
	    end
	    return true
	end
	
	local function Step(Now: number, Delta: number)
	    if not Gate() then
	        if Brain.active then
	            Brain.active = false
	            Walk.Cancel()
	            Combat.Reset()
	            Aim.Hold(false)
	            Brain.goal = nil
	        end
	        return
	    end
	    if not Brain.active then
	        Brain.active = true
	        Mark("Resumed control")
	    end
	
	    Senses.Filter()
	    if Now >= Brain.nextObserve then
	        Brain.nextObserve = Now + Tuning.ObserveInterval
	        Observe(Now)
	    end
	    if Now >= Brain.readyAt and (Brain.dirty or Now >= Brain.nextThink) then
	        Think(Now)
	    end
	
	    local Goal = Brain.goal
	    if not Goal then
	        Walk.Halt()
	        return
	    end
	    if Now - Goal.StartedAt > Tuning.GoalTimeout and Goal.Kind ~= "WAIT" and Goal.Kind ~= "FIGHT" then
	        Finish(Goal, Now, false, "timed out")
	        return
	    end
	    Handlers[Goal.Kind](Goal, Now, Delta)
	end
	
	local function NewAgent()
	    return Navigation.newAgent({
	        Config = {
	            BlockReserve = Tuning.BlockReserve
	        },
	        Context = {
	            Player = LocalPlayer,
	            Players = Players,
	            Collection = CollectionService,
	            Entity = Entity,
	            Store = store,
	            bedwars = bedwars,
	            PathModel = PathModel,
	            PlacedBlock = getPlacedBlock,
	            Wool = getWool,
	            Item = getItem,
	            Hotbar = getHotbar,
	            CanPlace = canPlace,
	            CanSwing = canSwing,
	            Projectiles = getProjectiles,
	            FireProjectile = fireProjectile,
	            BreakEnabled = function()
	                return BreakBeds.Enabled
	            end,
	            DebugEnabled = function()
	                return Debug.Enabled
	            end
	        }
	    })
	end
	
	LegitAutoPlay = vape.Categories.Utility:CreateModule({
	    Name = "LegitAutoPlay",
	    Tags = {"Experimental"},
	    Function = function(Callback: boolean)
	        if Callback then
	            Agent = NewAgent()
	            Senses = Agent.Interface
	            Reset()
	            LegitAutoPlay.Brain, LegitAutoPlay.World, LegitAutoPlay.Agent, LegitAutoPlay.Walk = Brain, World, Agent, Walk
	
	            LegitAutoPlay:Clean(VapeEvents.BedwarsBedBreak.Event:Connect(function()
	                Senses.Mark("beds")
	                Mark("Bed destroyed")
	            end))
	            LegitAutoPlay:Clean(VapeEvents.EntityDeathEvent.Event:Connect(function(DeathTable)
	                if DeathTable.entityInstance == LocalPlayer.Character then
	                    Walk.Cancel()
	                    Combat.Reset()
	                    Brain.goal = nil
	                    return
	                end
	
	                local Killed: Player? = DeathTable.entityInstance and Players:GetPlayerFromCharacter(DeathTable.entityInstance)
	                local Record = Killed and World.enemies[tostring(Killed.UserId)]
	                if Record then
	                    Record.alive, Record.root, Record.seenAt = false, nil, -math.huge
	                    Mark("Enemy died")
	                end
	            end))
	            LegitAutoPlay:Clean(VapeEvents.EntityDamageEvent.Event:Connect(function(DamageTable)
	                if DamageTable.entityInstance ~= LocalPlayer.Character then
	                    return
	                end
	
	                local Source: Instance? = DamageTable.fromEntity
	                local Attacker: Player? = Source and Players:GetPlayerFromCharacter(Source)
	                local Record = Attacker and World.enemies[tostring(Attacker.UserId)]
	                Brain.hitAt = os.clock()
	                if Record then
	                    Record.hitAt = os.clock()
	                end
	                Mark("Under attack")
	            end))
	            LegitAutoPlay:Clean(VapeEvents.InventoryAmountChanged.Event:Connect(function()
	                Mark("Inventory changed")
	            end))
	            LegitAutoPlay:Clean(VapeEvents.PlaceBlockEvent.Event:Connect(function(BlockTable)
	                if BlockTable.player ~= LocalPlayer then
	                    Senses.Obstacle(BlockTable.blockRef.blockPosition * 3)
	                end
	            end))
	            if Entity.Events then
	                LegitAutoPlay:Clean(Entity.Events.LocalAdded:Connect(function()
	                    Mark("Respawned")
	                end))
	            end
	
	            LegitAutoPlay:Clean(RunService.Heartbeat:Connect(function(Delta: number)
	                local Now: number = os.clock()
	                local Success, Problem = xpcall(Step, debug.traceback, Now, Delta)
	                if not Success then
	                    warn(`[catvape] legitautoplay step failed: {Problem}`)
	                    Brain.errors = (Brain.errors or 0) + 1
	                    if Brain.errors >= 3 then
	                        Brain.errors = 0
	                        Brain.goal = nil
	                        Walk.Cancel()
	                        Combat.Reset()
	                        Aim.Hold(false)
	                    end
	                end
	            end))
	        else
	            Aim.Hold(false)
	            if Entity.isAlive then
	                Walk.Halt()
	            end
	            if Agent then
	                Agent:Destroy()
	            end
	            if Brain then
	                Brain.goal = nil
	            end
	            LegitAutoPlay.Brain, LegitAutoPlay.World, LegitAutoPlay.Agent = nil, nil, nil
	        end
	    end,
	    Tooltip = "Plays the match like a person would. It walks with the humanoid only, aims at a human turn speed and clicks at a human rate, and it weighs shopping, farming, covering your bed, raiding beds and fights against each other as the match changes"
	})
	
	Reaction = LegitAutoPlay:CreateSlider({
	    Name = "Reaction time",
	    Min = 100,
	    Max = 600,
	    Default = 240,
	    Suffix = "ms",
	    Tooltip = "How long it takes to react after something changes, like being hit or a bed breaking"
	})
	TurnRate = LegitAutoPlay:CreateSlider({
	    Name = "Turn speed",
	    Min = 120,
	    Max = 1080,
	    Default = 520,
	    Suffix = "deg/s",
	    Tooltip = "Fastest it turns to face a target, the character never snaps"
	})
	ClickRate = LegitAutoPlay:CreateSlider({
	    Name = "Click rate",
	    Min = 4,
	    Max = 14,
	    Default = 9,
	    Decimal = 10,
	    Suffix = "cps",
	    Tooltip = "Average sword swings per second, each click is randomised around it"
	})
	Caution = LegitAutoPlay:CreateSlider({
	    Name = "Retreat health",
	    Min = 5,
	    Max = 90,
	    Default = 35,
	    Suffix = "%",
	    Tooltip = "Health where it stops fighting and falls back to your bed when enemies are close"
	})
	Style = LegitAutoPlay:CreateDropdown({
	    Name = "Style",
	    List = {"Balanced", "Aggressive", "Defensive"},
	    Tooltip = "Balanced - weighs everything evenly\nAggressive - goes for beds and fights sooner\nDefensive - covers and defends your bed more"
	})
	BreakBeds = LegitAutoPlay:CreateToggle({
	    Name = "Break beds",
	    Default = true,
	    Tooltip = "Go after enemy beds, off it only farms, shops and fights"
	})
	CoverBed = LegitAutoPlay:CreateToggle({
	    Name = "Cover bed",
	    Default = true,
	    Tooltip = "Wall off the open sides of your own bed with the best blocks you carry"
	})
	Hunt = LegitAutoPlay:CreateToggle({
	    Name = "Hunt players",
	    Default = true,
	    Tooltip = "Once every enemy bed is gone it searches for the remaining players and finishes them"
	})
	EmptyBeds = LegitAutoPlay:CreateToggle({
	    Name = "Empty beds",
	    Tooltip = "Also go after beds whose team has no players, useful in custom matches and training rooms where there is nobody to fight"
	})
	Debug = LegitAutoPlay:CreateToggle({
	    Name = "Debug",
	    Tooltip = "Warn on every goal change with its score and the reason. LegitAutoPlay.Brain and LegitAutoPlay.World hold the live state"
	})
end)

Run(function()
	local MatchDodge
	local Mode
	local Timeout = {}
	local Skill = {}
	local RankCheck = {}
	local Amount = {}
	local AmountWhitelist = {}
	local Library = vape.Libraries.matchdodge or {}
	vape.Libraries.matchdodge = Library
	
	local Weights = {Win = 1, Combat = 0.5, Rank = 2, Kit = 1, KitPlays = 0.2, Experience = 0.15, Streak = 0.25, FinalKills = 0.5, BedBreaks = 0.5, Level = 0.2, Device = 0.4, Recent = 0.5}
	local DefenderClass = 2
	local HoverOption = 0
	local RoleThreat = {Juggernaut = 1, Breaker = 0.8, Defender = 0.6, Cycler = 0.5, Support = 0.4}
	local KitRoles = {
	    Defender = {"black_market_trader", "slime_tamer", "hannah", "fisherman", "farmer_cletus", "spirit_gardener"},
	    Cycler = {"fisherman", "metal_detector", "beekeeper", "cowgirl", "farmer_cletus", "steam_engineer", "spirit_gardener", "davey", "miner"},
	    Breaker = {"davey", "oil_man", "santa", "dino_tamer", "smoke", "yeti", "glacial_skater", "elk_master", "mimic", "shielder", "airbender"},
	    Support = {"baker", "soul_broker", "oasis", "melody", "hatter"},
	    Juggernaut = {"frost_hammer_kit", "axolotl", "summoner", "bigman", "pinata", "tinker", "blood_assassin", "miner", "aery", "nazar", "barbarian", "ice_queen", "block_kicker", "seahorse", "void_knight"}
	}
	local DeviceThreat = {PC = 1, GAMEPAD = 0.5, MOBILE = 0}
	local Ignored = {none = true, random = true, [""] = true}
	local PriorMatches = 10
	local FetchTimeout = 10
	local MaxTries = 3
	
	local HasAdvantage
	do
	    local Profiles = {}
	    local KitValue: {[string]: number} = {}
	    for Role: string, List: {string} in KitRoles do
	        for _, Kit: string in List do
	            KitValue[Kit] = math.max(KitValue[Kit] or 0, RoleThreat[Role])
	        end
	    end
	
	    for Kit: string, Meta: any in bedwars.BedwarsKitMeta or {} do
	        if Meta.kitClass == DefenderClass then
	            KitValue[Kit] = math.max(KitValue[Kit] or 0, RoleThreat.Defender)
	        end
	    end
	
	    local TopDivision: number?
	
	    local function GetRows(Data: any): {any}
	        local Rows = {}
	        for _, Match: any in Data.matchHistory or {} do
	            if Match.matchCancelled then
	                continue
	            end
	
	            for _, Row: any in Match.players or {} do
	                if Row.playerInfo and Row.playerInfo.userId == Data.userId then
	                    table.insert(Rows, {Queue = Match.queueType, Outcome = Row.generic and Row.generic.matchOutcome, Kit = Row.bedwars and Row.bedwars.kit})
	                    break
	                end
	            end
	        end
	
	        return Rows
	    end
	
	    local function Fetch(Player: Player)
	        local Entry = Profiles[Player]
	        if not Entry then
	            Entry = {Tries = 0, Retry = 0, Started = 0}
	            Profiles[Player] = Entry
	        end
	
	        local Now: number = os.clock()
	        if Entry.Done or (Entry.Pending and Now - Entry.Started < FetchTimeout) or (not Entry.Pending and Now < Entry.Retry) then
	            return Entry
	        end
	
	        if Entry.Tries >= MaxTries then
	            Entry.Done = true
	            return Entry
	        end
	
	        Entry.Pending, Entry.Started, Entry.Tries = true, Now, Entry.Tries + 1
	        local Try: number = Entry.Tries
	        task.spawn(function()
	            local Success, Data = pcall(function()
	                return bedwars.Handler:Get("RequestProfileData"):Fire("CallServer", Player)
	            end)
	
	            local RankSuccess, Rank = pcall(store.rank[Player].async)
	            if Entry.Tries ~= Try then
	                return
	            end
	
	            Entry.Pending = false
	            Entry.Retry = os.clock() + 5
	            
	            if Success and typeof(Data) == "table" and typeof(Data.queues) == "table" then
	                Entry.Data, Entry.Rank, Entry.Rows, Entry.Done = Data, RankSuccess and Rank or nil, GetRows(Data), true
	            end
	        end)
	        
	        return Entry
	    end
	
	    local function GetRoster()
	        local State = bedwars.Store:getState().Game
	        local Assigned = {}
	        for _, v: any in State.teams or {} do
	            for Index: any, Member: any in v.members or {} do
	                Assigned[tonumber(Member.userId or Index)] = tostring(v.id)
	            end
	        end
	
	        local Team: number? = LocalPlayer:GetAttribute("Team") or (State.myTeam and State.myTeam.id) or Assigned[LocalPlayer.UserId]
	        if not Team then
	            return nil
	        end
	
	        Team = tostring(Team)
	
	        local Allies, Opponents, Pending = {LocalPlayer}, {}, false
	        for _, v: Player in Players:GetPlayers() do
	            if v == LocalPlayer or v:GetAttribute("Spectator") then
	                continue
	            end
	
	            local Other = v:GetAttribute("Team") or Assigned[v.UserId]
	            if Other then
	                table.insert(tostring(Other) == Team and Allies or Opponents, v)
	            else
	                Pending = true
	            end
	        end
	
	        for UserId: number in Assigned do
	            if UserId ~= LocalPlayer.UserId and not Players:GetPlayerByUserId(UserId) then
	                Pending = true
	            end
	        end
	
	        return Allies, Opponents, Pending
	    end
	
	    local function GetRecent(Rows: {any}, Queue: string): (number, number)
	        local Wins, Losses = 0, 0
	        for _, Row: any in Rows do
	            if Row.Queue == Queue then
	                Wins += Row.Outcome == "win" and 1 or 0
	                Losses += Row.Outcome == "loss" and 1 or 0
	            end
	        end
	
	        return Wins, Losses
	    end
	
	    local function PredictKit(Entry: any, Banned: {[string]: any}): (string?, number)
	        local Counts: {[string]: number} = {}
	        for Kit: string, Plays: number in Entry.Data.favoriteKitData or {} do
	            Counts[Kit] = Plays
	        end
	
	        for _, Row: any in Entry.Rows do
	            if Row.Kit then
	                Counts[Row.Kit] = (Counts[Row.Kit] or 0) + 1
	            end
	        end
	
	        local Best: string?
	        local BestPlays: number, Total: number = 0, 0
	        for Kit: string, Plays: number in Counts do
	            if Ignored[Kit] then
	                continue
	            end
	
	            Total += Plays
	            if not Banned[Kit] and Plays > BestPlays then
	                Best, BestPlays = Kit, Plays
	            end
	        end
	
	        return Best, BestPlays / (Total + PriorMatches)
	    end
	
	    local function GetKit(Player: Player, Entry: any, Context: any): (string?, number)
	        local Kit: string? = Player:GetAttribute("PlayingAsKits")
	        if Kit and not Ignored[Kit] then
	            return Kit, 1
	        end
	
	        local UserId: string = tostring(Player.UserId)
	        local Pick: any = Context.Draft.teamData.kitSelection[UserId]
	        if not Pick then
	            for _, Team: any in Context.Draft.enemyTeamData do
	                Pick = Team.kitSelection and Team.kitSelection[UserId]
	                if Pick then
	                    break
	                end
	            end
	        end
	
	        if Pick and Pick.kit and Pick.selectorOption ~= HoverOption and not Ignored[Pick.kit] then
	            return Pick.kit, 1
	        end
	
	        if Context.Ranked and Entry.Data then
	            return PredictKit(Entry, Context.Draft.sharedData.kitBans)
	        end
	
	        return nil, 0
	    end
	
	    local function Score(Player: Player, Entry: any, Context: any): number
	        local Data = Entry.Data
	        if not Data then
	            return 0
	        end
	
	        if not TopDivision then
	            TopDivision = 1
	
	            for Division: any in bedwars.RankMeta do
	                if type(Division) == "number" and Division > TopDivision then
	                    TopDivision = Division
	                end
	            end
	        end
	
	        local Baseline: number = Context.Baseline
	        local Stats = Data.queues[Context.Queue] or {}
	        local Wins, Losses = Stats.wins or 0, Stats.losses or 0
	        local Rate: number = (Wins + Baseline * PriorMatches) / (Wins + Losses + PriorMatches)
	        local RecentWins, RecentLosses = GetRecent(Entry.Rows, Context.Queue)
	        local RecentRate: number = (RecentWins + Baseline * PriorMatches) / (RecentWins + RecentLosses + PriorMatches)
	        local Matches: number = (Stats.matches or 0) + PriorMatches
	        local Kit, Confidence = GetKit(Player, Entry, Context)
	        local Device: string? = Player:GetAttribute("UserInputType") or Data.platform
	
	        local Parts = {
	            Win = math.log(Rate * (1 - Baseline) / ((1 - Rate) * Baseline)),
	            Combat = math.log(((Stats.kills or 0) + PriorMatches) / ((Stats.deaths or 0) + PriorMatches)),
	            Rank = (Entry.Rank or 0) / TopDivision,
	            Kit = (KitValue[Kit] or 0) * Confidence,
	            KitPlays = math.log(1 + (Data.favoriteKitData and Data.favoriteKitData[Kit] or 0)) * Confidence,
	            Experience = math.log(1 + (Data.globalStats and Data.globalStats.matches or 0)),
	            Streak = math.log(1 + (Stats.currentWinStreak or 0)),
	            FinalKills = math.log(1 + (Stats.finalKills or 0) / Matches),
	            BedBreaks = math.log(1 + (Stats.bedBreaks or 0) / Matches),
	            Level = math.log(1 + (Data.level or 0)),
	            Device = DeviceThreat[Device] or 0,
	            Recent = math.log(RecentRate * (1 - Baseline) / ((1 - RecentRate) * Baseline))
	        }
	
	        local Total: number = 0
	        for Name: string, Value: number in Parts do
	            Total += Value * Weights[Name]
	        end
	
	        return Total
	    end
	
	    local function Average(List: {Player}, Entries: {[Player]: any}, Context: any): number
	        local Sum: number = 0
	        for _, v: Player in List do
	            Sum += Score(v, Entries[v], Context)
	        end
	
	        return Sum / #List
	    end
	
	    HasAdvantage = function(Target: Player?): (boolean?, string)
	        local Allies, Opponents, Pending
	        if Target then
	            if Target == LocalPlayer then
	                return nil, "Pick another player"
	            end
	
	            if not Target:IsDescendantOf(Players) then
	                return nil, "Player left"
	            end
	        else
	            Allies, Opponents, Pending = GetRoster()
	            if not Allies or #Opponents == 0 or Pending then
	                return nil, "Waiting for teams"
	            end
	        end
	
	        local Data = TeleportService:GetLocalPlayerTeleportData()
	        local Match = type(Data) == "table" and (Data.match or Data.customMatch)
	        local Queue: string = Match and Match.queueType or store.queueType
	        local Meta = bedwars.QueueMeta[Queue]
	        local Baseline: number = 1 / math.max(Meta and Meta.teams and #Meta.teams or 2, 2)
	
	        local Context = {Queue = Queue, Baseline = Baseline, Ranked = Meta ~= nil and Meta.rankCategory ~= nil, Draft = bedwars.Store:getState().Draft}
	        local Entries, Loaded, Unknown = {}, 0, 0
	        local Groups: {{Player}} = Target and {{LocalPlayer, Target}} or {Allies, Opponents}
	        for _, List: {Player} in Groups do
	            for _, v: Player in List do
	                local Entry = Fetch(v)
	                Entries[v] = Entry
	                if Entry.Done then
	                    Loaded += 1
	                    Unknown += Entry.Data and 0 or 1
	                end
	            end
	        end
	
	        local Total: number = Target and 2 or #Allies + #Opponents
	        if Loaded < Total then
	            return nil, `Waiting for stats ({Loaded}/{Total})`
	        end
	
	        local You: number = Score(LocalPlayer, Entries[LocalPlayer], Context)
	        if Target then
	            local Them: number = Score(Target, Entries[Target], Context)
	            return You > Them, string.format("You %.2f, %s %.2f%s", You, Target.Name, Them, Unknown > 0 and `, {Unknown} without stats` or "")
	        end
	
	        local Own, Enemy = Average(Allies, Entries, Context), Average(Opponents, Entries, Context)
	        return Own > Enemy, string.format("You %.2f, team %.2f, enemies %.2f%s", You, Own, Enemy, Unknown > 0 and `, {Unknown} without stats` or "")
	    end
	end
	
	local function Check(UseSkill: boolean, UseRank: boolean, UseAmount: boolean, Names: {string}): string?
	    if UseRank then
	        local Data = TeleportService:GetLocalPlayerTeleportData()
	        local Match = type(Data) == "table" and (Data.match or Data.customMatch)
	        local Meta = bedwars.QueueMeta[Match and Match.queueType or store.queueType]
	        if not (Meta and Meta.rankCategory) then
	            return
	        end
	    end
	
	    if UseSkill then
	        local Advantages = 0
	        for _, Ent: any in Entity.List do
	            if Ent.Player and Ent.Player:GetAttribute("Team") ~= LocalPlayer:GetAttribute("Team") and HasAdvantage(Ent.Player) == false then
	                Advantages += 1
	            end
	
	            if Advantages > 1 then
	                break
	            end
	        end
	
	        if Advantages > 1 then
	            return "Dodging because multiple opponents are \"better\" than you"
	        end
	    end
	
	    if UseAmount then
	        local Whitelisted = {}
	        for _, v: string in Names do
	            Whitelisted[v:lower()] = true
	        end
	
	        local MyTeam = LocalPlayer:GetAttribute("Team")
	        local Teammates, Enemies, Pending = 1, {}, false
	        for _, v: Player in Players:GetPlayers() do
	            if v == LocalPlayer or v:GetAttribute("Spectator") then
	                continue
	            end
	
	            local Team = v:GetAttribute("Team")
	            if Whitelisted[v.Name:lower()] then
	                Teammates += 1
	            elseif not Team then
	                Pending = true
	            elseif MyTeam and Team == MyTeam then
	                Teammates += 1
	            elseif MyTeam then
	                Enemies[Team] = (Enemies[Team] or 0) + 1
	            end
	        end
	
	        local State = bedwars.Store:getState()
	        local Meta = bedwars.QueueMeta[store.queueType]
	        local Present, Expected = Teammates, 0
	        for _, Count: number in Enemies do
	            Present += Count
	        end
	
	        for _, Team: any in State.Game.teams or {} do
	            for _ in Team.members or {} do
	                Expected += 1
	            end
	        end
	
	        local Drafting = Meta and Meta.drafting and Meta.drafting.enabled
	        local Ready = Present >= Expected and (not Drafting or State.Draft.sharedData.matchDraftPhase >= 3)
	        if MyTeam and not Pending and Ready then
	            local Largest = 0
	            for _, Count: number in Enemies do
	                Largest = math.max(Largest, Count)
	            end
	
	            if Teammates < Largest then
	                return `Dodging because you have fewer players ({Teammates}) than the enemy team ({Largest})`
	            end
	        end
	    end
	
	    return nil
	end
	
	Library.HasAdvantage = HasAdvantage
	Library.Check = Check
	
	local function Fire()
	    store.readyHold.Release()
	end
	
	MatchDodge = vape.Categories.Utility:CreateModule({
	    Name = "AutoMatchDodge",
	    Function = function(Callback: boolean)
	        writefile(`{vape.Directory}/profiles/matchdodge.txt`, tostring(Callback))
	
	        if Callback then
	            local Hold = store.readyHold
	            if not Hold.Held then
	                return
	            end
	
	            Hold.Claimed = true
	            local ShouldFire = Hold.Started + Timeout.Value
	
	            repeat
	                if Mode.Value == "Auto" then
	                    local Reason: string? = Check(Skill.Enabled, RankCheck.Enabled, Amount.Enabled, AmountWhitelist.ListEnabled)
	                    if Reason then
	                        SendNotification("AutoMatchDodge", Reason, 12, "info")
	                        break
	                    end
	
	                    if os.clock() > ShouldFire and not Hold.Block then
	                        task.spawn(Fire)
	                        break
	                    end
	                end
	                task.wait(0.1)
	            until not MatchDodge.Enabled or not Hold.Held
	        else
	            Fire()
	        end
	    end,
	    Tooltip = "Puts you in a loading state for as long as you want",
	    ExtraText = function()
	        return getgenv().Dodged and "Dodging" or "Game loaded"
	    end
	})
	
	Mode = MatchDodge:CreateDropdown({
	    Name = "Mode",
