Run(function()
	local AutoEquipKit
	local Kit
	
	local Kits, List = {}, {}
	
	for KitType: string, v: any in bedwars.BedwarsKitMeta do
	    if v.name ~= "None" then
	        table.insert(List, v.name)
	    end
	    Kits[v.name] = KitType
	end
	table.sort(List)
	table.insert(List, 1, "None")
	
	AutoEquipKit = vape.Categories.Kits:CreateModule({
	    Name = "AutoEquipKit",
	    Function = function(Callback: boolean)
	        if Callback then
	            local Last: number?
	
	            repeat
	                if store.matchState == 2 and Last == 1 and Kit.Value ~= "None" then
	                    bedwars.Handler:Get("BedwarsActivateKit"):Fire("CallServer", {kit = Kits[Kit.Value]})
	                    SendNotification("AutoEquipKit", `Equipped {Kit.Value} for the next round.`, 10, "info")
	                end
	
	                Last = store.matchState
	                task.wait(0.5)
	            until not AutoEquipKit.Enabled
	        end
	    end,
	    Tooltip = "Equips a kit automatically when a round ends"
	})
	
	Kit = AutoEquipKit:CreateDropdown({
	    Name = "Equip kit",
	    List = List,
	    Default = "None"
	})
end)

