Run(function()
	local AutoJade
	local Height
	local FallSpeed
	local Switch
	local SwitchDelay = {}
	local LimitItem
	local KitCheck
	local NextSlam: number = 0
	
	local function Slam(Hammer)
	    if store.hand.tool ~= Hammer.tool then
	        if Switch.Enabled then
	            hotbarSwitch(getHotbar(Hammer.tool))
	        else
	            switchItem(Hammer.tool, 0)
	        end
	        task.wait(SwitchDelay.Value)
	    end
	
	    if AutoJade.Enabled and Entity.isAlive and bedwars.AbilityController:canUseAbility("jade_hammer_jump", {disableBlockedAbilityAlert = true}) then
	        bedwars.JadeHammerController:useJadeHammer()
	    end
	end
	
	AutoJade = vape.Categories.Kits:CreateModule({
	    Name = "AutoJade",
	    Function = function(Callback: boolean)
	        if Callback then
	            NextSlam = 0
	
	            AutoJade:Clean(RunService.Heartbeat:Connect(function()
	                if not Entity.isAlive or (KitCheck.Enabled and not store.hasKit("jade")) or tick() < NextSlam or not bedwars.JadeHammerController then
	                    return
	                end
	
	                local Root: BasePart = Entity.character.RootPart
	                if Root.AssemblyLinearVelocity.Y > -FallSpeed.Value then
	                    return
	                end
	                if not bedwars.AbilityController:canUseAbility("jade_hammer_jump", {disableBlockedAbilityAlert = true}) then
	                    return
	                end
	                if not Entity.Raycast(Root.Position, Vector3.new(0, -Height.Value, 0), store.airRay) then
	                    return
	                end
	
	                local Hammer
	                if store.hand.tool and bedwars.JadeBalance.isJadeHammer(store.hand.tool.Name) then
	                    Hammer = store.hand
	                elseif not LimitItem.Enabled then
	                    for _, v: any in store.inventory.inventory.items do
	                        if bedwars.JadeBalance.isJadeHammer(v.itemType) then
	                            Hammer = v
	                            break
	                        end
	                    end
	                end
	                if not Hammer then
	                    return
	                end
	
	                NextSlam = tick() + bedwars.JadeBalance.HAMMER_COOLDOWN
	                task.spawn(Slam, Hammer)
	            end))
	        end
	    end,
	    Tooltip = "Slams the Jade hammer down right before you land"
	})
	
	Height = AutoJade:CreateSlider({
	    Name = "Height",
	    Min = 3,
	    Max = 60,
	    Default = 15,
	    Suffix = function(Val: number)
	        return Val <= 1 and "stud" or "studs"
	    end,
	    Tooltip = "Slams once the ground is this close beneath you"
	})
	FallSpeed = AutoJade:CreateSlider({
	    Name = "Fall speed",
	    Min = 0,
	    Max = 100,
	    Default = 10,
	    Tooltip = "Only slams once you are dropping this fast"
	})
	Switch = AutoJade:CreateToggle({
	    Name = "Legit switch",
	    Function = function(Callback: boolean)
	        if SwitchDelay.Object then
	            SwitchDelay.Object.Visible = Callback
	        end
	    end,
	    Tooltip = "Takes the hammer out through the hotbar instead of silently"
	})
	SwitchDelay = AutoJade:CreateSlider({
	    Name = "Switch delay",
	    Min = 0,
	    Max = 1,
	    Decimal = 100,
	    Default = 0.05,
	    Darker = true,
	    Visible = false,
	    Suffix = "seconds"
	})
	LimitItem = AutoJade:CreateToggle({
	    Name = "Limit to items",
	    Tooltip = "Only slams while the hammer is already held"
	})
	KitCheck = AutoJade:CreateToggle({
	    Name = "Kit check",
	    Tooltip = "Only slams while you are using the Jade kit",
	    Default = true
	})
end)

Run(function()
