	local GUI
	local KitCheck
	
	local Casting: number = 0
	
	local function GetClaw()
	    if Limit.Enabled then
	        return store.hand.tool and bedwars.IsItemClaw(store.hand.tool.Name) and store.hand or nil
	    end
	
	    for _, v: any in store.inventory.inventory.items do
	        if bedwars.IsItemClaw(v.itemType) then
	            return v
	        end
	    end
	    return nil
	end
	
	local function CastSpell()
	    local LocalPosition: Vector3 = Entity.character.RootPart.Position
	    local Range: number = math.min(SpellRange.Value, bedwars.SummonerKitBalance.SPELL_CAST_RANGE)
	    local Target: Vector3?
	    if SpellMode.Value == "Camera" then
	        local Point: Vector3? = bedwars.AbilityIndicatorUtil:calculateBlockTargetPoint(Camera.CFrame.Position, Camera.CFrame.LookVector, 300, nil, {allowArenaBarrierTarget = false})
	        Target = Point and (Point - LocalPosition).Magnitude <= Range and Point or nil
	    else
	        local Ent = Entity.EntityPosition({
	            Range = Range,
	            Wallcheck = Targets.Walls.Enabled or nil,
	            Part = "RootPart",
	            Players = Targets.Players.Enabled,
	            NPCs = Targets.NPCs.Enabled,
	            Priority = Targets.Priority.Value,
	            Sort = SortMethods[Sort.Value]
	        })
	        if Ent then
	            local Point: Vector3? = bedwars.AbilityIndicatorUtil:calculateBlockTargetPoint(Ent.RootPart.Position + Vector3.new(0, 3, 0), Vector3.new(0, -1, 0), 30, nil, {allowArenaBarrierTarget = false})
	            Target = Point and (Point - LocalPosition).Magnitude <= Range and Point or Ent.RootPart.Position
	        end
	    end
	    if not Target or not bedwars.AbilityController:canUseAbility("summoner_start_charging", {disableBlockedAbilityAlert = true}) then
	        return
	    end
	
	    Casting = tick() + 6
	    bedwars.AbilityController:useAbility("summoner_start_charging", nil, {targetPosition = Target})
	
	    local Level: number = bedwars.SummonerUtil.summoner_getPlayerSpellLevel(LocalPlayer) or 1
	    local Charge: number = math.max(bedwars.SummonerUtil.summoner_getTotalCastTimeRequired(Level) * (SpellCharge.Value / 100), bedwars.SummonerKitBalance.SPELL_MINIMUM_CAST_TIME)
	    local Deadline: number = tick() + Charge
	    repeat
	        task.wait()
	    until tick() >= Deadline or not AutoKaida.Enabled or not Entity.isAlive or not bedwars.SummonerKitController:isPlayerCastingSpell(LocalPlayer)
	
	    if AutoKaida.Enabled and Entity.isAlive and bedwars.SummonerKitController:isPlayerCastingSpell(LocalPlayer) then
	        bedwars.AbilityController:useAbility("summoner_finish_charging")
	    end
	    Casting = 0
	end
	
	AutoKaida = vape.Categories.Kits:CreateModule({
	    Name = "AutoKaida",
	    Function = function(Callback: boolean)
	        if Callback then
	            repeat
	                if Entity.isAlive and (not KitCheck.Enabled or store.hasKit("summoner")) then
	                    if Spell.Enabled and tick() > Casting and not bedwars.SummonerKitController:isPlayerCastingSpell(LocalPlayer) then
	                        task.spawn(CastSpell)
	                    end
	
	                    local Claw = (not Mouse.Enabled or UserInputService:IsMouseButtonPressed(0)) and (not GUI.Enabled or not bedwars.AppController:isLayerOpen(bedwars.UILayers.MAIN)) and GetClaw()
	                    local Ent = Claw and (workspace:GetServerTimeNow() - bedwars.SummonerClawHandController.lastAttackTime) > bedwars.SummonerKitBalance.CLAW_COOLDOWN and (Swing.Enabled or not bedwars.SummonerKitController:isPlayerCastingSpell(LocalPlayer)) and Entity.EntityPosition({
	                        Range = SwingRange.Value,
	                        Wallcheck = Targets.Walls.Enabled or nil,
	                        Part = "RootPart",
	                        Players = Targets.Players.Enabled,
	                        NPCs = Targets.NPCs.Enabled,
	                        Priority = Targets.Priority.Value,
	                        Sort = SortMethods[Sort.Value]
	                    })
	
	                    if Ent then
	                        local SelfPosition: Vector3 = Entity.character.RootPart.Position
	                        local Delta: Vector3 = Ent.RootPart.Position - SelfPosition
	                        local Direction: Vector3 = CFrame.lookAt(SelfPosition, Ent.RootPart.Position).LookVector
	                        TargetInfo.Targets[Ent] = tick() + 1
	                        SwitchItem(Claw.tool, 0)
	                        if Delta.Magnitude <= AttackRange.Value then
	                            bedwars.Handler:Get("SummonerClawAttackRequest"):Fire(nil, {
	                                position = SelfPosition + Direction * math.max(Delta.Magnitude - 16.399, 0),
	                                direction = Direction,
	                                clientTime = workspace:GetServerTimeNow()
	                            })
	                        end
	                        bedwars.SummonerClawHandController.lastAttackTime = workspace:GetServerTimeNow()
	                        bedwars.SummonerClawController:clawAttack(LocalPlayer, SelfPosition, Direction, Claw.tool.Name)
	                    end
	                end
	
	                task.wait(0.1)
	            until not AutoKaida.Enabled
	        else
	            Casting = 0
	        end
	    end,
	    Tooltip = "Automatically attacks with the Kaida claw and casts her summon circle"
	})
	
	Targets = AutoKaida:CreateTargets({Players = true})
	local Methods: {string} = {"Distance", "Damage"}
	for _, v: string in SortList do
	    if not table.find(Methods, v) then
	        table.insert(Methods, v)
	    end
	end
	Sort = AutoKaida:CreateDropdown({
	    Name = "Target mode",
	    List = Methods
	})
	SwingRange = AutoKaida:CreateSlider({
	    Name = "Swing Range",
	    Min = 1,
	    Max = 32,
	    Default = 32,
	    Suffix = function(Val: number)
	        return Val <= 1 and "stud" or "studs"
	    end
	})
	AttackRange = AutoKaida:CreateSlider({
	    Name = "Attack Range",
	    Min = 1,
	    Max = 32,
	    Default = 32,
	    Suffix = function(Val: number)
	        return Val <= 1 and "stud" or "studs"
	    end
	})
	Spell = AutoKaida:CreateToggle({
	    Name = "Auto summon",
	    Function = function(Callback: boolean)
	        if SpellMode then
	            SpellMode.Object.Visible = Callback
	            SpellCharge.Object.Visible = Callback
	            SpellRange.Object.Visible = Callback
	        end
	    end,
	    Tooltip = "Charges and drops the summon circle on its own"
	})
	SpellMode = AutoKaida:CreateDropdown({
	    Name = "Summon at",
	    List = {"Target", "Camera"},
	    Darker = true,
	    Visible = false,
	    Tooltip = "Target drops the circle on the closest enemy, Camera drops it where you are looking"
	})
	SpellCharge = AutoKaida:CreateSlider({
	    Name = "Charge",
	    Min = 1,
	    Max = 100,
	    Default = 100,
	    Darker = true,
	    Visible = false,
	    Suffix = "%",
	    Tooltip = "How far to charge before releasing, 100% is the full radius for your spell level"
	})
	SpellRange = AutoKaida:CreateSlider({
	    Name = "Summon Range",
	    Min = 1,
	    Max = 120,
	    Default = math.floor(bedwars.SummonerKitBalance.SPELL_CAST_RANGE),
	    Darker = true,
	    Visible = false,
	    Suffix = function(Val: number)
	        return Val <= 1 and "stud" or "studs"
	    end,
	    Tooltip = "Capped at the range the game allows, which KitExtender can raise"
	})
	Swing = AutoKaida:CreateToggle({
	    Name = "Swing during ability",
	    Default = true,
	    Tooltip = "Continue claw attacks while the ability is charging"
	})
	Limit = AutoKaida:CreateToggle({
	    Name = "Limit to items",
	    Tooltip = "Only attacks while the claw is held"
	})
	Mouse = AutoKaida:CreateToggle({Name = "Require mouse down"})
	GUI = AutoKaida:CreateToggle({Name = "GUI check"})
	KitCheck = AutoKaida:CreateToggle({
	    Name = "Kit check",
	    Tooltip = "Only runs while you are using the Kaida kit",
	    Default = true
	})
end)

Run(function()
	local AutoKaliyah
	local Range
	local Stacks
	local Delay
	local NoSlow
	local KitCheck
	
	local Legit: number = GetFunctionRange(bedwars.DragonSlayerController.hasEligiblePunchTarget) or 14.4
	local Modifier, Old
	local NoSlowUntil: number = 0
	
	local function Punch()
	    if NoSlow.Enabled then
	        if not Old then
	            Modifier = bedwars.SprintController:getMovementStatusModifier()
	            Old = Modifier.addModifier
	            Modifier.addModifier = function(self, Data)
	                if NoSlow.Enabled and tick() < NoSlowUntil and Data and Data.moveSpeedMultiplier == 0 then
	                    Data.moveSpeedMultiplier = 1
	                end
	                return Old(self, Data)
	            end
	
	            AutoKaliyah:Clean(function()
	                Modifier.addModifier = Old
	                Modifier, Old = nil, nil
	                NoSlowUntil = 0
	            end)
	        end
	        NoSlowUntil = math.max(NoSlowUntil, tick() + Delay.Value + 0.1)
	    end
	
	    task.wait(Delay.Value)
	    bedwars.AbilityController:useAbility("dragon_slayer_punch")
	end
	
	AutoKaliyah = vape.Categories.Kits:CreateModule({
	    Name = "AutoKaliyah",
	    Function = function(Callback: boolean)
	        if Callback then
	            repeat
	                if Entity.isAlive and (not KitCheck.Enabled or store.hasKit("dragon_slayer")) and bedwars.AbilityController:canUseAbility("dragon_slayer_punch", {disableBlockedAbilityAlert = true}) then
	                    local LocalPosition: Vector3 = Entity.character.RootPart.Position
	                    for Target: Model, Emblem: any in bedwars.DragonSlayerController.dragonEmblems do
	                        if Emblem.stackCount >= Stacks.Value and Target.PrimaryPart and (Target.PrimaryPart.Position - LocalPosition).Magnitude <= Range.Value then
	                            Punch()
	                            break
	                        end
	                    end
	                end
	                task.wait(0.1)
	            until not AutoKaliyah.Enabled
	        end
	    end,
	    Tooltip = 'Automatically uses the "punch" ability from kaliyah'
	})
	
	NoSlow = AutoKaliyah:CreateToggle({
	    Name = "No Slow",
	    Default = true,
	    Tooltip = 'Prevents you from being slowed down after using the "Punch" ability'
	})
	Range = AutoKaliyah:CreateSlider({
	    Name = "Range",
	    Min = 1,
	    Max = 20,
	    Default = 18,
	    Suffix = function(Val: number)
	        return Val <= 1 and "stud" or "studs"
	    end
	})
	AutoKaliyah:CreateButton({
	    Name = "Sync to legit range",
	    Function = function()
	        Range:SetValue(Legit)
	    end
	})
	Stacks = AutoKaliyah:CreateSlider({
	    Name = "Stacks",
	    Min = 1,
	    Max = 3,
	    Default = 1,
	    Suffix = function(Val: number)
	        return Val <= 1 and "stack" or "stacks"
	    end,
	    Tooltip = "How many emblems a target needs before the punch fires, 3 stacks deals 25 damage against a wall instead of 10"
	})
	Delay = AutoKaliyah:CreateSlider({
	    Name = "Delay",
	    Min = 0,
	    Max = 1,
	    Default = 0.1,
	    Decimal = 100
	})
	KitCheck = AutoKaliyah:CreateToggle({
	    Name = "Kit check",
	    Tooltip = "Only punches while you are using the Kaliyah kit",
	    Default = true
	})
end)

Run(function()
	local AutoKit
	local Legit
	local Toggles = {}
	local Running = {}
	
	local function NewSession()
	    local Session = {Tasks = {}}
	
	    function Session:Clean(Task: any)
	        table.insert(self.Tasks, type(Task) == "function" and {Disconnect = Task} or Task)
	    end
	
	    function Session:Stop()
	        if self.Thread and coroutine.status(self.Thread) ~= "dead" then
	            task.cancel(self.Thread)
	        end
	        for _, v: any in self.Tasks do
	            v:Disconnect()
	        end
	        table.clear(self.Tasks)
	    end
	
	    return Session
	end
	
	local function KitCollection(Id, Callback: (Instance) -> (), Range: number, Specific: boolean, Session)
	    local Objects = type(Id) == "table" and Id or Collection(Id, Session)
	    repeat
	        if Entity.isAlive then
	            local LocalPosition: Vector3 = Entity.character.RootPart.Position
	            for _, v: Instance in Objects do
	                if (vape.Modules.InfiniteFly or {}).Enabled or not AutoKit.Enabled then
	                    break
	                end
	                local Part = not v:IsA("Model") and v or (v.PrimaryPart or v:FindFirstChildWhichIsA("BasePart", true))
	                if Part and (Part.Position - LocalPosition).Magnitude <= (not Legit.Enabled and Specific and math.huge or Range) then
	                    Callback(v)
	                end
	            end
	        end
	        task.wait(0.1)
	    until not AutoKit.Enabled
	end
	
	local AutoKitFunctions = {
	    battery = function()
	        repeat
	            if Entity.isAlive then
	                local LocalPosition: Vector3 = Entity.character.RootPart.Position
	                for BatteryId: any, v: any in bedwars.BatteryEffectsController.liveBatteries do
	                    if (v.position - LocalPosition).Magnitude <= 10 then
	                        local BatteryInfo = bedwars.BatteryEffectsController:getBatteryInfo(BatteryId)
	                        if not BatteryInfo or BatteryInfo.activateTime >= workspace:GetServerTimeNow() or BatteryInfo.consumeTime + 0.1 >= workspace:GetServerTimeNow() then
	                            continue
	                        end
	                        BatteryInfo.consumeTime = workspace:GetServerTimeNow()
	                        bedwars.Handler:Get("ConsumeBattery"):Fire("SendToServer", {batteryId = BatteryId})
	                    end
	                end
	            end
	            task.wait(0.1)
	        until not AutoKit.Enabled
	    end,
	    beekeeper = function(Session)
	        KitCollection("bee", function(Bee: Instance)
	            bedwars.Handler:Get("PickUpBee"):Fire("SendToServer", {beeId = Bee:GetAttribute("BeeId")})
	        end, 18, false, Session)
	    end,
	    bigman = function(Session)
	        KitCollection("treeOrb", function(Orb: Instance)
	            if bedwars.Handler:Get("ConsumeTreeOrb"):Fire("CallServer", {treeOrbSecret = Orb:GetAttribute("TreeOrbSecret")}) then
	                Orb:Destroy()
	            end
	        end, 12, false, Session)
	    end,
	    block_kicker = function(Session)
	        local Old = bedwars.BlockKickerKitController.getKickBlockProjectileOriginPosition
	        bedwars.BlockKickerKitController.getKickBlockProjectileOriginPosition = function(...)
	            local Origin, Direction = select(2, ...)
	            local Ent = Entity.EntityMouse({
	                Part = "RootPart",
	                Range = 1000,
	                Origin = Origin,
	                Players = true,
	                Wallcheck = true
	            })
	
	            if Ent then
	                local AimPosition: Vector3? = Prediction.SolveTrajectory(Origin, 100, 20, Ent.RootPart.Position, Ent.RootPart.AssemblyLinearVelocity, workspace.Gravity, Ent.HipHeight, Ent.Jumping and 42.6 or nil)
	                if AimPosition then
	                    for i: number, v: any in debug.getstack(2) do
	                        if v == Direction then
	                            debug.setstack(2, i, CFrame.lookAt(Origin, AimPosition).LookVector)
	                        end
	                    end
	                end
	            end
	
	            return Old(...)
	        end
	
	        Session:Clean(function()
	            bedwars.BlockKickerKitController.getKickBlockProjectileOriginPosition = Old
	        end)
	    end,
	    cat = function(Session)
	        local Old = bedwars.CatController.leap
	        bedwars.CatController.leap = function(...)
	            VapeEvents.CatPounce:Fire()
	            return Old(...)
	        end
	
	        Session:Clean(function()
	            bedwars.CatController.leap = Old
	        end)
	    end,
	    davey = function(Session)
	        local Old = bedwars.CannonHandController.launchSelf
	        bedwars.CannonHandController.launchSelf = function(...)
	            local Results = {Old(...)}
	            local self, Block = ...
	            if Block:GetAttribute("PlacedByUserId") == LocalPlayer.UserId and (Block.Position - Entity.character.RootPart.Position).Magnitude < 30 then
	                task.spawn(bedwars.breakBlock, Block, false)
	            end
	
