Run(function()
	local AutoSigrid
	local Combat
	local Charge
	local Targets
	local Range
	local ChargeRange
	local KitCheck
	local NextSummon, NextCharge = 0, 0
	
	local function UpdateVisibility()
	    if ChargeRange then
	        Range.Object.Visible = Combat.Enabled
	        ChargeRange.Object.Visible = Charge.Enabled
	        Targets.Object.Visible = Combat.Enabled or Charge.Enabled
	    end
	end
	
	AutoSigrid = vape.Categories.Kits:CreateModule({
	    Name = "AutoSigrid",
	    Function = function(Callback: boolean)
	        if Callback then
	            NextSummon, NextCharge = 0, 0
	
	            repeat
	                if Entity.isAlive and (not KitCheck.Enabled or store.hasKit("elk_master")) and tick() >= NextSummon and bedwars.AbilityController:canUseAbility("elk_summon", {disableBlockedAbilityAlert = true}) then
	                    local Wanted: boolean = not Combat.Enabled
	
	                    if not Wanted then
	                        Wanted = #Entity.AllPosition({
	                            Range = Range.Value,
	                            Part = "RootPart",
	                            Players = Targets.Players.Enabled,
	                            NPCs = Targets.NPCs.Enabled
	                        }) > 0
	                    end
	
	                    if Wanted then
	                        NextSummon = tick() + 1
	                        bedwars.AbilityController:useAbility("elk_summon")
	                    end
	                end
	
	                if Charge.Enabled and Entity.isAlive and (not KitCheck.Enabled or store.hasKit("elk_master")) and LocalPlayer.Character:FindFirstChild("elk") and tick() >= NextCharge and bedwars.AbilityController:canUseAbility("elk_antler_uppercut", {disableBlockedAbilityAlert = true}) then
	                    local Ent = Entity.EntityPosition({
	                        Range = ChargeRange.Value,
	                        Wallcheck = Targets.Walls.Enabled or nil,
	                        Part = "RootPart",
	                        Players = Targets.Players.Enabled,
	                        NPCs = Targets.NPCs.Enabled
	                    })
	
	                    if Ent then
	                        local Root: BasePart = Entity.character.RootPart
	                        local Flat: Vector3 = (Ent.RootPart.Position - Root.Position) * Vector3.new(1, 0, 1)
	                        if Flat.Magnitude > 0.001 then
	                            Root.CFrame = CFrame.lookAlong(Root.Position, Flat)
	                        end
	                        NextCharge = tick() + 1
	                        bedwars.AbilityController:useAbility("elk_antler_uppercut")
	                    end
	                end
	                task.wait(0.1)
	            until not AutoSigrid.Enabled
	        end
	    end,
	    Tooltip = "Keeps the elk summoned so you are never caught on foot"
	})
	
	Combat = AutoSigrid:CreateToggle({
	    Name = "Only in combat",
	    Function = UpdateVisibility,
	    Tooltip = "Waits until somebody is nearby instead of resummoning on cooldown"
	})
	Charge = AutoSigrid:CreateToggle({
	    Name = "Charge attack",
	    Function = UpdateVisibility,
	    Tooltip = "Charges at whoever is in range while you are riding the elk"
	})
	Targets = AutoSigrid:CreateTargets({
	    Players = true,
	    NPCs = true,
	    Visible = false
	})
	Range = AutoSigrid:CreateSlider({
	    Name = "Range",
	    Min = 1,
	    Max = 80,
	    Default = 40,
	    Visible = false,
	    Suffix = function(Val: number)
	        return Val <= 1 and "stud" or "studs"
	    end
	})
	ChargeRange = AutoSigrid:CreateSlider({
	    Name = "Charge range",
	    Min = 1,
	    Max = 40,
	    Default = 20,
	    Visible = false,
	    Suffix = function(Val: number)
	        return Val <= 1 and "stud" or "studs"
	    end
	})
	KitCheck = AutoSigrid:CreateToggle({
	    Name = "Kit check",
	    Tooltip = "Only runs while you are using the Sigrid kit",
	    Default = true
	})
end)

Run(function()
	local AutoSilas
	local SwapAura
	local PressAttack
	local Range
	local KitCheck
	local Aura: string = ""
	
	local function GetHurtAlly(Origin: Vector3)
	    for _, v: any in Entity.List do
	        if v.Player and v.Player:GetAttribute("Team") == LocalPlayer:GetAttribute("Team") and v.Health < v.MaxHealth and (v.RootPart.Position - Origin).Magnitude <= Range.Value then
	            return v
