	    Tooltip = "Only runs while you are using the Silas kit",
	    Default = true
	})
end)

Run(function()
	local AutoSkoll
	local Targets
	local Sort
	local Range
	local Aim
	local Detonate
	local KitCheck
	local DetonateMode = {}
	local Health = {}
	local Marked: {[Instance]: number} = {}
	
	local Old
	
	local function GetTarget()
	    return Entity.EntityPosition({
	        Range = Range.Value,
	        Part = "RootPart",
	        Players = Targets.Players.Enabled,
	        NPCs = Targets.NPCs.Enabled,
	        Priority = Targets.Priority.Value,
	        Wallcheck = Targets.Walls.Enabled or nil,
	        Sort = sortmethods[Sort.Value]
	    })
	end
	
	local function ShouldDetonate()
	    if not Detonate.Enabled then
	        return false
	    end
	
	    local TargetHealth, Expiry
	    for Target: Instance, v: number in Marked do
	        if Target.Parent and tick() < v then
	            local Humanoid: Humanoid? = Target:FindFirstChildWhichIsA("Humanoid")
	            if Humanoid and Humanoid.MaxHealth > 0 then
	                TargetHealth, Expiry = (Humanoid.Health + getShieldAttribute(Target)) / Humanoid.MaxHealth * 100, v
	                break
	            end
	        end
	    end
	    if DetonateMode.Value == "Instantly" then
	        return true
	    elseif not TargetHealth then
	        return false
	    elseif DetonateMode.Value == "Low health" then
	        return TargetHealth <= Health.Value
	    end
	    return tick() >= Expiry - 1
	end
	
	AutoSkoll = vape.Categories.Kits:CreateModule({
	    Name = "AutoSkoll",
	    Function = function(Callback: boolean)
	        if Callback then
	            table.clear(Marked)
	
	            Old = bedwars.VoidHunterKitController.onAbilityUsed
	            bedwars.VoidHunterKitController.onAbilityUsed = function(self, Character, Data, ...)
	                if (not KitCheck.Enabled or store.hasKit("void_hunter")) and Aim.Enabled and Data and Data.ability == "void_hunter_mark" and Character == LocalPlayer.Character and Character.PrimaryPart then
	                    local Target = GetTarget()
	                    if Target then
	                        local Origin: Vector3 = Character.PrimaryPart.Position
	                        local Delta: Vector3 = Target.RootPart.Position - Origin
	                        if Delta.Magnitude > 0 then
	                            bedwars.Handler:Get("VoidHunter_MarkAbilityRequest"):Fire("SendToServer", {
	                                originPosition = Origin,
	                                direction = Delta.Unit
	                            })
	                            return
	                        end
	                    end
	                end
	                return Old(self, Character, Data, ...)
	            end
	
	            AutoSkoll:Clean(bedwars.Handler:Get("VoidHunter_TargetMarked").Remote:Connect(function(Data)
	                if Data.userPlayer == LocalPlayer and Data.targetEntityInstance then
	                    Marked[Data.targetEntityInstance] = tick() + bedwars.VoidHunterBalance.MARK_DURATION
	                end
	            end))
	
	            AutoSkoll:Clean(bedwars.Handler:Get("VoidHunter_TargetMarkRemoved").Remote:Connect(function(Data)
	                if Data.userPlayer == LocalPlayer and Data.targetEntityInstance then
	                    Marked[Data.targetEntityInstance] = nil
	                end
	            end))
	
	            repeat
	                if Entity.isAlive and (not KitCheck.Enabled or store.hasKit("void_hunter")) then
	                    if ShouldDetonate() and bedwars.AbilityController:canUseAbility("void_hunter_detonate", {disableBlockedAbilityAlert = true}) then
	                        bedwars.AbilityController:useAbility("void_hunter_detonate")
	                        table.clear(Marked)
	                    elseif GetTarget() and bedwars.AbilityController:canUseAbility("void_hunter_mark", {disableBlockedAbilityAlert = true}) then
	                        bedwars.AbilityController:useAbility("void_hunter_mark")
	                    end
	                end
	                task.wait(0.1)
	            until not AutoSkoll.Enabled
	        else
	            table.clear(Marked)
	            if Old then
	                bedwars.VoidHunterKitController.onAbilityUsed = Old
	                Old = nil
	            end
	        end
	    end,
	    Tooltip = "Sends Fenrir at whoever is near you and sets the mark off"
	})
	
	Targets = AutoSkoll:CreateTargets({
	    Players = true,
	    NPCs = false
	})
	local Methods: {string} = {"Distance", "Health"}
	for _, v: string in sortlist do
	    if not table.find(Methods, v) then
	        table.insert(Methods, v)
	    end
	end
	Sort = AutoSkoll:CreateDropdown({
	    Name = "Target mode",
	    List = Methods
	})
	Range = AutoSkoll:CreateSlider({
	    Name = "Range",
	    Min = 1,
	    Max = 100,
	    Default = 50,
	    Suffix = function(Val: number)
	        return Val <= 1 and "stud" or "studs"
	    end,
	    Tooltip = "Fenrir travels 39 studs a second and lives 3 seconds"
	})
	Aim = AutoSkoll:CreateToggle({
	    Name = "Aim wolf",
	    Default = true,
	    Tooltip = "Throws Fenrir straight at your target instead of wherever your camera points"
	})
	Detonate = AutoSkoll:CreateToggle({
	    Name = "Auto detonate",
	    Function = function(Callback: boolean)
	        if DetonateMode.Object then
	            DetonateMode.Object.Visible = Callback
	            Health.Object.Visible = Callback and DetonateMode.Value == "Low health"
	        end
	    end,
	    Default = true,
	    Tooltip = "Sets the mark off, which costs you the damage buff on them"
	})
	DetonateMode = AutoSkoll:CreateDropdown({
	    Name = "Detonate at",
	    List = {"Low health", "Instantly", "Before it expires"},
	    Darker = true,
	    Visible = false,
	    Function = function(Val: string)
	        if Health.Object then
	            Health.Object.Visible = Detonate.Enabled and Val == "Low health"
	        end
	    end,
	    Tooltip = "Low health finishes them off, Before it expires keeps the buff until the mark runs out"
	})
	Health = AutoSkoll:CreateSlider({
	    Name = "Health",
	    Min = 1,
	    Max = 100,
	    Default = 30,
	    Darker = true,
	    Visible = false,
	    Suffix = "%",
	    Tooltip = "Blows the mark for 20 damage once they drop under this"
	})
	KitCheck = AutoSkoll:CreateToggle({
	    Name = "Kit check",
	    Tooltip = "Only runs while you are using the Skoll kit",
	    Default = true
	})
end)

