Run(function()
	local AutoSophia
	local Targets
	local Range
	local FireRate
	local SwitchDelay
	local KitCheck
	local NextFire: number = 0
	local NextSwap: number = 0
	
	local Staffs: {string} = {"frost_staff_3", "frost_staff_2", "frost_staff_1"}
	
	local function ShootStaff()
	    local Item, ItemType
	    for _, v: string in Staffs do
	        Item = GetItem(v)
	        if Item then
	            ItemType = v
	            break
	        end
	    end
	    local Source = Item and bedwars.ItemMeta[ItemType].projectileSource or nil
	    local Target = Source and GetFacingEntity({
	        Part = "RootPart",
	        Range = Range.Value,
	        Players = Targets.Players.Enabled,
	        NPCs = Targets.NPCs.Enabled,
	        Priority = Targets.Priority.Value,
	        Wallcheck = Targets.Walls.Enabled,
	        Limit = 10
	    }) or nil
	    if not Target then
	        return
	    end
	
	    local Ready: boolean = bedwars.FrostyGunController.projectileMode == bedwars.FrostyGunMode.PROJECTILE
	    local Swapping: boolean = not Ready and tick() >= NextSwap and bedwars.AbilityController:canUseAbility("frosty_gun_swap", {disableBlockedAbilityAlert = true})
	    if not Ready and not Swapping then
	        return
	    end
	
	    local Hotbar = store.hand.tool and GetHotbar(store.hand.tool) or nil
	    if HotbarSwitch(GetHotbar(Item.tool)) then
	        task.wait(store.ping.total or 0)
	        if Ready then
	            if FireProjectile(Item, ItemType, Source.projectileType(ItemType), Target) then
	                NextFire = tick() + Source.fireDelaySec + FireRate:GetRandomValue()
	                task.wait(SwitchDelay.Value)
	            end
	        else
	            NextSwap = tick() + 1
	            bedwars.AbilityController:useAbility("frosty_gun_swap")
	            task.wait(SwitchDelay.Value)
	        end
	        HotbarSwitch(Hotbar)
	    end
	end
	
	AutoSophia = vape.Categories.Kits:CreateModule({
	    Name = "AutoSophia",
	    Function = function(Callback: boolean)
	        if Callback then
	            NextFire, NextSwap = 0, 0
	
	            repeat
	                if Entity.isAlive and (not KitCheck.Enabled or store.hasKit("winter_lady")) and store.hand.toolType == "sword" and (tick() - bedwars.SwordController.lastSwing) < 0.2 and tick() >= NextFire then
	                    ShootStaff()
	                end
	                task.wait(0.1)
	            until not AutoSophia.Enabled
	        end
	    end,
	    Tooltip = "Automatically shoots Sophia's frost staff at whoever you're meleeing, swapping it out of mist mode when needed"
	})
	
	Targets = AutoSophia:CreateTargets({
	    Players = true,
	    NPCs = false
	})
	Range = AutoSophia:CreateSlider({
	    Name = "Range",
	    Min = 1,
	    Max = 60,
	    Default = 22,
	    Suffix = function(Val: number)
	        return Val <= 1 and "stud" or "studs"
	    end
	})
	FireRate = AutoSophia:CreateTwoSlider({
	    Name = "Fire Rate",
	    Min = 0,
	    Max = 1,
	    DefaultMin = 0.05,
	    DefaultMax = 0.12,
	    Decimal = 100
	})
	SwitchDelay = AutoSophia:CreateSlider({
	    Name = "Switch Delay",
	    Min = 0,
	    Max = 1,
	    Decimal = 100,
	    Suffix = "seconds",
	    Default = 0.02
	})
	KitCheck = AutoSophia:CreateToggle({
	    Name = "Kit check",
	    Tooltip = "Only shoots while you are using the Sophia kit",
	    Default = true
	})
end)

Run(function()
	local AutoStar
	local Streamer
	local Range
	local Animation
	local Delay
	local KitCheck
	
	local Cooldowns: {[Instance]: number} = {}
	
	AutoStar = vape.Categories.Kits:CreateModule({
	    Name = "AutoStarCollector",
	    Function = function(Callback: boolean)
	        if Callback then
	            AutoStar:Clean(ProximityPromptService.PromptShown:Connect(function(Prompt: ProximityPrompt)
	                if Streamer.Enabled and (not KitCheck.Enabled or store.hasKit("star_collector")) and Prompt.Name == "stars_ProximityPrompt" then
	                    task.wait(0.1)
	                    Prompt:InputHoldBegin()
	                end
	            end))
	
	            repeat
	                if not Streamer.Enabled and Entity.isAlive and (not KitCheck.Enabled or store.hasKit("star_collector")) then
	                    local LocalPosition: Vector3 = Entity.character.RootPart.Position
	                    for _, v: Model in CollectionService:GetTagged("stars") do
	                        if tick() > (Cooldowns[v] or 0) and v.PrimaryPart and (LocalPosition - v.PrimaryPart.Position).Magnitude <= Range.Value then
	                            if Delay.Value > 0 then
	                                task.wait(Delay.Value)
	                            end
	
	                            if (LocalPosition - v.PrimaryPart.Position).Magnitude <= Range.Value then
	                                if Animation.Enabled then
	                                    bedwars.GameAnimationUtil:playAnimation(LocalPlayer.Character, bedwars.AnimationType.PUNCH)
	                                    bedwars.ViewmodelController:playAnimation(bedwars.AnimationType.FP_USE_ITEM)
	                                end
	
	                                bedwars.StarCollectorController:collectEntity(LocalPlayer, v, v.Name)
	                                Cooldowns[v] = tick() + 1
	                            end
	                        end
	                    end
	                end
	                task.wait(0.1)
	            until not AutoStar.Enabled
	        else
	            table.clear(Cooldowns)
	        end
	    end,
	    Tooltip = "Automatically collects stars"
	})
	
	Streamer = AutoStar:CreateToggle({
	    Name = "Streamer mode",
	    Function = function(Callback: boolean)
	        if Delay then
	            Delay.Object.Visible = not Callback
	            Range.Object.Visible = not Callback
	            Animation.Object.Visible = not Callback
	        end
	    end,
	    Tooltip = "Useful for when ur screensharing"
	})
	Animation = AutoStar:CreateToggle({
	    Name = "Animation",
	    Default = true,
	    Tooltip = "Plays the collect animation"
	})
	Range = AutoStar:CreateSlider({
	    Name = "Range",
	    Min = 1,
	    Max = 20,
	    Default = 12,
	    Suffix = function(Val: number)
	        return Val > 1 and "studs" or "stud"
	    end
	})
	Delay = AutoStar:CreateSlider({
	    Name = "Delay",
	    Min = 0,
	    Max = 1,
	    Default = 0.2,
	    Decimal = 100,
	    Suffix = function(Val: number)
	        return Val > 1 and "secs" or "sec"
	    end
	})
	KitCheck = AutoStar:CreateToggle({
	    Name = "Kit check",
	    Tooltip = "Only collects while you are using the Star Collector kit",
	    Default = true
	})
end)

Run(function()
	local AutoStyx
	local KitCheck
	
	local Reach: number = 10
	local Attempted = setmetatable({}, {__mode = "k"})
	local Warned: number = 0
	
	AutoStyx = vape.Categories.Kits:CreateModule({
	    Name = "AutoStyx",
	    Function = function(Callback: boolean)
	        if Callback then
	            repeat
	                local Success, Error = pcall(function()
	                    if not Entity.isAlive or (KitCheck.Enabled and not store.hasKit("styx")) then
	                        return
	                    end
	
	                    local LocalPosition: Vector3 = Entity.character.RootPart.Position
	                    for _, v: any in bedwars.StyxKitController.exitPortals do
	                        local Prompt = v.proximityPrompt
	                        if not Prompt or Prompt.ActionText ~= "Connect" then
	                            continue
	                        end
	                        if (v.worldPosition - LocalPosition).Magnitude > Reach then
	                            continue
	                        end
	                        if Attempted[v] and tick() - Attempted[v] < 1 then
	                            continue
	                        end
	
	                        Attempted[v] = tick()
	                        bedwars.StyxKitController:tryOpenExitPortal(v)
	                    end
	                end)
	
	                if not Success and tick() - Warned > 5 then
	                    Warned = tick()
	                    warn(`[catvape] AutoStyx: {Error}`)
	                end
	                task.wait(0.1)
	            until not AutoStyx.Enabled
	            table.clear(Attempted)
	        end
	    end,
	    Tooltip = "Automatically opens Styx's exit portals when you are within 10 studs of them"
	})
	
	KitCheck = AutoStyx:CreateToggle({
	    Name = "Kit check",
	    Tooltip = "Only opens portals while you are using the Styx kit",
	    Default = true
	})
end)

Run(function()
	local AutoTaliyah
	local Emerald
	local Diamond
	local Iron
	local Amount
	local KitCheck
	
	local function GetShopId()
	    if Entity.isAlive then
	        local LocalPosition: Vector3 = Entity.character.RootPart.Position
	        for _, v: any in store.shop do
	            if v.Shop and (v.RootPart.Position - LocalPosition).Magnitude <= 20 then
	                return v.Id
	            end
	        end
	    end
	    return
	end
	
	AutoTaliyah = vape.Categories.Kits:CreateModule({
	    Name = "AutoTaliyah",
	    Function = function(Callback: boolean)
	        if Callback then
	            local Item
	            local NextSell: number = 0
	
	            repeat
	                Item = Item or bedwars.Shop.getShopItem("chicken_shop_item", LocalPlayer)
	                local Id = Item and NextSell < os.clock() and (not KitCheck.Enabled or store.hasKit("taliyah")) and GetShopId()
	                if Id then
	                    local ChickenData = bedwars.TaliyahUtil:getPrice()
	                    if (ChickenData.currency == "emerald" and Emerald.Enabled or ChickenData.currency == "iron" and Iron.Enabled or ChickenData.currency == "diamond" and Diamond.Enabled) and ChickenData.price >= Amount.Value then
	                        NextSell = os.clock() + 0.5
	                        bedwars.Handler:Get("BedwarsPurchaseItem"):Fire("CallServerAsync", {
	                            shopItem = Item,
	                            shopId = Id
	                        }):andThen(function(Success: boolean)
	                            if Success then
	                                bedwars.AudioManager:playAudio(bedwars.SoundList.BEDWARS_PURCHASE_ITEM)
	                                bedwars.Store:dispatch({
	                                    type = "BedwarsAddItemPurchased",
	                                    itemType = Item.itemType
	                                })
	                                if Item.tiered then
	                                    bedwars.BedwarsShopController.alreadyPurchasedMap[Item.itemType] = true
	                                end
	                            end
	                        end)
	                    end
	                end
	                task.wait(0.1)
	            until not AutoTaliyah.Enabled
	        end
	    end,
	    Tooltip = "Automatically buy chickens when it sells for emerald"
	})
	
	Iron = AutoTaliyah:CreateToggle({
	    Name = "Iron",
	    Default = true,
	    Tooltip = "Sells ur chicken when the currency is iron"
	})
	Emerald = AutoTaliyah:CreateToggle({
	    Name = "Emerald",
	    Default = true,
	    Tooltip = "Sells ur chicken when the currency is emerald"
	})
	Diamond = AutoTaliyah:CreateToggle({
	    Name = "Diamond",
	    Default = true,
	    Tooltip = "Sells ur chicken when the currency is diamond"
	})
	Amount = AutoTaliyah:CreateSlider({
	    Name = "Amount",
	    Min = 1,
	    Max = 1000,
	    Default = 2,
	    Tooltip = "Only sells if the currency is selling for the selected amount"
	})
	KitCheck = AutoTaliyah:CreateToggle({
	    Name = "Kit check",
	    Tooltip = "Only buys while you are using the Taliyah kit",
	    Default = true
	})
end)

Run(function()
	local AutoTrap
	local Mode
	local Targets
	local TrapType
	local Traps
	local Target
	local Radius
	local Range
	local Amount
	local PlaceRange
	local Delay
	local IgnoreWalls
	local Switch
	local Notify
	local Detonate
	local KitCheck
	
	local TrapperFolder: Folder = ReplicatedStorage.TS.games.bedwars.kit.kits.trapper
	local Constants = require(TrapperFolder["trapper-constants"])
	local TrapperUtil = require(TrapperFolder["trapper-util"])
	local TrapState = require(TrapperFolder["snap-trap-state"]).SnapTrapState
	local Balance = Constants.TrapperBalance
	local TrapNames: {[string]: string} = {Snap = "snap_trap", Venom = "venom_trap", Explosive = "explosive_trap"}
	local Placed: {[Vector3]: number} = {}
	local NextThrow: number = 0
	local NextSwitch: number = 0
	local NextDetonate: number = 0
	local BedCount: number = 0
	local Session: number = 0
	local RayFilter: {Instance} = {}
	local SightParams: RaycastParams = RaycastParams.new()
	SightParams.FilterType = Enum.RaycastFilterType.Exclude
	
	local function UpdateFilter()
	    local Filter: {Instance} = {Camera, Entity.character.Character}
	    for _, v: any in Entity.List do
	        table.insert(Filter, v.Character)
	    end
	    for _, v: Instance in CollectionService:GetTagged("DontBlockAbilityRaycast") do
	        table.insert(Filter, v)
	    end
	    RayFilter = Filter
	end
	
	local function Raycast(Origin: Vector3, Direction: Vector3): RaycastResult?
	    SightParams.FilterDescendantsInstances = RayFilter
	    return bedwars.QueryUtil:raycast(Origin, Direction, SightParams)
	end
	
	local function HasStock(Item: string): boolean
	    local Meta = Constants.TrapperTrapMeta[Item]
	    return Meta ~= nil and bedwars.TrapperController:canUseAbilities() and TrapperUtil.getTrapCount(LocalPlayer, Item) > 0 and TrapperUtil.getPlacedTrapCount(LocalPlayer, Item) < Meta.maxPlaced
	end
	
	local function GetTrap(EnemyMode: boolean): string?
	    local Wanted: string? = TrapNames[TrapType.Value]
	    if Wanted then
	        return HasStock(Wanted) and Wanted or nil
	    end
	
	    if EnemyMode then
	        local Selected: string = TrapperUtil.getSelectedTrap(LocalPlayer)
	        if HasStock(Selected) then
	            return Selected
	        end
	        for _, v: string in Constants.TrapperTraps do
	            if HasStock(v) then
	                return v
	            end
	        end
	    else
	        for _, v: string in Traps.ListEnabled do
	            if TrapperUtil.isTrapperTrap(v) and HasStock(v) or not TrapperUtil.isTrapperTrap(v) and GetItem(v) then
	                return v
	            end
	        end
	    end
	    return nil
	end
	
	local function GetGround(Position: Vector3): Vector3?
	    local Hit: RaycastResult? = Raycast(Position + Vector3.new(0, 3, 0), Vector3.new(0, -24, 0))
	    if Hit and Hit.Normal.Y > 0.99 then
	        return RoundPosition(Hit.Position + Vector3.new(0, 0.15, 0))
	    end
	    return nil
	end
	
	local function IsValid(Position: Vector3, Item: string): boolean
	    if tick() < (Placed[Position] or 0) or GetPlacedBlock(Position) then
	        return false
	    end
	
	    local Origin: Vector3 = Entity.character.RootPart.Position + Vector3.new(0, 1, 0)
	    if (Position - Origin).Magnitude > math.min(PlaceRange.Value, Balance.ThrowRange) then
	        return false
	    end
	
	    if TrapperUtil.isTrapperTrap(Item) then
	        return TrapperUtil.canThrowTrap(Origin, Position, Raycast, Vector3.yAxis)
	    end
	    return GetPlacedBlock(Position - Vector3.new(0, 3, 0)) ~= nil and CanPlace()
	end
	
	local function PlaceTrap(Position: Vector3, Item: string): boolean
	    if not IsValid(Position, Item) then
	        return false
	    end
	
	    if TrapperUtil.isTrapperTrap(Item) then
	        if not HasStock(Item) or bedwars.TrapperController.currentAim then
	            return false
	        end
	
	        if TrapperUtil.getSelectedTrap(LocalPlayer) ~= Item then
	            if tick() >= NextSwitch and bedwars.AbilityController:canUseAbility("trapper_switch", {disableBlockedAbilityAlert = true}) then
	                NextSwitch = tick() + math.max(Balance.SwitchCooldown, 0.25)
	                bedwars.AbilityController:useAbility("trapper_switch", nil, {trapType = Item})
	            end
	            return false
	        end
	
	        local Controller = bedwars.TrapperController
	        local Aim = {
	            character = LocalPlayer.Character,
	            trapType = Item,
	            source = "binding",
	            released = true,
	            payload = {trapType = Item, target = Position, normal = Vector3.yAxis}
	        }
	        Controller.currentAim = Aim
	        local Success, Fired = pcall(function(): boolean
	            if not bedwars.AbilityController:canUseAbility("trapper_throw", {disableBlockedAbilityAlert = true}) then
	                return false
	            end
	            bedwars.AbilityController:useAbility("trapper_throw", nil, Aim.payload)
	            return true
	        end)
	        if Controller.currentAim == Aim then
	            Controller:cancelAim()
	        end
	        if not Success then
	            error(Fired)
	        end
	        if not Fired then
	            return false
	        end
	    else
	        local Previous: number? = Switch.Enabled and store.hand.tool and GetHotbar(store.hand.tool) or nil
	        bedwars.placeBlock(Position, Item)
	        if Previous then
	            HotbarSwitch(Previous)
	        end
	    end
	
	    Placed[Position] = tick() + 2
	    if Notify.Enabled then
	        SendNotification("AutoTrap", `Placed {Item}`, 3)
	    end
	    return true
	end
	
	local function GetBed(): BasePart?
	    local Own: string = `Team{LocalPlayer:GetAttribute("Team") or -1}NoBreak`
	    local Closest, ClosestDistance = nil, Range.Value
	    for _, v: BasePart in CollectionService:GetTagged("bed") do
	        local Mine: boolean = v:GetAttribute(Own) and true or false
	        if Mine ~= (Target.Value == "Your bed") then
	            continue
	        end
	
	        local Distance: number = (Entity.character.RootPart.Position - v.Position).Magnitude
	        if Distance < ClosestDistance then
	            Closest, ClosestDistance = v, Distance
	        end
	    end
	    return Closest
	end
	
	local function TrapBed(Item: string): boolean
	    local Bed: BasePart? = GetBed()
	    if not Bed then
	        return false
	    end
	
	    local Step: number = Radius.Value * 3
	    for X: number = -Step, Step, 3 do
	        for Z: number = -Step, Step, 3 do
	            if math.abs(X) ~= Step and math.abs(Z) ~= Step then
	                continue
	            end
	
	            local Position: Vector3? = GetGround(Bed.Position + Vector3.new(X, 0, Z))
	            if Position and PlaceTrap(Position, Item) then
	                return true
	            end
	        end
	    end
	    return false
	end
	
	local function GetEnemies(): {any}
	    return Entity.AllPosition({
	        Range = Detonate.Enabled and TrapperUtil.getArmedTrapCount(LocalPlayer, "explosive_trap") > 0 and math.huge or PlaceRange.Value + 15,
	        Part = "RootPart",
	        Players = Targets.Players.Enabled,
	        NPCs = Targets.NPCs.Enabled,
	        Wallcheck = (IgnoreWalls.Enabled or Targets.Walls.Enabled) and true or nil,
	        Sort = SortMethods.Distance
	    })
	end
	
	local function TrapEnemies(Item: string, Enemies: {any}): boolean
	    local Origin: Vector3 = Entity.character.RootPart.Position + Vector3.new(0, 1, 0)
	    for _, v: any in Enemies do
	        local Position: Vector3 = v.RootPart.Position
	        local Velocity: Vector3 = v.RootPart.AssemblyLinearVelocity * Vector3.new(1, 0, 1)
	        local Duration: number = TrapperUtil.trapThrowDuration(Origin, Position) + Balance.SettleTime + Constants.TrapperTrapMeta[Item].setupTime + (store.ping.total or 0)
	        local Lead: Vector3 = Velocity * Duration
	        if Lead.Magnitude > 18 then
	            Lead = Lead.Unit * 18
	        end
	
	        for _, Factor: number in {1, 0.5, 0} do
	            local Ground: Vector3? = GetGround(Position + Lead * Factor - Vector3.new(0, v.HipHeight - 1.5, 0))
	            if Ground and PlaceTrap(Ground, Item) then
	                return true
	            end
	        end
	    end
	    return false
	end
	
	local function DetonateTraps(PlacedTraps: {BasePart}, Enemies: {any})
	    if not Detonate.Enabled or tick() < NextDetonate or TrapperUtil.getArmedTrapCount(LocalPlayer, "explosive_trap") == 0 or not bedwars.TrapperController:canUseAbilities() or not bedwars.AbilityController:canUseAbility("trapper_detonate", {disableBlockedAbilityAlert = true}) then
	        return
	    end
	
	    for _, v: BasePart in PlacedTraps do
	        if v.Name ~= "explosive_trap" or v:GetAttribute("PlacedByUserId") ~= LocalPlayer.UserId or v:GetAttribute("SnapTrapState") ~= TrapState.ACTIVE then
	            continue
	        end
	
	        local Normal: Vector3 = v:GetAttribute("TrapperSurfaceNormal") or Vector3.yAxis
	        local Center: Vector3 = TrapperUtil.trapSurfacePosition(v.Position, Normal)
	        for _, Ent: any in Enemies do
	            local Predicted: Vector3 = Ent.RootPart.Position + Ent.RootPart.AssemblyLinearVelocity * Balance.ExplosionDelay
	            if (Ent.RootPart.Position - Center).Magnitude <= Balance.ExplosionRadius and (Predicted - Center).Magnitude <= Balance.ExplosionRadius then
	                NextDetonate = tick() + math.max(Balance.DetonateCooldown, Balance.ExplosionDelay)
	                bedwars.AbilityController:useAbility("trapper_detonate")
	                return
	            end
	        end
	    end
	end
	
	AutoTrap = vape.Categories.Kits:CreateModule({
	    Name = "AutoTrap",
	    Function = function(Callback: boolean)
	        Session += 1
	        if Callback then
	            local CurrentSession: number = Session
	            table.clear(Placed)
	            NextThrow, NextSwitch, NextDetonate, BedCount = 0, 0, 0, 0
	            local PlacedTraps: {BasePart} = Collection("trapper_trap", AutoTrap)
	
	            repeat
	                if Entity.isAlive and (not KitCheck.Enabled or store.hasKit("trapper")) then
	                    local Enemies: {any} = GetEnemies()
	                    DetonateTraps(PlacedTraps, Enemies)
	                    if tick() >= NextThrow then
	                        local EnemyMode: boolean = Mode.Value == "Enemies"
	                        local Item: string? = GetTrap(EnemyMode)
	                        if Item then
	                            UpdateFilter()
	                            local Success: boolean = EnemyMode and TrapEnemies(Item, Enemies) or not EnemyMode and TrapBed(Item)
	                            if Success then
	                                BedCount = EnemyMode and 0 or BedCount + 1
	                                local Pause: boolean = EnemyMode or BedCount >= Amount.Value
	                                NextThrow = tick() + math.max(Balance.ThrowCooldown, Pause and Delay.Value or 0)
	                                if Pause then
	                                    BedCount = 0
	                                end
	                            end
	                        end
	                    end
	                end
	
	                for Position: Vector3, Expiry: number in Placed do
	                    if tick() >= Expiry then
	                        Placed[Position] = nil
	                    end
	                end
	                task.wait(0.1)
	            until not AutoTrap.Enabled or CurrentSession ~= Session
	        end
	    end,
	    Tooltip = "Throws the reworked Trapper traps at enemies or around a bed and detonates armed explosives"
	})
	
	Mode = AutoTrap:CreateDropdown({
	    Name = "Mode",
	    List = {"Bed ring", "Enemies"},
	    Function = function(Val: string)
	        if Traps then
	            local EnemyMode: boolean = Val == "Enemies"
	            Target.Object.Visible = not EnemyMode
	            Radius.Object.Visible = not EnemyMode
	            Range.Object.Visible = not EnemyMode
	            Amount.Object.Visible = not EnemyMode
	            Traps.Object.Visible = not EnemyMode
	            IgnoreWalls.Object.Visible = EnemyMode
	        end
	        BedCount = 0
	    end,
	    Tooltip = "Bed ring surrounds a bed; Enemies throws ahead of nearby targets using the trap's travel and arming time"
	})
	Targets = AutoTrap:CreateTargets({Players = true})
	TrapType = AutoTrap:CreateDropdown({
	    Name = "Trap type",
	    List = {"Auto", "Snap", "Venom", "Explosive"},
	    Tooltip = "Auto uses your selected stocked trap against enemies and the Traps list around beds"
	})
	Target = AutoTrap:CreateDropdown({
	    Name = "Target",
	    List = {"Your bed", "Enemy bed"}
	})
	Radius = AutoTrap:CreateSlider({
	    Name = "Radius",
	    Min = 1,
	    Max = 5,
	    Default = 2,
	    Suffix = "blocks"
	})
	Range = AutoTrap:CreateSlider({
	    Name = "Range",
	    Min = 4,
	    Max = 60,
	    Default = 20,
	    Suffix = "studs",
	    Tooltip = "How close the bed has to be before placing"
	})
	Amount = AutoTrap:CreateSlider({
	    Name = "Amount",
	    Min = 1,
	    Max = 8,
	    Default = 3,
	    Suffix = "traps",
	    Tooltip = "Traps to throw per bed ring pass"
	})
	PlaceRange = AutoTrap:CreateSlider({
	    Name = "Place Range",
	    Min = 1,
	    Max = 45,
	    Default = 30,
	    Suffix = "studs",
	    Tooltip = "Maximum throw distance, capped at the game's throw range"
	})
	Delay = AutoTrap:CreateSlider({
	    Name = "Delay",
	    Min = 0.35,
	    Max = 10,
	    Default = 0.5,
	    Decimal = 100,
	    Suffix = "seconds",
	    Tooltip = "Wait between enemy throws or bed ring passes, respecting the game's cooldown"
	})
	IgnoreWalls = AutoTrap:CreateToggle({
	    Name = "Ignore behind walls",
	    Visible = false,
	    Tooltip = "Skips enemies you cannot see; throw paths are always checked"
	})
	Detonate = AutoTrap:CreateToggle({
	    Name = "Auto detonate",
	    Default = true,
	    Tooltip = "Detonates all your armed explosives when an enemy is inside a blast and is predicted to remain there"
	})
	Switch = AutoTrap:CreateToggle({
	    Name = "Switch back",
	    Default = true,
	    Tooltip = "Restores your hotbar slot after placing an inventory trap; Trapper throws do not change your held item"
	})
	Notify = AutoTrap:CreateToggle({Name = "Notify"})
	Traps = AutoTrap:CreateTextList({
	    Name = "Traps",
	    Default = {"snap_trap", "venom_trap", "explosive_trap", "invisible_landmine", "spike_trap", "tesla_trap", "grave_trap", "lucky_block_trap"},
	    Darker = true,
	    Placeholder = "item",
	    Tooltip = "Bed ring trap priority; Trapper traps use your kit stock and other traps use your inventory"
	})
	KitCheck = AutoTrap:CreateToggle({
	    Name = "Kit check",
	    Tooltip = "Only throws traps while you are using the Trapper kit, turn it off to throw inventory traps with any kit",
	    Default = true
	})
end)

Run(function()
	local AutoTriton
	local Legit
	local Back
	local BackDelay
	local Limit
	local FallSpeed
	local Search
	local KitCheck
	local NextFire: number = 0
	
	local RayCheck: RaycastParams = RaycastParams.new()
	RayCheck.RespectCanCollide = true
	RayCheck.FilterType = Enum.RaycastFilterType.Include
	
	local function GetNearGround(Origin: Vector3)
	    for Step: number = 1, Search.Value do
	        for _, v: Vector3 in {Vector3.xAxis, Vector3.zAxis, -Vector3.xAxis, -Vector3.zAxis} do
	            local RayResult: RaycastResult? = workspace:Raycast((Origin + Vector3.new(0, 3, 0)) + (v * Step), Vector3.new(0, -80, 0), RayCheck)
	            if RayResult then
	                return RayResult.Position
	            end
	        end
	    end
	    return nil
	end
	
	local function FireHarpoon(Item, Spot: Vector3)
	    local Meta = bedwars.ProjectileMeta.harpoon_projectile
	    local Source = bedwars.ItemMeta[Item.itemType].projectileSource
	    local Origin: Vector3 = Entity.character.RootPart.Position
	    local Speed, Gravity = Meta.launchVelocity, Meta.gravitationalAcceleration or 196.2
	    local ShootPosition: Vector3 = (CFrame.new(Origin, Spot) * CFrame.new(Vector3.new(-bedwars.BowConstantsTable.RelX, -bedwars.BowConstantsTable.RelY, -bedwars.BowConstantsTable.RelZ))).Position
	    local AimPoint: Vector3? = Prediction.SolveTrajectory(ShootPosition, Speed, Gravity, Spot, Vector3.zero, workspace.Gravity, 0, nil, nil, false, Spot)
	    if not AimPoint then
	        return false
	    end
	
	    local Hotbar, Previous = GetHotbar(Item.tool), store.hand.tool
	    SwitchItem(Item.tool)
	    if Legit.Enabled and Hotbar then
	        HotbarSwitch(Hotbar)
	    end
	
	    NextFire = tick() + (Source and Source.fireDelaySec or 8)
	    bedwars.Handler:Get("ProjectileFire"):Fire("CallServerAsync",
	        Item.tool,
	        nil,
	        Source and Source.projectileType(Item.itemType) or "harpoon_projectile",
	        ShootPosition,
	        Origin,
	        CFrame.lookAt(ShootPosition, AimPoint).LookVector * Speed,
	        bedwars.IdUtil.generateId(8),
	        bedwars.getShotData(Item.itemType),
	        workspace:GetServerTimeNow() - 0.045
	    ):andThen(function(Result)
	        if type(Result) == "table" and Result.accepted and Result.model then
	            Result.model.Parent = ReplicatedStorage
	        end
	    end)
	
	    if Back.Enabled and Previous then
	        task.wait(BackDelay:GetRandomValue())
	        SwitchItem(Previous)
	        if Legit.Enabled and GetHotbar(Previous) then
	            HotbarSwitch(GetHotbar(Previous))
	        end
	    end
	    return true
	end
	
	AutoTriton = vape.Categories.Kits:CreateModule({
	    Name = "AutoTriton",
	    Function = function(Callback: boolean)
	        if Callback then
	            NextFire = 0
	            local LastGround: Vector3?
	
	            repeat
	                if Entity.isAlive and (not KitCheck.Enabled or store.hasKit("harpoon")) and tick() >= NextFire and (not Limit.Enabled or store.hand.tool and store.hand.tool.Name == "harpoon") then
	                    local Root: BasePart = Entity.character.RootPart
	                    local Harpoon = GetItem("harpoon")
	                    RayCheck.FilterDescendantsInstances = {store.map}
	                    RayCheck.CollisionGroup = Root.CollisionGroup
	
	                    if Entity.character.Humanoid.FloorMaterial ~= Enum.Material.Air then
	                        LastGround = Root.Position
	                    end
	
	                    if Harpoon and Root.AssemblyLinearVelocity.Y < -FallSpeed.Value and not workspace:Raycast(Root.Position, Vector3.new(0, -200, 0), RayCheck) then
	                        local Spot: Vector3? = GetNearGround(Root.Position + Vector3.new(0, 40, 0)) or LastGround and GetNearGround(LastGround + Vector3.new(0, 5, 0))
	                        if Spot then
	                            FireHarpoon(Harpoon, Spot)
	                        end
	                    end
	                end
	                task.wait(0.1)
	            until not AutoTriton.Enabled
	        end
	    end,
	    Tooltip = "Automatically throws the trident onto nearby ground when you are falling into the void"
	})
	
	FallSpeed = AutoTriton:CreateSlider({
	    Name = "Fall speed",
	    Min = 10,
	    Max = 200,
	    Default = 60,
	    Suffix = "studs a second",
	    Tooltip = "How fast you have to be falling before it throws"
	})
	Search = AutoTriton:CreateSlider({
	    Name = "Search range",
	    Min = 4,
	    Max = 60,
	    Default = 40,
	    Suffix = function(Val: number)
	        return Val <= 1 and "stud" or "studs"
	    end,
	    Tooltip = "How far out it looks for ground to land on"
	})
	Legit = AutoTriton:CreateToggle({
	    Name = "Legit Switch",
	    Default = true,
	    Tooltip = "Visualizes the switching clientside"
	})
	Back = AutoTriton:CreateToggle({
	    Name = "Switch back",
	    Function = function(Callback: boolean)
	        if BackDelay then
	            BackDelay.Object.Visible = Callback
	        end
	    end,
	    Default = true,
	    Tooltip = "Switches back to the last slot after throwing"
	})
	BackDelay = AutoTriton:CreateTwoSlider({
	    Name = "Switch Back Delay",
	    Min = 0,
	    Max = 2,
	    DefaultMin = 0.1,
	    DefaultMax = 0.2,
	    Darker = true
	})
	Limit = AutoTriton:CreateToggle({
	    Name = "Limit to item",
	    Tooltip = "Only throws when you are already holding the trident"
	})
	KitCheck = AutoTriton:CreateToggle({
	    Name = "Kit check",
	    Tooltip = "Only throws while you are using the Triton kit",
	    Default = true
	})
end)

Run(function()
	local AutoTrixie
	local Targets
	local Warp
	local WarpRange
	local Rewind
	local Health
	local KitCheck
	local NextAbility: number = 0
	
	AutoTrixie = vape.Categories.Kits:CreateModule({
	    Name = "AutoTrixie",
	    Function = function(Callback: boolean)
	        if Callback then
	            NextAbility = 0
	
	            repeat
	                if Entity.isAlive and (not KitCheck.Enabled or store.hasKit("void_walker")) and tick() >= NextAbility then
	                    local Humanoid: Humanoid = Entity.character.Humanoid
	
	                    if Rewind.Enabled and Humanoid.Health <= (Humanoid.MaxHealth * (Health.Value / 100)) and bedwars.AbilityController:canUseAbility("void_walker_rewind", {disableBlockedAbilityAlert = true}) then
	                        NextAbility = tick() + 1
	                        bedwars.AbilityController:useAbility("void_walker_rewind")
	                    elseif Warp.Enabled and bedwars.AbilityController:canUseAbility("void_walker_warp", {disableBlockedAbilityAlert = true}) then
	                        local Target = Entity.EntityPosition({
	                            Range = WarpRange.Value,
	                            Part = "RootPart",
	                            Players = Targets.Players.Enabled,
	                            NPCs = Targets.NPCs.Enabled,
	                            Wallcheck = Targets.Walls.Enabled,
	                            Sort = SortMethods.Distance
	                        })
	
	                        if Target then
	                            local Root: BasePart = Entity.character.RootPart
	                            Root.CFrame = CFrame.lookAlong(Root.Position, (Target.RootPart.Position - Root.Position) * Vector3.new(1, 0, 1))
	                            NextAbility = tick() + 1
	                            bedwars.AbilityController:useAbility("void_walker_warp")
	                        end
	                    end
	                end
	                task.wait(0.1)
	            until not AutoTrixie.Enabled
	        end
	    end,
	    Tooltip = "Warps you onto whoever you are chasing and rifts you back out when it goes wrong"
	})
	
	Targets = AutoTrixie:CreateTargets({
	    Players = true,
	    NPCs = true,
	    Walls = true
	})
	Warp = AutoTrixie:CreateToggle({
	    Name = "Warp to target",
	    Default = true,
	    Function = function(Callback: boolean)
	        if WarpRange then
	            WarpRange.Object.Visible = Callback
	        end
	    end,
	    Tooltip = "Turns you at the closest enemy before warping so the portal lands on them"
	})
	WarpRange = AutoTrixie:CreateSlider({
	    Name = "Warp range",
	    Min = 5,
	    Max = 80,
	    Default = 40,
	    Suffix = function(Val: number)
	        return Val <= 1 and "stud" or "studs"
	    end
	})
	Rewind = AutoTrixie:CreateToggle({
	    Name = "Rewind on low health",
	    Default = true,
	    Function = function(Callback: boolean)
	        if Health then
	            Health.Object.Visible = Callback
	        end
	    end
	})
	Health = AutoTrixie:CreateSlider({
	    Name = "Health",
	    Min = 1,
	    Max = 100,
	    Default = 40,
	    Suffix = "%"
	})
	KitCheck = AutoTrixie:CreateToggle({
	    Name = "Kit check",
	    Tooltip = "Only runs while you are using the Trixie kit",
	    Default = true
	})
end)

Run(function()
	local AutoUma
	local Range
	local Limit
	local Animation
	local AutoSummon
	local HealSpirit
	local AttackSpirit
	local TargetItemDrops
	local Diamond
	local Emerald
	local KitCheck
	
	local function GetAttackData()
	    if Limit.Enabled then
	        local Tool: Tool? = (store.hand.tool and store.hand.tool.Name == "spirit_staff") and store.hand.tool or nil
	        return Tool, Tool and GetHotbar(Tool) or nil
	    end
	    for i: number, v: any in store.inventory.inventory.items do
	        if v.itemType == "spirit_staff" and v.tool then
	            SwitchItem(v.tool, 0)
	            return v.tool, i
	        end
	    end
	    return
	end
	
	local RayCheck: RaycastParams = RaycastParams.new()
	RayCheck.FilterType = Enum.RaycastFilterType.Include
	
	local function FireSpirit(Staff, SpiritType: string, Drop: BasePart)
	    local Meta = bedwars.ProjectileMeta[SpiritType]
	    if not Meta then
	        return false
	    end
	
	    local LocalPosition: Vector3 = Entity.character.RootPart.Position
	    local ShootPosition: Vector3 = LocalPosition + Vector3.new(0, 2, 0)
	    RayCheck.FilterDescendantsInstances = store.map and {store.map} or {}
	
	    local AimPoint: Vector3? = Prediction.SolveTrajectory(ShootPosition, Meta.launchVelocity, Meta.gravitationalAcceleration or 196.2, Drop.Position, Vector3.zero, workspace.Gravity, 0, 0, RayCheck)
	    if not AimPoint then
	        return false
	    end
	
	    bedwars.Handler:Get("ProjectileFire"):Fire("CallServerAsync",
	        Staff,
	        nil,
	        SpiritType,
	        ShootPosition,
	        LocalPosition,
	        CFrame.lookAt(ShootPosition, AimPoint).LookVector * Meta.launchVelocity,
	        bedwars.IdUtil.generateId(8),
	        bedwars.getShotData(Staff.Name),
	        workspace:GetServerTimeNow() - 0.045
	    )
	
	    return true
	end
	
	local function GetDrops(LocalPosition: Vector3, ItemDrops: {BasePart})
	    local Drop, LastMagnitude = nil, Range.Value + 1
	    for _, v: BasePart in ItemDrops do
	        if v.Name == "emerald" and Emerald.Enabled or v.Name == "diamond" and Diamond.Enabled then
	            local Magnitude: number = (LocalPosition - v.Position).Magnitude
	            if Magnitude <= LastMagnitude and not Entity.Wallcheck(LocalPosition, v.Position, {Camera, LocalPlayer.Character, v}) then
	                Drop, LastMagnitude = v, Magnitude
	            end
	        end
	    end
	    return Drop
	end
	
	AutoUma = vape.Categories.Kits:CreateModule({
	    Name = "AutoUma",
	    Function = function(Callback: boolean)
	        if Callback then
	            local Items: {BasePart} = Collection("ItemDrop", AutoUma)
	            repeat
	                local Staff = (not KitCheck.Enabled or store.hasKit("spirit_summoner")) and GetAttackData()
	                if Staff then
	                    if TargetItemDrops.Enabled then
	                        local AttackSpirits: number = (LocalPlayer:GetAttribute("ReadySummonedAttackSpirits") or 0)
	                        local HealSpirits: number = (LocalPlayer:GetAttribute("ReadySummonedHealSpirits") or 0)
	
	                        if AutoSummon.Enabled then
	                            if AttackSpirit.Enabled and AttackSpirits < 1 and GetItem("summon_stone") then
	                                bedwars.AbilityController:useAbility("summon_attack_spirit")
	                            end
	
	                            if HealSpirit.Enabled and HealSpirits < 1 and GetItem("summon_stone") then
	                                bedwars.AbilityController:useAbility("summon_heal_spirit")
	                            end
	                        end
	
	                        if (HealSpirits + AttackSpirits) > 0 then
	                            local LocalPosition: Vector3 = Entity.character.RootPart.Position
	                            local Drop: BasePart? = GetDrops(LocalPosition, Items)
	                            if Drop and FireSpirit(Staff, AttackSpirits > 0 and "attack_spirit" or "heal_spirit", Drop) then
	                                if Animation.Enabled then
	                                    bedwars.GameAnimationUtil:playAnimation(LocalPlayer.Character, bedwars.AnimationType.WIZARD_BALL_CAST)
	                                    bedwars.AudioManager:playAudio(bedwars.SoundList.SPIRIT_SUMMONER_CHANGE_AFFINITY, {})
	                                end
	
	                                task.wait(1.5)
	                            end
	                        end
	                    end
	                end
	                task.wait(0.1)
	            until not AutoUma.Enabled
	        end
	    end,
	    Tooltip = "Automatically throw spirits at item drops and opponents."
	})
	
	Range = AutoUma:CreateSlider({
	    Name = "Range",
	    Min = 1,
	    Max = 80,
	    Default = 50,
	    Decimal = 5,
	    Suffix = function(Val: number)
	        return Val >= 2 and "studs" or "stud"
	    end
	})
	Animation = AutoUma:CreateToggle({
	    Name = "Animation",
	    Default = true
	})
	Limit = AutoUma:CreateToggle({
	    Name = "Limit to item",
	    Default = true
	})
	AutoSummon = AutoUma:CreateToggle({
	    Name = "Auto Summon",
	    Function = function(Callback: boolean)
	        if AttackSpirit then
	            AttackSpirit.Object.Visible = Callback
	            HealSpirit.Object.Visible = Callback
	        end
	    end,
	    Tooltip = "Automattically summons spirit for you"
	})
	HealSpirit = AutoUma:CreateToggle({
	    Name = "Use heal spirit",
	    Default = true,
	    Visible = false,
	    Darker = true
	})
	AttackSpirit = AutoUma:CreateToggle({
	    Name = "Use attack spirit",
	    Default = true,
	    Visible = false,
	    Darker = true
	})
	TargetItemDrops = AutoUma:CreateToggle({
	    Name = "Target item drops",
	    Function = function(Callback: boolean)
	        if Emerald then
	            Emerald.Object.Visible = Callback
	            Diamond.Object.Visible = Callback
	        end
	    end,
	    Default = true
	})
	Emerald = AutoUma:CreateToggle({
	    Name = "Emerald",
	    Darker = true,
	    Default = true
	})
	Diamond = AutoUma:CreateToggle({
	    Name = "Diamond",
	    Darker = true,
	    Default = true
	})
	KitCheck = AutoUma:CreateToggle({
	    Name = "Kit check",
	    Tooltip = "Only runs while you are using the Uma kit",
	    Default = true
	})
end)

