Run(function()
	local AutoWarrior
	local Targets
	local Range
	local Amount
	local KitCheck
	
	AutoWarrior = vape.Categories.Kits:CreateModule({
	    Name = "AutoWarrior",
	    Function = function(Callback: boolean)
	        if Callback then
	            repeat
	                if Entity.isAlive and (not KitCheck.Enabled or store.hasKit("warrior")) and bedwars.AbilityController:canUseAbility("warrior_strike", {disableBlockedAbilityAlert = true}) then
	                    local Found: number = #Entity.AllPosition({
	                        Range = Range.Value,
	                        Part = "RootPart",
	                        Players = Targets.Players.Enabled,
	                        NPCs = Targets.NPCs.Enabled,
	                        Wallcheck = Targets.Walls.Enabled
	                    })
	
	                    if Found >= Amount.Value then
	                        bedwars.AbilityController:useAbility("warrior_strike")
	                    end
	                end
	                task.wait(0.1)
	            until not AutoWarrior.Enabled
	        end
	    end,
	    Tooltip = "Automatically uses Warriors Strike once enough enemies are next to you"
	})
	
	Targets = AutoWarrior:CreateTargets({
	    Players = true,
	    NPCs = true,
	    Walls = true
	})
	Range = AutoWarrior:CreateSlider({
	    Name = "Range",
	    Min = 1,
	    Max = 40,
	    Default = 14,
	    Suffix = function(Val: number)
	        return Val <= 1 and "stud" or "studs"
	    end
	})
	Amount = AutoWarrior:CreateSlider({
	    Name = "Targets",
	    Min = 1,
	    Max = 8,
	    Default = 1,
	    Tooltip = "Enemies in range before striking"
	})
	KitCheck = AutoWarrior:CreateToggle({
	    Name = "Kit check",
	    Tooltip = "Only strikes while you are using the Warrior kit",
	    Default = true
	})
end)

Run(function()
	local AutoWhim
	local Targets
	local Range
	local FireRate
	local SwitchDelay
	local KitCheck
	local NextFire: number = 0
	
	local function CastSpell()
	    local Item = GetItem("mage_spellbook")
	    local Util = bedwars.MageKitUtil
	    local Element: string? = bedwars.BalanceFile.MAGE_ELEMENT_CYCLE[(LocalPlayer:GetAttribute("MageElementIndex") or 0) + 1]
	    if not Element or table.find(Util.getUnlockedMageElements(LocalPlayer), Element) == nil then
	        Element = "BASE"
	    end
	
	    local Meta = Util.MageElementMeta[Element]
	    local Source = Item and Meta and Meta.projectileSource or nil
	    local Target = Source and GetFacingEntity({
	        Part = "RootPart",
	        Range = Range.Value,
	        Players = Targets.Players.Enabled,
	        NPCs = Targets.NPCs.Enabled,
	        Priority = Targets.Priority.Value,
	        Wallcheck = Targets.Walls.Enabled,
	        Limit = 10
	    }) or nil
	    if not Target then
	        return
	    end
	
	    local Hotbar = store.hand.tool and GetHotbar(store.hand.tool) or nil
	    if HotbarSwitch(GetHotbar(Item.tool)) then
	        task.wait(store.ping.total or 0)
	        if FireProjectile(Item, "mage_spellbook", Source.projectileType("mage_spellbook"), Target) then
	            NextFire = tick() + Source.fireDelaySec + FireRate:GetRandomValue()
	            task.wait(SwitchDelay.Value)
	        end
	        HotbarSwitch(Hotbar)
	    end
	end
	
	AutoWhim = vape.Categories.Kits:CreateModule({
	    Name = "AutoWhim",
	    Function = function(Callback: boolean)
	        if Callback then
	            NextFire = 0
	
	            repeat
	                if Entity.isAlive and (not KitCheck.Enabled or store.hasKit("mage")) and store.hand.toolType == "sword" and (tick() - bedwars.SwordController.lastSwing) < 0.2 and tick() >= NextFire then
	                    CastSpell()
	                end
	                task.wait(0.1)
	            until not AutoWhim.Enabled
	        end
	    end,
	    Tooltip = "Automatically casts Whim's magic book at whoever you're meleeing"
	})
	
	Targets = AutoWhim:CreateTargets({
	    Players = true,
	    NPCs = false
	})
	Range = AutoWhim:CreateSlider({
	    Name = "Range",
	    Min = 1,
	    Max = 60,
	    Default = 22,
	    Suffix = function(Val: number)
	        return Val <= 1 and "stud" or "studs"
	    end
	})
	FireRate = AutoWhim:CreateTwoSlider({
	    Name = "Fire Rate",
	    Min = 0,
	    Max = 1,
	    DefaultMin = 0.05,
	    DefaultMax = 0.12,
	    Decimal = 100
	})
	SwitchDelay = AutoWhim:CreateSlider({
	    Name = "Switch Delay",
	    Min = 0,
	    Max = 1,
	    Decimal = 100,
	    Suffix = "seconds",
	    Default = 0.02
	})
	KitCheck = AutoWhim:CreateToggle({
	    Name = "Kit check",
	    Tooltip = "Only casts while you are using the Whim kit",
	    Default = true
	})
end)

Run(function()
	local AutoWhimElement
	local Range
	local Delay
	local Notify
	local KitCheck
	local Attempts: {[string]: number} = {}
	
	local function LearnTome(Tome: Instance)
	    local Secret = Tome:GetAttribute("TomeSecret")
	    if not Secret or (Attempts[Secret] or 0) > tick() then
	        return
	    end
	
	    Attempts[Secret] = tick() + 3
	    local Result = bedwars.Handler:Get("LearnElementTome"):Fire("CallServer", {secret = Secret})
	    if typeof(Result) ~= "table" or not Result.element then
	        return
	    end
	
	    local Element = Result.element
	    pcall(function()
	        bedwars.MageController:destroyTomeGuidingBeam()
	        bedwars.MageController:playLearnTomeEffect(LocalPlayer, Tome, Element)
	    end)
	
	    task.delay(bedwars.BalanceFile.LEARN_TOME_DURATION or 2, function()
	        pcall(function()
	            bedwars.MageController:fadeOutTome(Tome)
	            if LocalPlayer.Character then
	                bedwars.MageKitUtil.changeMageKitAppearance(LocalPlayer, LocalPlayer.Character, Element)
	            end
	        end)
	    end)
	    if Notify.Enabled then
	        notif("AutoWhimElement", `Learned the {Result.element} element`, 5, "info")
	    end
	end
	
	AutoWhimElement = vape.Categories.Kits:CreateModule({
	    Name = "AutoWhimElement",
	    Function = function(Callback: boolean)
	        if Callback then
	            table.clear(Attempts)
	
	            repeat
	                if Entity.isAlive and (not KitCheck.Enabled or store.hasKit("mage")) then
	                    local LocalPosition: Vector3 = Entity.character.RootPart.Position
	
	                    for _, v: Instance in CollectionService:GetTagged("ElementTome") do
	                        local Part = v.Parent and (not v:IsA("Model") and v or (v.PrimaryPart or v:FindFirstChildWhichIsA("BasePart", true)))
	                        if Part and (Part.Position - LocalPosition).Magnitude <= Range.Value then
	                            LearnTome(v)
	                        end
	                    end
	                end
	                task.wait(Delay.Value)
	            until not AutoWhimElement.Enabled
	        else
	            table.clear(Attempts)
	        end
	    end,
	    Tooltip = "Reads every Tome of the Elements it can reach so Whim unlocks its spells"
	})
	
	Range = AutoWhimElement:CreateSlider({
	    Name = "Range",
	    Min = 1,
	    Max = 500,
	    Default = 10,
	    Suffix = function(Val: number)
	        return Val <= 1 and "stud" or "studs"
	    end,
	    Tooltip = "The prompt the game gives you stops at 10 studs"
	})
	Delay = AutoWhimElement:CreateSlider({
	    Name = "Delay",
	    Min = 0.1,
	    Max = 5,
	    Decimal = 10,
	    Default = 0.5,
	    Suffix = "seconds",
	    Tooltip = "How often it looks for a tome"
	})
	Notify = AutoWhimElement:CreateToggle({
	    Name = "Notify",
	    Default = true,
	    Tooltip = "Tells you which element you picked up"
	})
	KitCheck = AutoWhimElement:CreateToggle({
	    Name = "Kit check",
	    Tooltip = "Only reads tomes while you are using the Whim kit",
	    Default = true
	})
end)

Run(function()
	local AutoWhisper
	local Heal
	local Threshold
	local Fly
	local Owl
	local Target
	local FOVCheck
	local FOV
	local RangeCircle
	local CircleColor
	local CircleTransparency
	local CircleThickness
	local CircleFilled
	local CircleObject
	local KitCheck
	
	local Teammates: {string} = {"None"}
	local Old
	local MapBottom: number = math.huge
	local FallDepth: number = 12
	local FootingCharacter, FootingY = nil, -math.huge
	
	local Success, OwlBalance = pcall(function()
	    return require(ReplicatedStorage.TS.balance["owl-balance-file"]).OwlBalance
	end)
	local AttachRange: number = Success and OwlBalance and OwlBalance.OWL_ATTACH_MAX_RANGE or 60
	
	local function GetMouseOrigin()
	    return UserInputService.TouchEnabled and Camera.ViewportSize / 2 or UserInputService:GetMouseLocation()
	end
	
	local function GetOwlTarget(): Player?
	    local Picked: Player? = Players:FindFirstChild(Target.Value)
	    if not FOVCheck.Enabled then
	        return Picked
	    end
	
	    if not Entity.isAlive then
	        return nil
	    end
	
	    local Origin: Vector2 = GetMouseOrigin()
	    local Best, BestDistance = nil, FOV.Value
	    for _, v: Player in (Picked and {Picked} or Players:GetPlayers()) do
	        local Character: Model? = v.Character
	        local Root: BasePart? = Character and Character:FindFirstChild("HumanoidRootPart")
	        if v == LocalPlayer or not Root or v:GetAttribute("Team") ~= LocalPlayer:GetAttribute("Team") or v:GetAttribute("IsOwlTarget") then
	            continue
	        end
	
	        if (Root.Position - Entity.character.RootPart.Position).Magnitude > AttachRange then
	            continue
	        end
	
	        local Position, Visible = Camera:WorldToViewportPoint(Root.Position)
	        local Distance: number = (Vector2.new(Position.X, Position.Y) - Origin).Magnitude
	        if Visible and Distance <= BestDistance then
	            Best, BestDistance = v, Distance
	        end
	    end
	
	    return Best
	end
	
	local function RefreshOptions()
	    local ShowFOV: boolean = Owl.Enabled and FOVCheck.Enabled
	    local ShowCircle: boolean = ShowFOV and RangeCircle.Enabled
	
	    Target.Object.Visible = Owl.Enabled
	    FOVCheck.Object.Visible = Owl.Enabled
	    FOV.Object.Visible = ShowFOV
	    RangeCircle.Object.Visible = ShowFOV
	    CircleColor.Object.Visible = ShowCircle
	    CircleTransparency.Object.Visible = ShowCircle
	    CircleThickness.Object.Visible = ShowCircle
	    CircleFilled.Object.Visible = ShowCircle
	
	    if CircleObject then
	        CircleObject.Visible = AutoWhisper.Enabled and ShowFOV
	    end
	end
	
	local function GetAttachedCharacter(): Model?
	    local Attached: Instance? = bedwars.OwlAbilityController.target
	    if Attached and Attached:IsA("Player") then
	        return Attached.Character
	    end
	    return Attached :: Model?
	end
	
	local function GetMapBottom(): number
	    if MapBottom == math.huge then
	        for _, v: BasePart in store.blocks do
	            MapBottom = math.min(MapBottom, v.Position.Y - (v.Size.Y / 2))
	        end
	    end
	    return MapBottom == math.huge and -math.huge or MapBottom
	end
	
	local function CanUse(Ability: string): boolean
	    return bedwars.AbilityController:getEnabledAbility(Ability) ~= nil and bedwars.AbilityController:canUseAbility(Ability, {disableBlockedAbilityAlert = true})
	end
	
	local function AddConnection(TargetPlayer: Player, Connected: boolean?)
	    if not Connected then
	        vape:Clean(TargetPlayer:GetAttributeChangedSignal("Team"):Connect(function()
	            AddConnection(TargetPlayer, true)
	        end))
	    end
	
	    if TargetPlayer ~= LocalPlayer and TargetPlayer:GetAttribute("Team") == LocalPlayer:GetAttribute("Team") and not table.find(Teammates, TargetPlayer.Name) then
	        table.insert(Teammates, TargetPlayer.Name)
	        Target:Change(Teammates)
	    end
	end
	
	AutoWhisper = vape.Categories.Kits:CreateModule({
	    Name = "AutoWhisper",
	    Function = function(Callback: boolean)
	        if CircleObject then
	            CircleObject.Visible = Callback and Owl.Enabled and FOVCheck.Enabled
	        end
	
	        if Callback then
	            AutoWhisper:Clean(RunService.RenderStepped:Connect(function()
	                if CircleObject then
	                    CircleObject.Position = GetMouseOrigin()
	                end
	            end))
	
	            Old = bedwars.OwlKitController.onAbilityUsed
	            bedwars.OwlKitController.onAbilityUsed = function(self, Character, Data, ...)
	                if (not KitCheck.Enabled or store.hasKit("owl")) and Owl.Enabled and Data and Data.ability == "SUMMON_OWL" and Character == LocalPlayer.Character then
	                    local TargetPlayer: Player? = GetOwlTarget()
	                    if TargetPlayer and TargetPlayer ~= LocalPlayer then
	                        bedwars.Handler:Get("SummonOwl"):Fire("CallServer", TargetPlayer)
	                        return
	                    end
	                end
	                return Old(self, Character, Data, ...)
	            end
	
	            repeat
	                task.wait()
	            until store.matchState ~= 0 or not AutoWhisper.Enabled
	            if not AutoWhisper.Enabled then
	                return
	            end
	
	            repeat
	                if (not KitCheck.Enabled or store.hasKit("owl")) and Owl.Enabled and not bedwars.OwlAbilityController.target and GetOwlTarget() and bedwars.AbilityController:canUseAbility("SUMMON_OWL", {disableBlockedAbilityAlert = true}) then
	                    bedwars.AbilityController:useAbility("SUMMON_OWL")
	                end
	
	                local Character: Model? = GetAttachedCharacter()
	                if Character and (not KitCheck.Enabled or store.hasKit("owl")) then
	                    local Root: BasePart? = Character.PrimaryPart
	                    if Root then
	                        if FootingCharacter ~= Character then
	                            FootingCharacter, FootingY = Character, GetMapBottom() + FallDepth
	                        end
	                        if math.abs(Root.AssemblyLinearVelocity.Y) < 2 then
	                            FootingY = Root.Position.Y
	                        end
	
	                        if Fly.Enabled and Root.Position.Y < FootingY - FallDepth and CanUse("OWL_LIFT") then
	                            bedwars.AbilityController:useAbility("OWL_LIFT")
	                        end
	                    end
	
	                    local Health: number? = Character:GetAttribute("Health")
	                    local MaxHealth: number? = Character:GetAttribute("MaxHealth")
	                    if Heal.Enabled and (Threshold.Value >= 100 or Health and MaxHealth and MaxHealth > 0 and Health / MaxHealth <= Threshold.Value / 100) and CanUse("OWL_HEAL") then
	                        bedwars.AbilityController:useAbility("OWL_HEAL")
	                    end
	                end
	                task.wait(0.1)
	            until not AutoWhisper.Enabled
	        elseif Old then
	            bedwars.OwlKitController.onAbilityUsed = Old
	            Old = nil
	        end
	    end,
	    Tooltip = "Automatically uses whisper abilities"
	})
	
	Heal = AutoWhisper:CreateToggle({
	    Name = "Heal",
	    Function = function(Callback: boolean)
	        if Threshold then
	            Threshold.Object.Visible = Callback
	        end
	    end,
	    Default = true
	})
	Threshold = AutoWhisper:CreateSlider({
	    Name = "Health",
	    Min = 1,
	    Max = 100,
	    Default = 99,
	    Darker = true,
	    Suffix = "%"
	})
	Fly = AutoWhisper:CreateToggle({
	    Name = "Fly",
	    Default = true,
	    Tooltip = "Lifts the player your owl is on once they fall well below where they last stood over the void, so it never fires on normal jumps or while bridging"
	})
	Owl = AutoWhisper:CreateToggle({
	    Name = "Auto owl",
	    Function = RefreshOptions,
	    Tooltip = "Sends the owl to the teammate you pick as soon as the ability is up"
	})
	Target = AutoWhisper:CreateDropdown({
	    Name = "Teammate",
	    List = Teammates,
	    Darker = true,
	    Visible = false,
	    Tooltip = "Who the owl gets summoned onto"
	})
	FOVCheck = AutoWhisper:CreateToggle({
	    Name = "FOV check",
	    Function = RefreshOptions,
	    Darker = true,
	    Visible = false,
	    Tooltip = "Only sends the owl to a teammate inside the FOV around your mouse, within owl range and without an owl already\nWith Teammate on None it picks whoever is closest to your mouse"
	})
	FOV = AutoWhisper:CreateSlider({
	    Name = "FOV",
	    Min = 1,
	    Max = 1000,
	    Function = function(Val: number)
	        if CircleObject then
	            CircleObject.Radius = Val
	        end
	    end,
	    Darker = true,
	    Default = 150,
	    Visible = false
	})
	RangeCircle = AutoWhisper:CreateToggle({
	    Name = "Range Circle",
	    Function = function(Callback: boolean)
	        if Callback then
	            CircleObject = Drawing.new("Circle")
	            CircleObject.Filled = CircleFilled.Enabled
	            CircleObject.Color = Color3.fromHSV(CircleColor.Hue, CircleColor.Sat, CircleColor.Value)
	            CircleObject.Position = GetMouseOrigin()
	            CircleObject.Radius = FOV.Value
	            CircleObject.NumSides = 100
	            CircleObject.Thickness = CircleThickness.Value
	            CircleObject.Transparency = 1 - CircleTransparency.Value
	        else
	            pcall(function()
	                CircleObject.Visible = false
	                CircleObject:Remove()
	            end)
	            CircleObject = nil
	        end
	        RefreshOptions()
	    end,
	    Darker = true,
	    Visible = false
	})
	CircleColor = AutoWhisper:CreateColorSlider({
	    Name = "Circle Color",
	    Function = function(Hue: number, Sat: number, Val: number)
	        if CircleObject then
	            CircleObject.Color = Color3.fromHSV(Hue, Sat, Val)
	        end
	    end,
	    Darker = true,
	    Visible = false
	})
	CircleTransparency = AutoWhisper:CreateSlider({
	    Name = "Transparency",
	    Min = 0,
	    Max = 1,
	    Decimal = 10,
	    Function = function(Val: number)
	        if CircleObject then
	            CircleObject.Transparency = 1 - Val
	        end
	    end,
	    Darker = true,
	    Default = 0.5,
	    Visible = false
	})
	CircleThickness = AutoWhisper:CreateSlider({
	    Name = "Thickness",
	    Min = 1,
	    Max = 10,
	    Decimal = 10,
	    Function = function(Val: number)
	        if CircleObject then
	            CircleObject.Thickness = Val
	        end
	    end,
	    Darker = true,
	    Default = 1,
	    Visible = false,
	    Tooltip = "How wide the circle's outline is, has no effect while Circle Filled is on"
	})
	CircleFilled = AutoWhisper:CreateToggle({
	    Name = "Circle Filled",
	    Function = function(Callback: boolean)
	        if CircleObject then
	            CircleObject.Filled = Callback
	        end
	    end,
	    Darker = true,
	    Visible = false
	})
	KitCheck = AutoWhisper:CreateToggle({
	    Name = "Kit check",
	    Tooltip = "Only runs while you are using the Whisper kit",
	    Default = true
	})
	
	for _, v: Player in Players:GetPlayers() do
	    AddConnection(v)
	end
	vape:Clean(Players.PlayerAdded:Connect(AddConnection))
end)

Run(function()
	local AutoXurot
	local Range
	local Delay
	local KitCheck
	local DragonForm: boolean = false
	local NextBreath: number = 0
	
	local Breath = bedwars.Handler:Get("DragonBreath")
	
	local function IsLocal(Data)
	    if type(Data) ~= "table" then
	        return true
	    end
	    return Data.player == nil or Data.player == LocalPlayer
	end
	
	AutoXurot = vape.Categories.Kits:CreateModule({
	    Name = "AutoXurot",
	    Function = function(Callback: boolean)
	        if Callback then
	            DragonForm, NextBreath = false, 0
	
	            local Action = bedwars.Handler:Get("VoidDragonAction")
	            if Action.Remote then
	                AutoXurot:Clean(Action.Remote:Connect(function(Data)
	                    if IsLocal(Data) then
	                        if Data.action == "transform" then
	                            DragonForm = true
	                        elseif Data.action == "dragon_deactive" then
	                            DragonForm = false
	                        end
	                    end
	                end))
	            end
	
	            local Deactivate = bedwars.Handler:Get("VoidDragonDeactive")
	            if Deactivate.Remote then
	                AutoXurot:Clean(Deactivate.Remote:Connect(function(Data)
	                    if IsLocal(Data) then
	                        DragonForm = false
	                    end
	                end))
	            end
	
	            AutoXurot:Clean(LocalPlayer.CharacterAdded:Connect(function()
	                DragonForm = false
	            end))
	
	            repeat
	                if DragonForm and Entity.isAlive and (not KitCheck.Enabled or store.hasKit("void_dragon")) and tick() >= NextBreath then
	                    local Target = Entity.EntityPosition({
	                        Origin = Entity.character.RootPart.Position,
	                        Range = Range.Value,
	                        Part = "RootPart",
	                        Players = true,
	                        Wallcheck = true
	                    })
	
	                    if Target then
	                        NextBreath = tick() + Delay.Value
	                        Breath:Fire("SendToServer", {player = LocalPlayer, targetPoint = Target.RootPart.Position})
	                    end
	                end
	                task.wait(0.05)
	            until not AutoXurot.Enabled
	        end
	    end,
	    Tooltip = "Automatically breathes on enemies while you are in dragon form"
	})
	
	Range = AutoXurot:CreateSlider({
	    Name = "Range",
	    Min = 1,
	    Max = 200,
	    Default = 120,
	    Suffix = function(Val: number)
	        return Val <= 1 and "stud" or "studs"
	    end
	})
	Delay = AutoXurot:CreateSlider({
	    Name = "Delay",
	    Min = 0.1,
	    Max = 3,
	    Default = 0.5,
	    Decimal = 10,
	    Suffix = function(Val: number)
	        return Val <= 1 and "sec" or "secs"
	    end
	})
	KitCheck = AutoXurot:CreateToggle({
	    Name = "Kit check",
	    Tooltip = "Only runs while you are using the Xurot kit",
	    Default = true
	})
end)

Run(function()
	local AutoYeti
	local Range
	local Targets
	local KitCheck
	
	AutoYeti = vape.Categories.Kits:CreateModule({
	    Name = "AutoYeti",
