	        Hook = function(Entry, Old)
	            return function(self, Character: Model?, Direction: Vector3?)
	                local Call = Old(self, Character, Direction)
	                local Horizontal: Vector3 = Direction and Direction * Vector3.new(1, 0, 1) or Vector3.zero
	                local Root: BasePart? = Character and Character:FindFirstChild("HumanoidRootPart")
	                if Entry.Toggle.Enabled and (not KitCheck.Enabled or store.hasKit("cat")) and Root and Horizontal.Magnitude > 0 then
	                    Root:ApplyImpulse(Horizontal.Unit * Root.AssemblyMass * (Entry.Multiplier.Value - 1) * 70)
	                end
	                return Call
	            end
	        end
	    },
	    {
