Run(function()
	local DamageIndicator
	local FontOption
	local Color
	local Size
	local Anchor
	local Stroke
	local Success, Settings = pcall(function()
	    return debug.getupvalue(bedwars.DamageIndicator, 2)
	end)
	Settings = Success and Settings or {}
	local OldValues, OldFont = {}
	
	local ConstantCache: {[string]: number} = {}
	
	local function DumpConstant(Search: string)
	    if ConstantCache[Search] then
	        return ConstantCache[Search]
	    end
	
	    for i: number, v: any in debug.getconstants(bedwars.DamageIndicator) do
	        if v and tostring(v):find(Search) then
	            ConstantCache[Search] = i
	            return i
	        end
	    end
	    return nil
	end
	
	DamageIndicator = vape.Legit:CreateModule({
	    Name = "Damage Indicator",
	    Category = "Game",
	    Icon = GetVapeAsset(`{vape.Directory}/assets/new/legit_damageindicator.png`),
	    Function = function(Callback: boolean)
	        if not canDebug then
	            if Callback then
	                DamageIndicator:Clean(vape.Libraries.cheatengine.DamageIndicator.Bind(function()
	                    return {
	                        Font = Enum.Font[FontOption.Value],
	                        Color = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value),
	                        Size = Size.Value,
	                        Anchor = Anchor.Value,
	                        Stroke = Stroke.Enabled
	                    }
	                end))
	            end
	
	            return
	        end
	
	        if Callback then
	            OldValues = table.clone(Settings)
	            OldFont = debug.getconstant(bedwars.DamageIndicator, DumpConstant("Enum.Font"))
	            debug.setconstant(bedwars.DamageIndicator, DumpConstant("Enum.Font"), Enum.Font[FontOption.Value])
	            Settings.strokeThickness = Stroke.Enabled and 1 or 0
	            Settings.textSize = Size.Value
	            Settings.blowUpSize = Size.Value
	            Settings.blowUpDuration = 0
	            Settings.baseColor = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
	            Settings.blowUpCompleteDuration = 0
	            Settings.anchoredDuration = Anchor.Value
	        else
	            for Key: string, v: any in OldValues do
	                Settings[Key] = v
	            end
	            debug.setconstant(bedwars.DamageIndicator, DumpConstant("Enum.Font"), OldFont)
	        end
	    end,
	    Tooltip = "Customize the damage indicator"
	})
	
	local FontItems: {string} = {"GothamBlack"}
	for _, v: EnumItem in Enum.Font:GetEnumItems() do
	    if v.Name ~= "GothamBlack" then
	        table.insert(FontItems, v.Name)
	    end
	end
	FontOption = DamageIndicator:CreateDropdown({
	    Name = "Font",
	    List = FontItems,
	    Function = function(Val: string)
	        if DamageIndicator.Enabled then
	            debug.setconstant(bedwars.DamageIndicator, DumpConstant("Enum.Font"), Enum.Font[Val])
	        end
	    end
	})
	Color = DamageIndicator:CreateColorSlider({
	    Name = "Color",
	    DefaultHue = 0,
	    Function = function(Hue: number, Sat: number, Val: number)
	        if DamageIndicator.Enabled then
	            Settings.baseColor = Color3.fromHSV(Hue, Sat, Val)
	        end
	    end
	})
	Size = DamageIndicator:CreateSlider({
	    Name = "Size",
	    Min = 1,
	    Max = 32,
	    Function = function(Val: number)
	        if DamageIndicator.Enabled then
	            Settings.textSize = Val
	            Settings.blowUpSize = Val
	        end
	    end,
	    Default = 32
	})
	Anchor = DamageIndicator:CreateSlider({
	    Name = "Anchor",
	    Min = 0,
	    Max = 1,
	    Decimal = 10,
	    Function = function(Val: number)
	        if DamageIndicator.Enabled then
	            Settings.anchoredDuration = Val
	        end
	    end
	})
	Stroke = DamageIndicator:CreateToggle({
	    Name = "Stroke",
	    Function = function(Callback: boolean)
	        if DamageIndicator.Enabled then
	            Settings.strokeThickness = Callback and 1 or 0
	        end
	    end
	})
end)

